'    end loop;',
'wwv_flow_collection.create_or_truncate_collection(p_collection_name=>''CLOB_CONTENT'');',
'wwv_flow_collection.add_member(p_collection_name=>''CLOB_CONTENT'',p_clob001=>l_code);',
'sys.htp.prn(''SUCCESS'');',
'end;'))
