begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(4452665082428256.4003)
,p_lov_name=>'FLOW_SUBSCRIBE_FROM_APP_COMPUTATIONS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''|| b.computation_item d,',
'       b.id r',
'  from wwv_flow_computations b,',
'       wwv_main_apps_dev f',
' where b.flow_id          != nvl(:FB_FLOW_ID,0)',
'   and b.flow_id           = f.id',
'   and f.build_status      not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
'   and b.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and f.security_group_id = :FLOW_SECURITY_GROUP_ID',
'order by 1'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'R'
,p_display_column_name=>'D'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
,p_version_scn=>72475151
);
end;
