prompt --application/shared_components/user_interface/lovs/theme_list
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(240131711033281817.4003)
,p_lov_name=>'THEME_LIST'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html( t.theme_name ) ||',
'       '' ('' || ',
'       t.theme_id || ',
'       '') <a href="'' || ',
'       apex_util.prepare_url( p_url => ''f?p=4000:'' || :THEME_NEXT_PAGE  || '':'' ||:APP_SESSION || ''::::P496_THEME:'' || t.id  ) ||',
'       ''"><img src="#IMAGE_PREFIX#f_spacer.gif" class="theme_'' ||',
'       t.theme_id ||',
'       ''"></a>'' display_value,',
'       to_char(t.id) theme_app_id',
'  from wwv_flow_themes t, wwv_flows f ',
' where t.security_group_id in (11,12) ',
'   and (t.THEME_SECURITY_GROUP_ID is null or t.THEME_SECURITY_GROUP_ID = :flow_security_group_id) ',
'   and t.flow_id in (',
'              select id from wwv_flows f',
'               where (',
'                    (:P496_SHOW = ''ALL''      and f.application_type in (''STANDARD'',''THEME'')) or ',
'                    (:P496_SHOW = ''CUSTOM''   and f.application_type = ''STANDARD'') or ',
'                    (:P496_SHOW = ''STANDARD'' and f.application_type = ''THEME'') or',
'                    (:P496_SHOW = ''LEGACY''   and f.application_type = ''THEME'')',
'               ) ',
'               and f.security_group_id in (11,12)',
'               )',
'   and (',
'          (:P496_SHOW = ''STANDARD'' and instr('',''||wwv_flow_platform.get_preference(''TOP_THEMES'')||'','','',''||t.theme_id||'','') > 0 ) or',
'          (:P496_SHOW in (''LEGACY'',''CUSTOM'' ) and instr('',''||wwv_flow_platform.get_preference(''TOP_THEMES'')||'','','',''||t.theme_id||'','') = 0 ) or',
'          (:P496_SHOW = ''ALL'')',
'        )  ',
'   and f.id       = t.flow_id',
'   and f.theme_id = t.theme_id',
' order by t.theme_id'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'THEME_APP_ID'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
,p_version_scn=>72475311
);
end;
