'       from wwv_flow_component_groups w',
'      where w.flow_id = :FB_FLOW_ID',
'        and w.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_component_groups,       ',
'',
'    -- Gen AI Configurations',
'    to_char(nullif( ',
'    (select count(*)',
'       from wwv_flow_ai_configs a',
'      where a.flow_id = :FB_FLOW_ID',
'        and a.security_group_id = :FLOW_SECURITY_GROUP_ID), 0), ''fm999G999G999G999'') as p9_gen_ai_configurations',
'into ',
'    :P9_APP_ITEMS,',
'    :P9_APP_PROCESSES,',
