wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1493543391999991810.4003)
,p_plug_name=>'Hilfe'
,p_region_css_classes=>'a-Dialog-textContent'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4003)
,p_plug_display_sequence=>10
,p_plug_source=>'<big>Der Page Designer ist eine umfassende Integrated Development Environment (IDE), die zur Verwaltung und Erweiterung von Seiten in Ihren &PRODUCT_NAME.-Anwendungen verwendet wird.</big>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104689117393514433.4003)
,p_plug_name=>'Page Designer-Symbolleiste'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810.4003)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Symbolleiste am oberen Rand des Page Designers verf\00FCgt \00FCber eine Reihe von Funktionen:</p>'),
'<ul>',
unistr('  <li><strong>Seitenselektor</strong>: Zeigt die aktuelle Seite an. Sie k\00F6nnen eine Seitennummer direkt eingeben oder auf die Popup-Werteliste klicken, um eine Seite auszuw\00E4hlen. </li>'),
unistr('  <li><strong>Meldungen</strong>: Wenn Sie einer Seite eine neue Komponente hinzuf\00FCgen, werden aktuelle Fehler und Warnungen angezeigt. Durch Klicken auf eine Meldung wechselt der Fokus im Eigenschaftseditor zum entsprechenden Attribut des Fehlers od')
||'er der Warnung.</li>',
unistr('  <li><strong>Seitensperre</strong>: Gibt an, ob die Seite entsperrt (farblos), von Ihnen gesperrt (gr\00FCn) oder von einem anderen Entwickler gesperrt ist (rot mit Person).<br/>'),
unistr('    Wenn Sie auf dieses Symbol klicken, k\00F6nnen Sie die Seite sperren oder entsperren, sofern sie nicht von einem anderen Entwickler gesperrt wurde.</li>'),
unistr('  <li><strong>\00C4nderungen r\00FCckg\00E4ngig machen</strong>: Klicken Sie auf diese Option, um die letzte \00C4nderung in Page Designer r\00FCckg\00E4ngig zu machen.</li>'),
unistr('  <li><strong>\00C4nderungen wiederherstellen</strong>: Klicken Sie auf diese Option, um die letzte mit "\00C4nderungen r\00FCckg\00E4ngig machen" r\00FCckg\00E4ngig gemachte \00C4nderung wiederherzustellen.</li>'),
unistr('  <li><strong>Erstellen</strong>: Neue Seiten erstellen, Seiten kopieren, Regionen erstellen, gemeinsame Komponenten verwalten, Seitengruppen verwalten, Entwicklerkommentare hinzuf\00FCgen und Team Development-Vorg\00E4nge erstellen</li>'),
unistr('  <li><strong>Utilitys</strong>: Seiten l\00F6schen, eine Pr\00FCfung mit Advisor durchf\00FChren, Caching anzeigen, die Seitenhistorie anzeigen, die Seitenpr\00FCfsumme anzeigen, QuickInfos und die Registerkarte "Layout" exportieren, aktivieren oder deaktivieren od')
||'er mit dem Layout zwischen dem Zwei-Fensterbereich-Modus und dem Drei-Fensterbereich-Modus wechseln.<br/></li>',
'  <li><strong>Gemeinsame Komponenten</strong>: Zur Seite "Gemeinsame Komponenten" navigieren.</li>',
unistr('  <li><strong>Speichern</strong>: Alle auf der aktuellen Seite vorgenommenen \00C4nderungen speichern.</li>'),
unistr('  <li><strong>Seite speichern und ausf\00FChren</strong>: Alle \00C4nderungen speichern und die aktuelle Seite ausf\00FChren.<br/>'),
unistr('    <em>Hinweis: Sie k\00F6nnen keine modalen und nicht-modalen Seiten direkt mit "Seite speichern und ausf\00FChren" ausf\00FChren. Stattdessen m\00FCssen Sie zu einer normalen Seite navigieren, die Seite von dort ausf\00FChren und dann in der ausgef\00FChrten Anwendung zu')
||'r modalen oder nicht-modalen Seite navigieren.</em></li>',
'</ul><br/>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1498784482317536966.4003)
,p_plug_name=>'Hauptbereiche'
,p_parent_plug_id=>wwv_flow_imp.id(1493543391999991810.4003)
,p_region_css_classes=>'a-Region--textContent'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Es gibt drei Hauptbereiche innerhalb von Page Designer:</p>',
'<ul>',
unistr('  <li><strong>Linker Bereich</strong>: Umfasst Registerkarten f\00FCr Rendering, dynamische Aktionen, Verarbeitung und gemeinsame Komponenten. Jede Registerkarte zeigt eine Liste der entsprechenden Komponententypen und Komponenten an, die auf der aktuell')
||'en Seite erstellt wurden.<br/>',
unistr('    Klicken Sie mit der rechten Maustaste, um Kontextmen\00FCs aufzurufen. Sie k\00F6nnen Komponenten auch innerhalb des Baumes nach oben oder unten ziehen, um die Position oder Reihenfolge der ausgew\00E4hlten Komponente zu \00E4ndern.</li>'),
unistr('  <li><strong>Mittlerer Bereich</strong>: Umfasst Registerkarten f\00FCr Layout, Seitensuche und Hilfe.<br/>'),
unistr('   <em>Layout</em>: Zeigt eine visuelle Darstellung der Seite an. F\00FCgen Sie neue Seitenkomponenten hinzu, indem Sie mit der rechten Maustaste ein Kontextmen\00FC aufrufen oder indem Sie Komponenten per Drag-and-Drop aus der Registerkarte "Galerie" in die')
||' Registerkarte "Layout" verschieben.<br/>',
unistr('   <em>Seitensuche</em>: Erm\00F6glicht das Durchsuchen aller Seitenmetadaten, einschlie\00DFlich Regionen, Elemente, Schaltfl\00E4chen, dynamische Aktionen, Spalten usw.<br/>'),
unistr('   <em>Hilfe</em>: Zeigt attributspezifische Hilfe an. Klicken Sie im Eigenschaftseditor auf den Attributnamen, um Informationen und Beispiele f\00FCr dieses Attribut anzuzeigen.</li>'),
unistr('  <li><strong>Rechter Bereich</strong>: Zeigt den Eigenschaftseditor an. Mit dem Eigenschaftseditor k\00F6nnen Sie Attribute f\00FCr die ausgew\00E4hlten Komponenten aktualisieren.<br/>'),
unistr('    Wenn Sie mehrere Komponenten im Eigenschaftseditor ausw\00E4hlen, werden nur gemeinsame Attribute angezeigt. Wenn Sie ein gemeinsames Attribut aktualisieren, wird dieses Attribut f\00FCr alle ausgew\00E4hlten Komponenten aktualisiert.</li>'),
'</ul>',
'<p>&nbsp;</p>',
unistr('<p>Sie k\00F6nnen die Gr\00F6\00DFe jedes Bereichs anpassen, indem Sie die horizontalen und vertikalen Splitter ausw\00E4hlen und verschieben. Um einen Bereich ein- oder auszublenden, klicken Sie in der Mitte des Splitters auf das kleine Dreieck mit dem Label <stron')
||'g>Ausblenden</strong>.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_button(
 p_id=>wwv_flow_imp.id(81564783738352513.4003)
,p_button_sequence=>10
,p_button_plug_id=>wwv_flow_imp.id(153764270703903309.4003)
,p_button_name=>'GET_STARTED'
,p_button_action=>'REDIRECT_URL'
,p_button_template_options=>'#DEFAULT#:a-Button--strongLabel'
,p_button_template_id=>wwv_flow_imp.id(183227826797404355.4003)
,p_button_image_alt=>'Erste Schritte'
,p_button_position=>'NEXT'
,p_button_redirect_url=>'javascript:apex.navigation.openInNewWindow(''https://apex.oracle.com/go/get_started_page_designer'');'
,p_button_css_classes=>'a-Button--dark'
);
end;
