wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(116572254618859461.4003)
,p_validation_name=>'unique template name'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P85_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P85_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P85_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_field_templates ft,',
'       central_theme ct',
' where ( ft.flow_id, ft.theme_id, ft.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P85_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and ft.template_name = :F4000_P85_TEMPLATE_NAME',
'   and ft.id           != :F4000_P85_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Templatename muss eindeutig sein'
,p_associated_item=>wwv_flow_imp.id(92679924863336270.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
