,p_plug_name=>'Hilfe'
,p_region_template_options=>'a-Region--noTopBorder:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Der Page Designer stellt verschiedene Optionen zum Erstellen von Seitenkomponenten bereit.',
unistr('Um Regionen, Elemente und Schaltfl\00E4chen zu erstellen, k\00F6nnen Sie Komponenten per Drag-and-Drop innerhalb der Registerkarte "Layout" im zentralen Fensterbereich verschieben, oder k\00F6nnen die Kontextmen\00FCs innerhalb der Registerkarte "Rendering" im linke')
||'n Fensterbereich verwenden.',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'TEXT',
  'show_line_breaks', 'N')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687824864514420.4003)
,p_plug_name=>unistr('Regionen, Elemente und Schaltfl\00E4chen per Drag-and-Drop erstellen')
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4003)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>So verschieben Sie neue Komponenten per Drag-and-Drop:</p>',
'<ol>',
unistr('  <li>W\00E4hlen Sie im zentralen Fensterbereich die Registerkarte "Layout".</li>'),
unistr('  <li>W\00E4hlen Sie innerhalb der Galerie unten im Fensterbereich eine der Optionen "Region", "Element" oder "Schaltfl\00E4che".</li>'),
unistr('  <li>Klicken Sie auf die zu erstellende Komponente, und ziehen Sie sie bei gedr\00FCckter Maustaste in die Registerkarte "Layout".</li>'),
unistr('  <li>Verschieben Sie die Komponente an die gew\00FCnschte Position auf der Seite, und lassen Sie die Maustaste los.</li>'),
'  <li>Geben Sie die entsprechenden Details in den Eigenschaftseditor ein.</li>',
unistr('  <li>Klicken Sie auf <strong>Speichern</strong> oder <strong>Seite speichern und ausf\00FChren</strong>.</li>'),
'</ol>      ',
unistr('<p><em>Hinweis: Komponenten k\00F6nnen nur in entsprechenden Drop-Bereichen (gelb dargestellt) abgelegt werden, die vom Komponententyp bestimmt werden.'),
unistr('  Nachdem Sie den Mauszeiger \00FCber einen vorhandenen Drop-Bereich bewegt haben, \00E4ndert sich der gelbe Bereich in ein schwarzes Feld im entsprechenden Drop-Bereich.<br/>'),
unistr('  Wenn Sie die neue Komponente neben einer vorhandenen Komponente einf\00FCgen m\00F6chten, ziehen Sie die neue Komponente nach rechts, richten Sie sie an der vorhandenen Komponente aus, und warten Sie kurz, bis ein neuer Drop-Bereich angezeigt wird.</em></p')
||'>',
unistr('<p>Die Registerkarte "Layout" enth\00E4lt auch Kontextmen\00FCs. Durch Auswahl einer Komponente und Klicken mit der rechten Maustaste k\00F6nnen Sie die Komponente l\00F6schen, verschieben oder in andere Regionen oder neue Regionen auf der Seite kopieren.</p>'),
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687995506514421.4003)
,p_plug_name=>'Verzweigungen, Berechnungen und Prozesse vor Rendering erstellen'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4003)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>So erstellen Sie Verzweigungen, Berechnungen und Prozesse, die vor dem Rendering der Seite ausgef\00FChrt werden:</p>'),
'<ol>',
unistr('  <li>W\00E4hlen Sie die Registerkarte "Rendering" im linken Fensterbereich.</li>'),
'  <li>Blenden Sie den Knoten <strong>Pre-Rendering</strong> oben im Rendering-Baum ein.</li>',
unistr('  <li>Klicken Sie mit der rechten Maustaste auf "Vor Header", "Nach Header", "Vor Regionen", um das Kontextmen\00FC f\00FCr diesen Verarbeitungspunkt anzuzeigen.</li>'),
unistr('  <li>W\00E4hlen Sie <strong>Verzweigung erstellen</strong>, <strong>Berechnung erstellen</strong> oder <strong>Prozess erstellen</strong>.</li>'),
'  <li>Geben Sie die entsprechenden Details in den Eigenschaftseditor ein.</li>',
unistr('  <li>Klicken Sie auf <strong>Speichern</strong> oder <strong>Seite speichern und ausf\00FChren</strong>.</li>'),
'</ol>',
unistr('<p><em>Hinweis: Wenn Sie die Standardanzeige in Gruppenkomponenten nach Komponententyp ge\00E4ndert haben, m\00FCssen Sie zu der Registerkarte "Verarbeitung" navigieren, um Pre-Rendering-Komponenten zu verwalten.</em></p>'),
unistr('<p>Sie k\00F6nnen auch die Kontextmen\00FCs verwenden, um eine Komponente zu duplizieren, zu l\00F6schen und in andere Seiten zu kopieren.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104688010835514422.4003)
,p_plug_name=>'Seitenweiterleitungsverzweigungen, Validierungen, Berechnungen und Prozesse erstellen'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4003)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>So erstellen Sie Verzweigungen, Validierungen, Berechnungen und Prozesse, die bei der Weiterleitung der Seite ausgef\00FChrt werden:</p>'),
'<ol>',
unistr('  <li>W\00E4hlen Sie die Registerkarte "Verarbeitung" im linken Fensterbereich.</li>'),
'  <li>Navigieren Sie je nachdem zu "Nach Weiterleitung", "Validierung", "Verarbeitung" oder "Nach Verarbeitung" im Verarbeitungsbaum.</li>',
unistr('  <li>Klicken Sie mit der rechten Maustaste auf eine ID oder eine vorhandene Komponente, um das Kontextmen\00FC f\00FCr diesen Verarbeitungspunkt anzuzeigen.</li>'),
unistr('  <li>W\00E4hlen Sie <strong>Verzweigung erstellen</strong>, <strong>Validierung erstellen</strong>, <strong>Berechnung erstellen</strong> oder <strong>Prozess erstellen</strong>.</li>'),
'  <li>Geben Sie die entsprechenden Details in den Eigenschaftseditor ein.</li>',
