wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(18703290019360903.4003)
,p_name=>'P118_CONTENT_IMAGE'
,p_item_sequence=>180
,p_item_plug_id=>wwv_flow_imp.id(4503346701515831.4003)
,p_prompt=>'Bild'
,p_display_as=>'NATIVE_DISPLAY_IMAGE'
,p_tag_attributes=>'style="max-width: 100%;"'
,p_display_when=>'lower(:P118_MIME_TYPE) like ''image/%'''
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_help_text=>'Bildinhalt der Datei'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'SQL',
  'sql_statement', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select file_content as image,',
    '       file_name    as alt_text,',
    '       file_name    as filename,',
    '       mime_type    as mimetype',
    '  from (',
    '        select id, security_group_id, file_content, file_name, mime_type',
    '          from wwv_flow_static_files',
    '         where :P118_SCOPE       = ''APP''',
    '           and flow_id           = :P118_APP_ID',
    '           and security_group_id = :WORKSPACE_ID',
    '           and id                = :P118_ID',
    '',
    '         union all',
    '',
    '        select id, security_group_id, file_content, file_name, mime_type',
    '          from wwv_flow_company_static_files',
    '         where :P118_SCOPE       = ''WORKSPACE''',
    '           and security_group_id = :WORKSPACE_ID',
    '           and id                = :P118_ID',
    '',
    '         union all',
    '',
    '        select id, security_group_id, file_content, file_name, mime_type',
    '          from wwv_flow_plugin_files',
    '         where :P118_SCOPE       = ''PLUGIN''',
    '           and plugin_id         = :P118_PLUGIN_ID',
    '           and security_group_id in ( :WORKSPACE_ID, 11, 12 )',
    '           and id                = :P118_ID',
    '',
    '         union all',
    '',
    '        select id, security_group_id, file_content, file_name, mime_type',
    '          from wwv_theme_files',
    '         where :P118_SCOPE          = ''THEME''',
    '           and current_app_theme_id = :P118_THEME_ID',
    '           and id                = :P118_ID',
    '       );')))).to_clob
);
