,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select t.id,',
'       case',
'            when t.security_group_id in ( 11, 12 ) then m.theme_repository',
'            else to_char( t.flow_id )',
'       end flow_id,',
'       t.name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'', t.name) to_name,',
'       ''N'' Sub',
'  from wwv_flow_templates t,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( t.flow_id, t.theme_id, t.security_group_id ) in',
'       (',
'          ( :F4000_P26_COPY_FROM_FLOW_ID, :P225_COPY_FROM_THEME, :WORKSPACE_ID ),',
'          ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4003)
