,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4003)
,p_plug_display_sequence=>100
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Anwendung konnte nicht installiert werden, weil sie bereits in einem anderen Workspace vorhanden ist. Wenn Sie die Anwendung installieren m\00F6chten, gehen Sie folgenderma\00DFen vor:</p>'),
'<ol>',
'<li>Entfernen Sie die vorhandene Anwendung aus dem Workspace, in dem sie sich aktuell befindet.</li>',
'</ol>',
'ODER',
'<ol>',
unistr('<li>\00C4ndern Sie die Anwendungs-ID in Ihrer Exportdatei. Aktuell ist die Anwendungs-ID &P154_FLOW_ID. verf\00FCgbar.</li>'),
unistr('<li>Laden Sie die ge\00E4nderte Exportdatei im Repository hoch, und installieren Sie Ihre Anwendung neu.</li>'),
'</ol>'))
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_security_group_id number := null;',
'begin',
'  for c1 in (select security_group_id',
'             from wwv_flows',
'             where id = :P49_NEW_FLOW_ID)',
'  loop',
'    l_security_group_id := c1.security_group_id;',
'  end loop;',
'  if l_security_group_id is not null then',
'    if l_security_group_id != :P49_LOGGED_IN_COMPANY then',
'       return true;    ',
'    end if;',
'  end if;',
'  return false;',
'end;'))
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
