,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select l.name as link,',
'      (',
'          select count(*)',
'            from wwv_flow_page_plugs p',
'           where p.list_id           = l.id',
'             and p.flow_id           = l.flow_id',
'             and p.security_group_id = l.security_group_id',
'      ) +',
'      (',
'          select count(*)',
'            from wwv_flow_steps s',
'           where s.navigation_list_id = l.id',
'             and s.flow_id            = l.flow_id',
'             and s.security_group_id  = l.security_group_id',
'      ) +',
'      (',
'          select count(*)',
'            from wwv_flows f',
'           where l.id in (f.navigation_list_id, f.nav_bar_list_id)',
'             and f.id                = l.flow_id',
'             and f.security_group_id = l.security_group_id',
'      ) +',
'      (',
'          select count(*)',
'            from wwv_flow_list_items sl',
'           where sl.sub_list_id       = l.id',
'             and sl.flow_id           = l.flow_id',
'             and sl.security_group_id = l.security_group_id',
'      ) as c,',
'      (',
'          select count(*)',
'            from wwv_flow_list_items li',
'           where li.list_id           = l.id',
'             and li.flow_id           = l.flow_id',
'             and li.security_group_id = l.security_group_id',
'      ) as list_item_count,',
'      l.id as list_id',
'  from wwv_flow_lists l',
' where l.flow_id = :fb_flow_id',
'   and l.security_group_id = :flow_security_group_id',
''))
