wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1403940863419758219.4003)
,p_name=>'P179_RESET_GRID'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(57540512543180628.4003)
,p_item_default=>'ALL'
,p_display_as=>'NATIVE_HIDDEN'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Wenn Sie von einem Theme zu einem anderen wechseln, k\00F6nnen Sie die Regions- und Element-Grid-Einstellungen zur\00FCcksetzen. Die Grid-Einstellungen definieren die Positionierung Ihrer Regionen und Elemente auf einer Seite. Regionen k\00F6nnen nebeneinande')
||unistr('r positioniert werden. Sie k\00F6nnten jedoch auch ein Formular mit zwei oder mehr Elementen auf einer einzelnen Zeile verwenden. Durch das Zur\00FCcksetzen des Grids werden diese Einstellungen entfernt und alle Regionen und Elemente werden vertikal gestapel')
||'t wiedergegeben. </p>',
'',
unistr('<p>Wenn Sie von einem Theme, das ein tabellenbasiertes Grid verwendet, wie Theme 26 (Produktivit\00E4tsanwendungen), zu einem Theme wechseln, das ein DIV-basiertes Grid verwendet, wie Theme 42 (Universal Theme), m\00FCssen Regionen mit einer fixierten Positi')
||unistr('on zur\00FCckgesetzt werden, d.h. die Option "Feste Regionspositionen zur\00FCcksetzen" muss ausgew\00E4hlt werden. </p>'),
'',
unistr('<p>Wenn Sie von einem Theme zu einem anderen wechseln, w\00E4hrend beide Themes denselben Grid-Typ verwenden, ist keine R\00FCcksetzung erforderlich, und die Option " Aktuelle Regions- und Element-Grid-Einstellungen beibehalten" kann ausgew\00E4hlt werden.</p>'),
'',
unistr('<p>Es ist auch m\00F6glich, das Grid f\00FCr alle Regionen und Elemente zur\00FCckzusetzen. Dies wird besonders verwendet, wenn von einem alten Theme zu einem neueren, DIV-basierten Theme gewechselt wird, um die \00C4nderung des Seiten- und Formularlayouts f\00FCr alle ')
||'Seiten vorzubereiten. Beachten Sie, dass bei Auswahl dieser Option alle vorherigen Regions- und Elementpositionseinstellungen verloren sind.</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
