wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(186976606472820937.4003)
,p_name=>'F4000_P188_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(186976325397820915.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Schematyp'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHORIZATION TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHORIZATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHORIZATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHORIZATION TYPE''',
'       )',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Typ f\00FCr Autorisierungsschema ausw\00E4hlen -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Legen Sie fest, wie dieses Autorisierungsschema angewendet wird. Die folgenden integrierten Typen werden unterst\00FCtzt:</p>'),
'<ul>',
unistr('<li><strong>Exists-SQL-Abfrage:</strong> Eine Abfrage, bei der das Autorisierungsschema erfolgreich verl\00E4uft, wenn mindestens eine Zeile zur\00FCckgegeben wird, und nicht erfolgreich, wenn keine Zeilen zur\00FCckgegeben werden.</li>'),
unistr('<li><strong>Not Exists-SQL-Abfrage:</strong> Eine Abfrage, bei der das Autorisierungsschema erfolgreich verl\00E4uft, wenn keine Zeilen zur\00FCckgegeben werden, und nicht erfolgreich, wenn mindestens eine Zeile zur\00FCckgegeben wird.</li>'),
unistr('<li><strong>PL/SQL-Funktion, die Boolean zur\00FCckgibt:</strong> Ein PL/SQL-Funktionsbody, der "true" oder "false" zur\00FCckgibt. Beim Wert "false" verl\00E4uft das Autorisierungsschema nicht erfolgreich. Bei "true" verl\00E4uft es erfolgreich.</li>'),
'<li><strong>Element in Ausdruck 1 ist Null:</strong> Wert des in Ausdruck 1 benannten Elements ist Null.</li>',
'<li><strong>Element in Ausdruck 1 ist nicht Null:</strong>Wert des in Ausdruck 1 benannten Elements ist nicht Null.</li>',
'<li><strong>Wert der Voreinstellung in Ausdruck 1 = Ausdruck 2:</strong> Der Wert der in Ausdruck 1 benannten Voreinstellung entspricht Ausdruck 2.</li>',
'<li><strong>Wert von Voreinstellung in Ausdruck 1 ist nicht gleich Ausdruck 2:</strong> Der Wert der in Ausdruck 1 benannten Voreinstellung entspricht nicht Ausdruck 2.</li>',
'<li><strong>Wert von Element in Ausdruck 1 ist gleich Ausdruck 2:</strong> Der Wert des in Ausdruck 1 benannten Elements entspricht Ausdruck 2.</li>',
'<li><strong>Wert von Element in Ausdruck 1 ist nicht gleich Ausdruck 2:</strong> Der Wert des in Ausdruck 1 benannten Elements entspricht nicht Ausdruck 2</li>',
unistr('<li><strong>Ist in Rolle oder Gruppe:</strong> Vergleicht die angegebenen durch Komma getrennten Rollen-/Gruppennamen mit den Rollen/Gruppen des Benutzers, f\00FCr die die Quelle mit dem Anwendungssicherheitsattribut <strong>Quelle f\00FCr Rollen- oder Grupp')
||'enschemas</strong> konfiguriert ist.',
unistr('<p>Wenn die Quelle auf <em>Benutzerrollenzuweisungen f\00FCr Zugriffskontrolle</em> gesetzt ist, ber\00FCcksichtigt der Autorisierungsprozess nur die erteilten ACL-Rollen des Benutzers.</p>'),
unistr('<p>Andernfalls wird gepr\00FCft, ob die Gruppen als dynamische Gruppen f\00FCr die Session aktiviert sind (siehe APEX_AUTHORIZATION.ENABLE_DYNAMIC_GROUPS). Wenn die Anwendung ein Authentifizierungsschema verwendet, das mit Real Security Application (RAS) kon')
||unistr('figuriert ist, umfasst diese Pr\00FCfung RAS-Sessionrollen. Wenn die Oracle APEX-Accountauthentifizierung verwendet wird, umfasst diese Pr\00FCfung auch Workspace-Gruppen, die dem Benutzer erteilt sind. Wenn die Datenbankauthentifizierung verwendet wird, umf')
||unistr('asst diese Pr\00FCfung auch Datenbankrollen, die dem Benutzer erteilt sind.</p>'),
unistr('<p>Das Autorisierungsschema verl\00E4uft erfolgreich, wenn dem Benutzer eine der genannten Rollen/Gruppen erteilt ist.</p>'),
'</li>',
'<li><strong>Ist nicht in Gruppe:</strong> Gruppe ist nicht aktiviert oder nicht dem Benutzer erteilt. Weitere Einzelheiten finden Sie unter <strong>Ist in Gruppe</strong>.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
