wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1407141969590715.4003)
,p_name=>'P197_AUTO_DISMISS_SUCCESS_MSG'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(72766345492681456.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(28154408216362812.4003)
,p_item_default=>'N'
,p_prompt=>unistr('Erfolgsmeldungen automatisch schlie\00DFen')
,p_source=>'AUTO_DISMISS_SUCCESS_MSG'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Bei <strong>Ein</strong> werden alle Erfolgsmeldungen in dieser Anwendung nach 5 Sekunden automatisch geschlossen. Wenn ein Benutzer mit einer Meldung interagiert, bevor sie geschlossen wird, wird die Zeit zur\00FCckgesetzt, und die Meldung wird erst ')
||'nach weiteren 5 Sekunden geschlossen.</p>',
unistr('<p>Bei <strong>Aus</strong> werden Erfolgsmeldungen so lange angezeigt, bis Anwendungsbenutzer sie manuell schlie\00DFen.</p>'),
unistr('<p>Ber\00FCcksichtigen Sie unbedingt die m\00F6glichen Auswirkungen des automatischen Schlie\00DFens auf die Barrierefreiheit. Einige Benutzer sehen oder lesen eine Erfolgsmeldung m\00F6glicherweise nicht, bevor sie geschlossen wird, und k\00F6nnten so die Informationen')
||unistr(' der Meldung verpassen. Wenn Sie "Automatisch schlie\00DFen" einschalten, sollten Sie \00FCber die apex.message-JavaScript-API mit <code>setDismissPreferences</code> Benutzern Einstellungen bereitstellen, mit denen sie das automatische Schlie\00DFen deaktivieren')
||unistr(' k\00F6nnen.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
