wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(28171558111417124.4003)
,p_name=>'P197_NAV_BAR_TEMPLATE_OPTIONS'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(1329538546154482129.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(28154408216362812.4003)
,p_prompt=>'Templateoptionen'
,p_source=>'NAV_BAR_TEMPLATE_OPTIONS'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.TEMPALTE_OPT_CHECKBOX'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * from (',
'select o.display_name as d,',
'       o.css_classes as r,',
'       t.default_template_options,',
'       t.preset_template_options,',
'       o.help_text,',
'       ( select display_name ',
'           from wwv_flow_template_opt_groups',
'          where id                = o.group_id',
'            and security_group_id = o.security_group_id ) group_name,',
'       ( select is_advanced ',
'           from wwv_flow_template_opt_groups',
'          where id                = o.group_id',
'            and security_group_id = o.security_group_id ) advanced_group',
'  from wwv_flow_template_options o,',
'       wwv_flow_list_templates t',
' where o.list_template_id  =  :P197_NAV_BAR_LIST_TEMPLATE_ID',
'   and o.security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'   and t.id                =  o.list_template_id',
'   and t.security_group_id =  o.security_group_id',
'union all',
'select o.display_name as d,',
'       o.css_classes as r,',
'       null default_template_options,',
'       null preset_template_options,',
'       o.help_text,',
'       ( select display_name ',
'           from wwv_flow_template_opt_groups',
'        where id                = o.group_id',
'            and security_group_id = o.security_group_id ) group_name,',
'       ( select is_advanced ',
'           from wwv_flow_template_opt_groups',
'          where id                = o.group_id',
'            and security_group_id = o.security_group_id ) advanced_group',
'  from wwv_flow_template_options o',
' where ( o.flow_id, o.theme_id, o.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :FB_THEME_ID, :WORKSPACE_ID ),',
'        ( ( select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :FB_THEME_ID ) from sys.dual ),',
'          ( select wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :FB_THEME_ID ) from sys.dual ),',
'          ( select wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :FB_THEME_ID ) from sys.dual ) )',
'       )',
'   and o.virtual_template_id is null',
'   and o.template_types = ''LIST''',
') order by advanced_group nulls first, group_name nulls first, d'))
,p_lov_cascade_parent_items=>'P197_NAV_BAR_LIST_TEMPLATE_ID'
