wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28193838155607550.4003)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Theme Identifier and Navigation Template Ids'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P197_ID := :FB_FLOW_ID;',
'',
'select f.theme_id,',
'       th.theme_internal_name,',
'       th.current_theme_style_id',
'  into :FB_THEME_ID,',
'       :P197_THEME_IDENTIFIER,',
'       :P197_ACTIVE_STYLE',
'  from wwv_flows f,',
'       wwv_flow_themes th',
' where f.id                 = :FB_FLOW_ID',
'   and f.security_group_id  = :WORKSPACE_ID',
'   and th.flow_id           = f.id',
'   and th.security_group_id = f.security_group_id',
'   and th.theme_id          = f.theme_id;',
'',
'if :P197_THEME_IDENTIFIER = ''UNIVERSAL_THEME'' then',
'    begin',
'        select id',
'          into :P197_TOP_TEMPLATE_ID',
'          from wwv_theme_list_templates',
'         where current_app_theme_id = :FB_THEME_ID',
'           and internal_name        = ''TOP_NAVIGATION_MENU'';',
'    exception when no_data_found then',
'        :P197_TOP_TEMPLATE_ID := null;',
'    end;',
'',
'    begin',
'        select id',
'          into :P197_SIDE_TEMPLATE_ID',
'          from wwv_theme_list_templates',
'         where current_app_theme_id = :FB_THEME_ID',
'           and internal_name        = ''SIDE_NAVIGATION_MENU'';',
'    exception when no_data_found then',
'        :P197_SIDE_TEMPLATE_ID := null;',
'    end;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>28193838155607550.4003
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28154588402362813.4003)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(28154408216362812.4003)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize WWV_FLOWS Form'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>28154588402362813.4003
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(253750031521349706.4003)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Icon & Logo Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'    select ',
'        logo,',
'        logo_type,',
'        logo_text',
'    from ',
'        wwv_flows',
'    where',
'        id = :FB_FLOW_ID and',
'        security_group_id = :WORKSPACE_ID',
') loop',
'    :P197_LOGO_TYPE := nvl(c1.logo_type,''NO'');',
'    ',
'    -- Reset all items to null',
'    :P197_LOGO_TEXT := null;',
'    :P197_LOGO_CUSTOM := null;',
'    :P197_LOGO := null;',
'',
'    -- Set page items based on logo type',
'    if c1.logo_type = ''C'' then',
'        :P197_LOGO_CUSTOM := c1.logo;',
'    end if;',
'    ',
'    if c1.logo_type in (''I'',''IT'') then ',
'        :P197_LOGO := c1.logo;',
'    end if;',
'    ',
'    if c1.logo_type in (''T'',''IT'') then ',
'        :P197_LOGO_TEXT := c1.logo_text;',
'    end if;',
'    ',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>253750031521349706.4003
);
end;
