wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(77942616804912740.4003)
,p_name=>'F4000_P204_TEMPLATE'
,p_is_required=>true
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(77971829434098596.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Normales Template'
,p_source=>'TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>40
,p_cMaxlength=>4000
,p_cHeight=>8
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Definiert das Schaltfl\00E4chentemplate, das beim Schaltfl\00E4chentyp "Normal" angezeigt wird. Sie k\00F6nnen Standardanwendungsersetzungen einbeziehen. Beispiel: &amp;ITEM_NAME.-Werte k\00F6nnen beim Rendering ersetzt werden.</div>'),
unistr('<div class="htmldbInfoBodyP">Schaltfl\00E4chentemplates unterst\00FCtzen die folgenden Ersetzungszeichenfolgen:'),
'<ul class="noIndent">',
unistr('<li><code>#LABEL#</code> wird durch ein Schaltfl\00E4chenlabel ersetzt.</li>'),
unistr('<li><code>#LINK#</code> wird durch generierten JavaScript-Code ersetzt, um das Verhalten der Schaltfl\00E4che zu steuern. Je nach Aktion einer Schaltfl\00E4che kann dieser Code ein Aufruf von <code>apex.submit</code> zur Weiterleitung der Seite, ein <code>re')
||unistr('direct</code> zu einer Seite, ein <code>redirect</code> zu einer anderen angegebenen URL, Ausf\00FChrung eines benutzerdefinierten JavaScripts oder <code>void(0)</code> f\00FCr keine weitere Aktion sein (wobei das Verhalten separat mit dynamischen Aktionen d')
||'efiniert werden kann). Hinweis: <code>#LINK#</code> stellt dem generierten JavaScript-Code "javascript:" voran und sollte daher in einem <code>href</code>-Attribut verwendet werden.</li>',
unistr('<li><code>#JAVASCRIPT#</code> wird durch generierten JavaScript-Code ersetzt, um das Verhalten der Schaltfl\00E4che zu steuern. Je nach Aktion einer Schaltfl\00E4che kann dieser Code ein Aufruf von <code>apex.submit</code> zur Weiterleitung der Seite, ein <c')
||unistr('ode>redirect</code> zu einer Seite, ein <code>redirect</code> zu einer anderen angegebenen URL, Ausf\00FChrung eines benutzerdefinierten JavaScripts oder <code>void(0)</code> f\00FCr keine weitere Aktion sein (wobei das Verhalten separat mit dynamischen Akti')
||'onen definiert werden kann). ',
'<p><strong>Hinweis</strong>: <code>#JAVASCRIPT#</code> stellt dem generierten JavaScript-Code nicht "javascript:" voran und sollte daher in einem <code>onclick</code>-Attribut verwendet werden.</li>',
unistr('<li><code>#ONCLICK#</code> gibt an, dass die Schaltfl\00E4che ein OnClick-Ereignis mit JavaScript-Code hat, das unten auf der Seite in ein Skripttag aufgenommen wird.</li>'),
unistr('<li><code>#BUTTON_ID#</code> wird durch die ID f\00FCr die Schaltfl\00E4che ersetzt. Hierbei handelt es sich entweder um die statische ID der Schaltfl\00E4che, sofern definiert, oder um eine intern generierte ID im Format <pre>''B'' || [Interne Schaltfl\00E4chen-ID]</')
||'pre></li>',
unistr('<li><code>#BUTTON_CSS_CLASSES#</code> wird durch die Schaltfl\00E4chen-CSS-Klasseneigenschaft aus der Schaltfl\00E4chendefinition ersetzt.</li>'),
unistr('<li><code>#BUTTON_ATTRIBUTES#</code> wird durch die Schaltfl\00E4chenattributeigenschaft aus der Schaltfl\00E4chendefinition ersetzt.</li>'),
unistr('<li><code>#ICON_CSS_CLASSES#</code> wird durch die Symbol-CSS-Klasseneigenschaft aus der Schaltfl\00E4chendefinition ersetzt.</li>'),
unistr('<li><code>#BUTTON_NAME#</code> wird durch den Namen der Schaltfl\00E4che aus der Schaltfl\00E4chendefinition ersetzt.</li>'),
'</ul>',
'</div>',
unistr('<div class="htmldbInfoBodyP">Alle Ersetzungszeichenfolgen m\00FCssen in Gro\00DFbuchstaben angegeben werden.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
,p_item_comment=>'Generated 17-JUL-2002 17:42:24'
);
