,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(212879727923324936)
,p_step_template=>wwv_flow_imp.id(689065306389965836.4003)
,p_page_template_options=>'#DEFAULT#'
,p_dialog_attributes=>'minWidth:500,minHeight:400'
,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'ui_templt.htm'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(79037325082006306.4003)
,p_name=>unistr('Schaltfl\00E4chen-Template erstellen')
,p_template=>wwv_flow_imp.id(42025417508627628.4003)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select bt.id,',
'       case',
'           when bt.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( bt.flow_id )',
'       end flow_id,',
'       bt.template_name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'',bt.template_name) to_name,',
'       ''N'' Sub',
'  from wwv_flow_button_templates bt,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( bt.flow_id, bt.theme_id, bt.security_group_id ) in',
'       (',
'        ( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4003)
,p_query_num_rows=>500
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'(null)'
,p_query_break_cols=>'0'
,p_query_no_data_found=>unistr('<font class="fielddata">Keine Schaltfl\00E4chen-Templates gefunden.</font>')
,p_query_num_rows_type=>'ROWS_X_TO_Y_OF_Z'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
