,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P241_COPY_FROM_FLOW_ID, :P415_COPY_FROM_THEME ) as application_id,',
