wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(290023816157198599.4003)
,p_validation_name=>'NoDupeNames'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_found_name  varchar2(2000);',
'    l_theme_refs  wwv_flow_theme.t_refs;',
'begin',
'    l_theme_refs := wwv_flow_theme.get_refs_dev(',
'                        p_application_id => :FB_FLOW_ID );',
'',
'    for i in 1..wwv_flow.g_f01.count loop',
'        if wwv_flow.g_f03(i) in (''Y'',''SUBSCRIBE'') then',
'            for c1 in ( select name',
'                          from wwv_flow_menu_templates',
'                         where ( flow_id, security_group_id ) in',
'                                  ( ( l_theme_refs(1).app_id, l_theme_refs(1).sgid ),',
'                                    ( l_theme_refs(2).app_id, l_theme_refs(2).sgid ) )',
'                           and name = wwv_flow.g_f02(i) )',
'            loop',
'                if c1.name is not null then',
'                    if l_found_name is null then',
'                        l_found_name := c1.name;',
'                    else',
'                        l_found_name := l_found_name||'', ''||c1.name;',
'                    end if;',
'                end if;',
'            end loop;',
'        end if;',
'    end loop;',
'',
'    if l_found_name is not null then',
'        return wwv_flow_lang.system_message(''F4000.TEMPLATE_NAME_ALREADY_EXISTS'',',
'                    l_found_name);',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(14344019270246074.4003)
