wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(56432910873347879.4003)
,p_validation_name=>'version must be compatible'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_runtime_version varchar2(200); -- the date of the current runtime flows',
'  l_calling_version varchar2(200);',
'begin',
'    l_calling_version := replace(replace(replace(wwv_flow_imp_parser.get_version (p_file_id => :p253_file_id),''.'',null),''_'',null),''/'',null);',
'    l_runtime_version := replace(replace(replace(wwv_flows_version,''.'',null),''_'',null),''/'',null);',
'',
'    if l_calling_version > l_runtime_version then',
'        --',
'        -- version incompatability        ',
'        --',
'        ',
'        return false;',
'    else',
'        return true;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Nicht kompatibel (Ihr Import enth\00E4lt m\00F6glicherweise Aufrufe, die von Ihrer Anwendungsversion nicht unterst\00FCtzt werden.)')
,p_when_button_pressed=>wwv_flow_imp.id(47638615358532854.4003)
,p_associated_item=>wwv_flow_imp.id(56513630434665841.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(46353812810485581.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'install theme'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare l_create_theme boolean :=false;',
'begin',
'  if :P253_INSTALL_OPTION = ''CREATE'' then',
'    l_create_theme := true;',
'  end if;',
'  for c1 in (select owner from wwv_flows ',
'             where id              = :P253_NEW_FLOW_ID ',
'             and security_group_id = :flow_security_group_id) loop',
'      wwv_flow_imp_parser.parse (',
'         p_file_id          => :P253_FILE_ID,',
'         p_parse_as_schema  => c1.owner,',
'         p_install_as_flow  => :P253_NEW_FLOW_ID,',
'         p_original_flow_id => wwv_flow_imp_parser.get_flow_id(:P253_FILE_ID),',
'         p_adjust_offset    => true,',
'         p_create_theme     => l_create_theme',
'         );',
'  end loop;',
'  :FB_FLOW_ID := :P253_NEW_FLOW_ID;',
'  :F4000_P1_FLOW := :P253_NEW_FLOW_ID;',
'  :F4000_P1_PAGE := ''1'';',
'',
'  :P253_NEW_THEME_PK  := null;',
'  for c1 in (select id from wwv_flow_themes ',
'              where flow_id           = :P253_NEW_FLOW_ID ',
'                and theme_id          = wwv_flow.g_flow_theme_id',
'                and security_group_id = :WORKSPACE_ID ) loop',
'      :P253_NEW_THEME_PK := c1.id;',
'  end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Fehler beim Installieren von Theme.'
,p_process_when=>'INSTALL:REPLACE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'Theme installiert.'
,p_internal_uid=>46353812810485581.4003
);
end;
