,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Definiert das Spaltentemplate. Sie k\00F6nnen hier folgende Ersetzungszeichenfolgen verwenden:'),
'<ul class="noIndent">',
'<li>#COLUMN_VALUE#: Wird durch den Wert einer Spalte ersetzt</li>',
'<li>#ALIGNMENT#: Wird vom Benutzer angegeben und bestimmt die Ausrichtung einer Spalte</li>',
'<li>#COLNUM#: Aktuelle Spaltennummer</li>',
'<li>#COLUMN_HEADER#: Spaltenheader</li>',
'<li>#COLCOUNT#: Anzahl der Spalten</li>',
'<li>#ROWNUM#: Aktuelle Zeilennummer',
unistr('<li>#ACCESSIBLE_HEADERS#: F\00FCgt die Zeilen- und Spaltenheader f\00FCr die Zelle hinzu</li>'),
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">Typisches Beispiel:</div>',
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>',
'',
unistr('<div class="instructiontext">Sie k\00F6nnen bis zu vier Spaltentemplates definieren, die jeweils auf Bedingungen basieren k\00F6nnen. Beispiel: Sie k\00F6nnen unterschiedliche Hintergrundfarben f\00FCr gerade und ungerade Zeilen verwenden oder Zeilen hervorheben, di')
||unistr('e eine definierte PL/SQL-Bedingung erf\00FCllen.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
