,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den HTML-Code ein, der einmal am Anfang eines Berichtstemplates angezeigt wird.</p>',
unistr('<p>Dieses Attribut wird am H\00E4ufigsten verwendet, um eine HTML-Tabelle zu \00F6ffnen:</p>'),
'<pre>&lt;table&gt;</pre>',
unistr('<p>Wenn \00FCber den Berichten eine Paginierung angezeigt werden soll, muss die folgende Ersetzungszeichenfolge im Template angegeben werden:</p>'),
'<pre>#TOP_PAGINATION#</pre>',
unistr('<p>Die #TOP_PAGINATION#-Ersetzungszeichenfolge generiert einen HTML-Code, der mit einem \00F6ffnenden &lt;tr&gt;-Tag beginnt und mit einem schlie\00DFenden &lt;/tr&gt;-Tag endet. Im Idealfall w\00FCrden Sie ein \00F6ffnendes Tabellen-Tag und eine #TOP_PAGINATION#-Er')
||'setzungszeichenfolge wie folgt angeben:</p>',
'<pre>&lt;table&gt;#TOP_PAGINATION#</pre>',
unistr('<p>Sie k\00F6nnen auch die Ersetzungszeichenfolge #CSV_LINK# angeben, wenn der Export des Berichts im CSV-Format zur Verwendung in Arbeitsbl\00E4ttern unterst\00FCtzt werden soll.</p>'),
unistr('<p>Sie k\00F6nnen auch die Ersetzungszeichenfolge #REPORT_ATTRIBUTES# verwenden. Diese Ersetzungszeichenfolge wird pro Berichtsregion auf der Seite mit den Berichtsattributen festgelegt.'),
unistr('<p>Sie k\00F6nnen auch die Ersetzungszeichenfolge #COMPONENT_CSS_CLASSES# verwenden. Diese Ersetzungszeichenfolge wird auf der Seite zur Regionsbearbeitung festgelegt.</p>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
