wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1284198878924776853.4003)
,p_name=>'P267_CUSTOM_LIBRARY_FILE_URLS'
,p_item_sequence=>380
,p_item_plug_id=>wwv_flow_imp.id(1253547956481954904.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'URLs der benutzerdefinierten Library-Datei'
,p_source=>'CUSTOM_LIBRARY_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>80
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_css_classes=>'a-Form-fieldContainer--fieldsetBlock'
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie CSS-Datei-URLs f\00FCr benutzerdefinierte Symbole an, die auf jeder Seite geladen werden sollen. Jede URL muss in eine neue Zeile geschrieben werden. Wenn Sie eine minimierte Version der Datei angeben, k\00F6nnen Sie die Ersetzungszeichenfolge <')
||unistr('code>#MIN#</code> oder <code>#MIN_DIRECTORY#</code>verwenden, um <code>.min</code> bzw. <code>minified/</code> in der Datei-URL f\00FCr eine regul\00E4re Seitenansicht aufzunehmen, bzw. eine leere Zeichenfolge, wenn die Seite im Debugmodus angezeigt wird. Si')
||unistr('e haben au\00DFerdem Zugriff auf die Ersetzungszeichenfolge <code>#APP_VERSION#</code>, wenn Sie die Version der Anwendung in die Datei-URL aufnehmen m\00F6chten.</p>'),
'',
'<p>Die Ersetzungszeichenfolge <code>#THEME_CSS#</code> wird durch die hier eingegebenen Datei-URLs im Seitentemplate ersetzt.</p>',
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>link</code>-Tags aufnehmen. Nehmen Sie einfach die Datei-URL auf.</p>'),
'',
'<p>',
'Beispiele:',
'<ul>',
unistr('  <li>Standarddateireferenz, die die Datei aus dem Theme-Verzeichnis l\00E4dt.'),
'      <pre>#THEME_IMAGES#icons.css</pre>',
'  </li>',
unistr('  <li>Standarddateireferenz, die die minimierte Datei main.min.css aus /mycss/minified/ f\00FCr regul\00E4re Seitenansichten und main.css aus /mycss/ im Debugmodus l\00E4dt.'),
'      <pre>/mycss/#MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
'  <li>Bedingte Medienabfrage:',
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone.css</pre>',
'  </li>',
unistr('  <li>Dateireferenz mit einer Abfragezeichenfolge in der URL, die die Anwendungsversion referenziert, sodass der Browser beim Upgrade der Anwendung (und Erh\00F6hen der Version) die neue Datei l\00E4dt und alle zuvor gecachten Dateien ignoriert:'),
'      <pre>/mycss/icons.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1284811815656337680.4003)
,p_name=>'P267_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>420
,p_item_plug_id=>wwv_flow_imp.id(1253548287352954907.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'URLs der JavaScript-Datei'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>64
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_css_classes=>'a-Form-fieldContainer--fieldsetBlock'
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie JavaScript-Datei-URLs f\00FCr Code ein, der auf jeder Seite geladen werden soll. Jede URL muss in einer eigenen Zeile stehen. Wenn Sie eine minimierte Version der Datei angeben, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#MIN#</code> oder <')
||unistr('code>#MIN_DIRECTORY#</code> verwenden, um <code>.min</code> bzw. <code>minified/</code> in der Datei-URL f\00FCr eine regul\00E4re Seitenansicht aufzunehmen, bzw. eine leere Zeichenfolge, wenn die Seite im Debug-Modus angezeigt wird.</p>'),
'',
'<p>JavaScript-Datei-URLs, die Sie hier eingeben, ersetzen die Ersetzungszeichenfolge <code>#THEME_JAVASCRIPT#</code> im Seitentemplate.</p>',
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>script</code>-Tags einbeziehen. Schreiben Sie einfach die URL.'),
'',
'<p>',
'Beispiele:',
'<ul>',
unistr('  <li>Standarddateireferenz, die die Datei aus dem Theme-Verzeichnis l\00E4dt:'),
'      <pre>#THEME_IMAGES#main.js</pre>',
'  </li>',
unistr('  <li>Standarddateireferenz, die die minimierte Datei main.min.js aus /myjs/minified/ bei regul\00E4ren Seitenansichten und main.js aus /myjs/ im Debug-Modus l\00E4dt:'),
'      <pre>/myjs/#MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Library auch aus einem Require-Aufruf "RequireJS" verwendet wird. Der Define-Name muss mit den Angaben in den requirejs.config-Pfaden \00FCbereinstimmen, und der Wert muss das globale Symbol sein, das von der Li')
||unistr('brary verf\00FCgbar gemacht wird. Gilt nur, wenn RequireJS verwendet wird. Dadurch wird verhindert, dass RequireJS diese Library ein zweites Mal l\00E4dt.'),
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Datei von RequireJS abh\00E4ngig ist. Dadurch wird RequireJS automatisch vor dieser Datei geladen.'),
'      <pre>[require requirejs]/myjs/main.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Datei von Oracle JET abh\00E4ngig ist. Dadurch werden RequireJS und die Oracle JET RequireJS-Konfiguration automatisch vor dieser Datei geladen.'),
'      <pre>[require jet]/myjs/main.js</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
