'declare',
'  l_file_id number := null;',
'begin',
'  for c1 in (select id',
'             from wwv_flow_file_objects$',
'             where name = :P460_FILE',
'               and security_group_id = :WORKSPACE_ID)',
'  loop',
'     l_file_id := c1.id;',
'  end loop;',
'',
'  -- set 4460 file id item based if it''s a app, page, or component export',
'  if :P460_FILE_TYPE = ''FLOW_EXPORT'' then',
'     :P460_FILE_ID := l_file_id;',
'  end if;',
'',
'  :P163_FILE_ID := l_file_id;',
'end;'))
