,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Das install-Ereignis der Service-Worker-Schnittstelle wird ausgel\00F6st, sobald der Worker ausgef\00FChrt wird. Es wird nur einmal je Service-Worker aufgerufen.</p>'),
unistr('<p>Sie k\00F6nnen damit einen Cache mit einer Reihe von Ressourcen auff\00FCllen, die der Service-Worker dann zum Bereitstellen von Assets verwendet.</p>'),
'<p>Weitere Informationen:</p>',
'<ul>',
'    <li><a rel="noopener noreferrer" href="https://developer.mozilla.org/en-US/docs/Web/API/ServiceWorkerGlobalScope/install_event">https://developer.mozilla.org/en-US/docs/Web/API/ServiceWorkerGlobalScope/install_event</a></li>',
