,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Anzeige bestimmt den bevorzugten Anzeigemodus f\00FCr die Anwendung.</p>'),
'<p>Der Anzeigemodus legt fest, welcher Bereich der Browser-UI angezeigt wird.</p>',
