,p_post_element_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="u-textCenter margin-top-md">',
'<input id="APEXCropperZoom" type="range" min="0" max="100" value="0" step="1">',
'<label class="u-vh" for="APEXCropperZoom">&P508_ZOOM_SLIDER_LABEL.</label>',
'</div>'))
,p_display_as=>'NATIVE_DISPLAY_IMAGE'
,p_display_when=>'P508_INIT_CROPPER_YN'
,p_display_when2=>'Y'
,p_display_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(4923925522744860.4003)
,p_item_template_options=>'#DEFAULT#'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'SQL',
  'sql_statement', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select blob_content as blob_content,',
    '       name         as alt_text,',
    '       filename     as filename,',
    '       mime_type    as mime_type',
    '  from wwv_flow_temp_files ',
    ' where name = :p508_file_browse',
    '   and :p508_file_browse is not null',
    '',
    ' union all',
    '',
    'select sf.file_content as blob_content,',
    '       :p508_name     as alt_text,',
    '       sf.file_name    as filename,',
    '       sf.mime_type    as mime_type',
    '  from wwv_flow_pwa_shortcuts ps,',
    '       wwv_flow_static_files sf',
    ' where ps.security_group_id = :workspace_id',
    '   and ps.flow_id           = :fb_flow_id',
    '   and ps.id                = :p508_id',
    '   and sf.security_group_id = ps.security_group_id',
