wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005.4003)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Konfigurationsprozedur'
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den Namen einer Prozedur ein, die die Authentifizierung zur Laufzeit konfiguriert.',
unistr('Der Code unten ist f\00FCr eine Anwendung bestimmt, die Mehrmandantenf\00E4higkeit implementiert und'),
unistr('verschiedene <em>Social-Sign-In</em>-Varianten f\00FCr die Mandanten unterst\00FCtzt.'),
unistr('Dabei wird der Domainname in der URL f\00FCr den Abruf der Konfigurationsdaten verwendet (Beispiel-URLs: '),
'https://cust-01.example.com, https://cust-02.example.com, ...):',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
unistr('Die Prozedur kann 3 Attribute des in/out-Parameters <code>p_conf</code> \00E4ndern,'),
'alle davon optional:',
'<ul>',
'    <li><code>authentication_name</code>:',
'    Weisen Sie den Namen eines Authentifizierungsschemas in Ihrer Anwendung zu,',
'    das anstelle des Standardschemas verwendet wird.',
unistr('    F\00FCr dieses Schema muss die Option <em>In Session wechseln</em> aktiviert sein.'),
'    </li><li><code>substitutions</code>:',
'    Weisen Sie Name/Wert-Paare mit <code>apex_t_varchar2</code> zu.',
'    &PRODUCT_NAME. ersetzt jedes Vorkommen von <code>#NAME#</code> in den Attributen des ',
unistr('    Authentifizierungsschemas durch den verkn\00FCpften Wert.'),
'    Das integrierte <em>Social-Sign-In</em>-Schema verwendet <code>CREDENTIAL_STATIC_ID</code>,',
'    um den entsprechenden Zugangsdatenspeicher anstelle des ',
'    im Schema konfigurierten',
'    zu verwenden.',
'    </li><li><code>tenant_id</code>:',
'    Legen Sie diese Mandanten-ID in der Session fest (siehe <code>apex_session.set_tenant_id</code>).',
'    </li>',
'</ul>',
'</p><p>',
'In Anwendungen mit einer Prozedur zur Authentifizierungskonfiguration',
