wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203001185706981.4003)
,p_name=>'P509_PAGE_PROTECTION_ENABLED'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>unistr('Schutz f\00FCr den Sessionzustand')
,p_source=>'PAGE_PROTECTION_ENABLED_Y_N'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Wenn Sie <strong>Aktiviert</strong> ausw\00E4hlen, werden die Seitenattribute zum Schutz f\00FCr den Seitenzugriff und die Elementattribute zum Schutz f\00FCr den Sessionzustand in Verbindung mit Pr\00FCfsummen in </code>f?p=</code>-URLs')
||unistr(' verwendet. Wenn Sie dieses Feature aktivieren, k\00F6nnen URLs und der Sessionzustand nicht von unberechtigten Benutzern ge\00E4ndert bzw. aufgerufen werden.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Wenn Sie <strong>Deaktiviert</strong> ausw\00E4hlen, werden die Seitenattribute zum Schutz f\00FCr den Seitenzugriff und die Elementattribute zum Schutz f\00FCr den Sessionzustand von der &PRODUCT_NAME.-Engine nicht w\00E4hrend der Ausf\00FC')
||unistr('hrung Ihrer Anwendung verwendet. Au\00DFerdem werden keine Pr\00FCfsummen in den </code>f?p=</code>-Bereich der URLs einbezogen.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Wenn Sie dieses Attribut von <strong>Aktiviert</strong> in <strong>Deaktiviert</strong> \00E4ndern, wird der Schutz f\00FCr den Sessionzustand deaktiviert. Die Einstellung f\00FCr die Seitenattribute zum Schutz f\00FCr den Seitenzugriff ')
||unistr('und die Elementattribute zum Schutz f\00FCr den Sessionzustand wird jedoch nicht ge\00E4ndert. Wenn Sie das Attribut von <strong>Deaktiviert</strong> in <strong>Aktiviert</strong> \00E4ndern, wird der Schutz f\00FCr den Sessionzustand aktiviert. Die Einstellung f\00FCr ')
||unistr('die Seitenattribute zum Schutz f\00FCr den Seitenzugriff und die Elementattribute zum Schutz f\00FCr den Sessionzustand bleibt unber\00FChrt, und die Attribute werden w\00E4hrend der Ausf\00FChrung der Anwendung beobachtet.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Die Elementattribute zum Schutz f\00FCr den Sessionzustand sind nur dann aktiv, wenn f\00FCr den Schutz des Sessionzustand die Einstellung <strong>Aktiviert</strong> festgelegt ist, falls f\00FCr ein Elementattribut <strong>Gesch\00FCtzt')
||unistr('</strong> festgelegt wird. In diesem Fall ist dieser Zustand immer g\00FCltig. Anders ausgedr\00FCckt: Gesch\00FCtzte Elemente k\00F6nnen - ungeachtet des Schutzes f\00FCr den Sessionzustand(<strong>Aktiviert</strong> oder <strong>Deaktiviert</strong>) in der URL nicht ')
||unistr('ge\00E4ndert werden.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203519523706982.4003)
,p_name=>'P509_CHECKSUM_SALT_LAST_RESET'
,p_item_sequence=>220
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008.4003)
