,p_item_template_options=>'#DEFAULT#'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP"><strong>URLs zulassen, die nach dem folgenden Datum erstellt wurden</strong> f\00FChrt Datum und Uhrzeit auf, nach denen Links mit Lesezeichen f\00FCr den Zugriff auf Seiten in dieser Anwendung verwendbar sind, wenn der \00FCber ein ')
||unistr('Lesezeichen abrufbare Link eine Pr\00FCfsumme enth\00E4lt und der Schutz f\00FCr den Sessionzustand dieser Anwendung aktiviert ist. '),
'<p>',
unistr('Lesezeichen, die vor dieser Datums-/Zeitangabe erstellt wurden, k\00F6nnen nicht f\00FCr den Zugriff auf diese Anwendung verwendet werden, wenn der \00FCber ein Lesezeichen abrufbare Link eine Pr\00FCfsumme enth\00E4lt und der Schutz f\00FCr den Sessionzustand f\00FCr diese Anw')
||'endung aktiviert ist.',
'<p>',
unistr('Lesezeichen, die keine Pr\00FCfsummen enthalten, oder Lesezeichen mit nicht erforderlichen Pr\00FCfsummen sind von diesem Attribut nicht betroffen. Die Verwendbarkeit derartiger Lesezeichen wird von anderen Kriterien bestimmt.'),
'<p>',
unistr('Ein ausgeblendetes Anwendungsattribut (Pr\00FCfsumme Salt) wird bei der Berechnung und sp\00E4teren Verifizierung von Pr\00FCfsummen verwendet, die in <code>f?p=</code> URLs enthalten sind, die bei der Seitenanzeige generiert werden. Pr\00FCfsummen werden einbezogen')
||unistr(', wenn der Schutz f\00FCr den Sessionzustand f\00FCr die Anwendung aktiviert ist. Sie k\00F6nnen dieses Pr\00FCfsumme Salt-Attribut jederzeit durch Klicken auf die Schaltfl\00E4che <strong>Lesezeichens verfallen</strong> zur\00FCcksetzen. In diesem Fall werden alle \00FCber ein')
||unistr(' Lesezeichen abrufbaren URLs, die zuvor generierte Pr\00FCfsummen enthalten, nicht mehr erfolgreich ausgef\00FChrt, wenn sie sp\00E4ter f\00FCr den Zugriff auf die Anwendung verwendet werden.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'VALUE',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
