wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(384789975408553245.4003)
,p_name=>'P509_REJOIN_EXISTING_SESSIONS'
,p_is_required=>true
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(6354406057147715.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Sessions erneut beitreten'
,p_source=>'REJOIN_EXISTING_SESSIONS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'REJOIN_EXISTING_SESSIONS'
,p_lov=>'.'||wwv_flow_imp.id(492680965578161495)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Mit diesem Attribut k\00F6nnen Sie festlegen, ob &PRODUCT_NAME. Anwendungs-URLs unterst\00FCtzen soll, die keine Session-IDs enthalten.'),
unistr('Wenn "Sessions erneut beitreten" aktiviert ist, versucht  &PRODUCT_NAME. das Sessioncookie f\00FCr den Beitritt bei einer vorhandenen Session zu verwenden,'),
unistr('wenn eine URL keine Session-ID enth\00E4lt.'),
'</p>',
'<p>',
unistr('Eine restriktivere Einstellung auf Instanzebene setzt diesen Wert auf Seitenebene au\00DFer Kraft.'),
'</p>',
'<p>',
'    <strong>Hinweis:</strong>',
unistr('Die Aktivierung von "Sessions erneut beitreten" setzt Ihre Anwendung m\00F6glichen Sicherheitsverletzungen aus, da Angreifer vorhandene Endbenutzersessions \00FCbernehmen k\00F6nnen. Weitere Informationen finden Sie in den "Rejoin Sessions"-Abschnitten in "Manag')
||'ing Application Security" im App Builder User''s Guide.',
'</p>',
'',
'<p>',
unistr('Verf\00FCgbare Optionen umfassen:    '),
'</p>',
'<ul>',
'    <li><strong>Anwendungsstandardwert</strong> - ',
'    Die Einstellung auf Anwendungsebene wird angewendet.',
'    </li>',
'    <li><strong>Deaktiviert</strong> - ',
unistr('    Wenn die URL keine Session-ID enth\00E4lt, erstellt &PRODUCT_NAME. eine neue Session.'),
'    </li>',
unistr('    <li><strong>F\00FCr \00F6ffentliche Sessions aktiviert</strong> - '),
unistr('    Wenn die URL zu einer \00F6ffentlichen Seite f\00FChrt und keine Session-ID enth\00E4lt,'),
unistr('    versucht &PRODUCT_NAME., das vorhandene Sessioncookie zu nutzen, das f\00FCr diese Anwendung festgelegt wurde.'),
unistr('    Bei Anwendungen mit \00F6ffentlichen und authentifizierten Seiten wird nach der Authentifizierung des Endbenutzers eine Session-ID definiert.'),
'    &PRODUCT_NAME. tritt nur mit dem Cookie bei, wenn die Session noch nicht authentifiziert ist.',
'    </li>',
unistr('    <li><strong>F\00FCr alle Sessions aktiviert</strong> - '),
unistr('    Wenn die URL keine Session-ID enth\00E4lt, versucht &PRODUCT_NAME., das vorhandene Sessioncookie zu nutzen, das f\00FCr diese Anwendung festgelegt wurde,'),
unistr('    vorausgesetzt die folgenden Bedingungen werden erf\00FCllt:'),
'    <ul>',
'        <li>',
unistr('        Schutz f\00FCr den Sessionzustand ist f\00FCr die Anwendung aktiviert und die URL enth\00E4lt eine g\00FCltige Pr\00FCfsumme.'),
unistr('        Bei \00F6ffentlichen Lesezeichen'),
unistr('        muss der restriktivste Schutz auf Elementebene <em>Uneingeschr\00E4nkt</em> oder <em>Pr\00FCfsumme erforderlich - Anwendungsebene</em> sein.'),
'        </li>',
'        <li>',
unistr('        ODER die URL enth\00E4lt keine Payload (Anforderungsparameter, Cacheinhalt l\00F6schen (Clear-Cache) oder Datenwertpaare).'),
'        </li>',
'    </ul>',
unistr('    Diese Einstellung erfordert au\00DFerdem, dass "In Frames einbetten " auf "Aus selbem Ursprung zulassen" oder "Ablehnen" f\00FCr die Anwendung festgelegt ist.'),
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
