wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(875823623343323717.4003)
,p_name=>'P509_BROWSER_CACHE'
,p_is_required=>true
,p_item_sequence=>240
,p_item_plug_id=>wwv_flow_imp.id(875541626713267923.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Cache'
