wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1098121125859208369.4003)
,p_name=>'P260_BROWSER_FRAME'
,p_is_required=>true
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(875541626713267923.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'D'
,p_prompt=>'In Frames einbetten'
,p_source=>'BROWSER_FRAME'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'BROWSER_FRAME'
,p_lov=>'.'||wwv_flow_imp.id(1098055005642193053)||'.'
,p_cHeight=>1
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flows',
' where id                  = :FB_FLOW_ID',
'   and compatibility_mode <> ''4.0''',
'   and security_group_id   = :flow_security_group_id'))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Mit diesem Attribut k\00F6nnen Sie festlegen, ob der Browser die Seiten Ihrer Anwendung in einem Frame anzeigen kann:'),
'<ul>',
'<li><strong>Ablehnen</strong>: Die Seite kann nicht in einem Frame angezeigt werden, ungeachtet der Site, die dies versucht.</li>',
'<li><strong>Aus selbem Ursprung zulassen</strong>: Die Seite kann nur in einem Frame angezeigt werden, der denselben Ursprung wie die Seite selbst hat.</li>',
'<li><strong>Zulassen</strong>: Die Seite kann in jedem Frame angezeigt werden.</li>',
'</ul>',
'</p>',
'<p>',
unistr('Die Anzeige von Seiten in Frames kann \00FCber so genannte "Clickjacking"-Angriffe missbraucht werden.'),
unistr('Bei einem Clickjacking-Angriff verwendet der Angreifer mehrere Layer, um einen Benutzer zu verleiten, auf eine Schaltfl\00E4che oder einen Link auf einer anderen Seite zu klicken, w\00E4hrend er vermeintlich auf die Seite der obersten Ebene klickt.'),
unistr('Somit missbraucht der Angreifer Klicks (oder Tastenanschl\00E4ge), die f\00FCr die Benutzerseite gedacht waren, und leitet sie zu einer anderen Seite um.'),
'</p>',
'<p>',
unistr('Dialogseiten werden h\00E4ufig in einem iframe angezeigt, '),
'der normalerweise mit dem Attributwert "Ablehnen" nicht funktioniert.',
unistr('Das Attribut <em>Einbettung in Frame zulassen</em> eines Templates f\00FCr Dialogseiten definiert, ob "Aus selbem Ursprung zulassen" anstelle von "Ablehnen" '),
unistr('f\00FCr Seiten verwendet werden soll, die ein derartiges Template verwenden.'),
'Als Schutz vor Clickjacking verwendet',
unistr('&PRODUCT_NAME. eine seitenspezifische Pr\00FCfsumme in URLs f\00FCr Dialogseiten.'),
'</p>',
'<p>',
unistr('Hinweis: Dieses Feature erfordert moderne Browser, die die HTTP-Headerantwortvariable "X-Frame-Options" unterst\00FCtzen.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
