,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>150
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_page_api.get_url (',
'           p_page   => 4500,',
'           p_items  => ''FB_FLOW_PAGE_ID'',',
'           p_values => id) edit_link,',
'       id,',
'       name,',
'       (select count(*)',
'          from wwv_flow_page_plugs',
'         where flow_id = p.flow_id',
'           and page_id = p.id) regions,',
'       p.page_type,',
'       created_on,',
'       created_by,',
'       last_updated_on,',
'       last_updated_by',
'  from wwv_flow_pages_dev p',
' where flow_id           = :FB_FLOW_ID',
