wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(209195511077496719.4003)
,p_validation_name=>'version must be compatible'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_runtime_version varchar2(200); -- the date of the current runtime flows',
'  l_calling_version varchar2(200);',
'begin',
'    l_calling_version := replace(replace(replace(wwv_flow_imp_parser.get_version (p_file_id => :p598_file_id),''.'',null),''_'',null),''/'',null);',
'    l_runtime_version := replace(replace(replace(wwv_flows_version,''.'',null),''_'',null),''/'',null);',
'',
'    if l_calling_version > l_runtime_version then',
'        --',
'        -- version incompatability        ',
'        --',
'        ',
'        return false;',
'    else',
'        return true;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Nicht kompatibel (Ihr Import enth\00E4lt m\00F6glicherweise Aufrufe, die von Ihrer &PRODUCT_NAME.-Version nicht unterst\00FCtzt werden.)')
,p_when_button_pressed=>wwv_flow_imp.id(209190624600496680.4003)
,p_associated_item=>wwv_flow_imp.id(209193914713496705.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
