 p_id=>wwv_flow_imp.id(73941834180235927.4003)
,p_validation_name=>'P652_NAME unique'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P652_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P652_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P652_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_field_templates ft,',
'       central_theme ct',
' where ( ft.flow_id, ft.theme_id, ft.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P652_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and ft.template_name = :P652_NAME'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'#LABEL# muss eindeutig sein.'
,p_when_button_pressed=>wwv_flow_imp.id(91889113020926194.4003)
