'       central_theme ct',
'   where ( ft.flow_id, ft.theme_id, ft.security_group_id ) in',
'         (',
'          ( :P655_COPY_FROM_FLOW_ID, :P353_COPY_FROM_THEME, :WORKSPACE_ID ),',
