unistr('Geben Sie die SQL-Abfrage ein, die mindestens eine Zeile zur\00FCckgibt, falls unterst\00FCtzende Objekte vorhanden sind. Die Abfrage sollte keine Zeilen zur\00FCckgeben, wenn keine unterst\00FCtzenden Objekte vorhanden sind.<p />')))
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>'select id from wwv_flow_install where flow_id = :fb_flow_id'
,p_plug_footer=>wwv_flow_string.join(wwv_flow_t_varchar2(
