,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Export Components'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_components wwv_flow_export_dev.t_components;',
'begin',
'    -- Load selected components into array so we don''t have to query the collection for each language.',
'    select type_name as component,',
'           id        as component_id',
'           bulk collect into l_components',
'      from wwv_multi_component_export',
'     where flow_id   = :P688_APPLICATION',
'     order by type_name, seq_id;',
'     ',
'     wwv_flow_export_dev.export_components (',
'         p_application_id         => :P688_APPLICATION,',
'         p_components             => l_components,',
'         p_format                 => case ',
'                                     when :P688_EXPORT_ZIP = ''Y'' then ''ZIP_UNIX'' ',
'                                     else ''UNIX'' ',
'                                     end,',
'         p_export_translations_yn => :P688_EXPORT_TRANSLATIONS,',
'         p_flashback_min_ago      => :P688_FLASHBACK_MIN_AGO, ',
'                                     -- always include install when NOT a zip',
'         p_with_install           => :P688_EXPORT_ZIP != ''Y'' or ',
'                                     -- export install if requested when zip',
'                                     :P688_WITH_INSTALL = ''Y'', ',
'        p_with_audit_info         => :P688_AUDIT_INFO);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Fehler beim Exportieren von Komponenten.'
,p_process_when_button_id=>wwv_flow_imp.id(8006211505904123.4003)
,p_process_success_message=>'Gemeinsame Komponente(n) wurde(n) exportiert.'
,p_internal_uid=>8612229637147008.4003
);
