,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie das Ereignis an, das die dynamische Aktion ausl\00F6st. Informationen \00FCber spezifische Ereignisse finden Sie im entsprechenden Abschnitt im Benutzerhandbuch. Die Ereignisse sind folgenderma\00DFen kategorisiert:</p>'),
