,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>60
,p_plug_display_point=>'REGION_POSITION_03'
,p_list_id=>wwv_flow_imp.id(4883690711914138.4003)
,p_plug_source_type=>'NATIVE_LIST'
,p_list_template_id=>wwv_flow_imp.id(697214733556634905.4003)
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(47918318810645641.4003)
,p_plug_name=>'Authentifizierungsschemas'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4003)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select ',
'       case',
'         when a.id = f.authentication_id then',
'            ''icon-sc-authentication-scheme-on''',
'         else',
'            ''icon-sc-authentication-scheme-off''',
'       end as icon_class,',
'       ''f?p=4000:4495:''||:APP_SESSION||'':::RP,4495:P4495_ID:''||a.id as edit_link,',
'       replace(a.name,''_'','' '') as icon_title,',
'       a.name,',
'       case',
'         when a.id = f.authentication_id ',
'         then ''Y'' ',
'         else ''N''',
'       end as is_current_yn,',
'       a.scheme_type,',
'       a.id,',
'       a.cookie_name,',
'       a.cookie_path,',
'       a.cookie_domain,',
'       a.use_secure_cookie_yn,',
'       a.help_text,',
'       case when a.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                      messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_authentications',
'          where reference_id      = a.id',
'            and security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when a.reference_id is not null then',
'           case',
'               when master.version_scn = a.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != a.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       a.created_by,',
'       a.created_on,',
'       a.last_updated_by,',
'       a.last_updated_on',
'  from wwv_flow_authentications a,',
'       wwv_flow_authentications master,',
'       wwv_flows f,',
'       messages',
' where a.flow_id           = :FB_FLOW_ID',
'   and a.security_group_id = :WORKSPACE_ID',
'   and f.id                = a.flow_id',
'   and a.reference_id      = master.id (+)',
'   and a.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
