,p_plug_template=>wwv_flow_imp.id(399849897040726767.4003)
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p class="instructiontext">',
unistr('Sie k\00F6nnen ein neues Authentifizierungsschema erstellen, indem Sie eine Kopie eines Schemas in dieser Anwendung oder einer anderen Anwendung in Ihrem Workspace erstellen. Danach k\00F6nnen Sie das neue Schema bearbeiten und den Namen und die Einstellunge')
||unistr('n wie gew\00FCnscht \00E4ndern, damit sie Ihren Anforderungen gerecht werden.'),
'</p>',
'<p class="instructiontext">',
unistr('Sie k\00F6nnen auch ein Authentifizierungsschema zur aktuellen Anwendung hinzuf\00FCgen, indem Sie eines aus der Galerie der bereitgestellten Schemas ausw\00E4hlen.'),
'</p>',
'<p class="instructiontext">',
unistr('Alternativ k\00F6nnen Sie ein neues Authentifizierungsschema erstellen, indem Sie die einzelnen Schritte des Assistenten ausf\00FChren und alle Parameter angeben. Um ein neues Authentifizierungsschema zu erstellen, w\00E4hlen Sie "Basiert auf einem vorkonfigurie')
||unistr('rten Schema aus der Galerie", und w\00E4hlen Sie dann den Schematyp "Benutzerdefiniert".'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_plug_comment=>'Region generated 26-JUN-2002 03:01:48'
);
