'            p_application_id  => :FB_FLOW_ID,',
'            p_rc_id           => l_rc_id,',
'            p_attr_to_include => :P907_INCLUDE_IN_UPDATE );',
'      end if;',
'',
'   end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Aktualisieren des Attribut-Dictionarys nicht erfolgreich.'
,p_process_when_button_id=>wwv_flow_imp.id(253950306918283249.4003)
