 p_id=>wwv_flow_imp.id(73941776788235926.4003)
,p_validation_name=>'P955_NAME unique'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P955_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P955_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P955_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_row_templates rt,',
'       central_theme ct',
' where ( rt.flow_id, rt.theme_id, rt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P955_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and rt.row_template_name = :P955_NAME'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'#LABEL# muss eindeutig sein.'
,p_when_button_pressed=>wwv_flow_imp.id(148837904548483281.4003)
