 p_id=>979.4003
,p_name=>'Alle Backupdetails'
,p_alias=>'ALL-BACKUP-DETAILS'
,p_page_mode=>'MODAL'
,p_step_title=>'Alle Backupdetails'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(5507013954294272)
,p_step_template=>wwv_flow_imp.id(120871216744825711.4003)
,p_page_template_options=>'#DEFAULT#'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(489623016951494467.4003)
,p_name=>'Backupdetails'
,p_template=>wwv_flow_imp.id(42025417508627628.4003)
,p_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--inline:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with manifest_summary as (',
'    select wwv_flow_lang.system_message(e.component_type) as component_type,',
'           wwv_flow_lang.system_message(e.action) as action,',
'           e.component_name,',
'           e.last_updated_by, ',
'           to_date(e.last_updated_on, ''YYYYMMDD HH24:MI:SS'') as last_updated_on',
'    from wwv_flow_backups$ j, xmltable(',
'        ''/json/details/row''',
'        passing wwv_flow_json.to_xmltype( j.manifest )',
'        columns',
'            component_type    varchar2(100)   path ''component_type/text()'',',
'            action            varchar2(100)   path ''action/text()'',',
