wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6220902957565972.4003)
,p_plug_name=>'REST-Quellenparameter'
,p_parent_plug_id=>wwv_flow_imp.id(6403047177080356.4003)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4003)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select cp.id, ',
'       pa.name,',
'       pa.data_type,',
'       cp.value_type,',
'       cp.value_language,',
'       cp.value,',
'       cp.format_mask',
'  from wwv_flow_web_src_comp_params cp, wwv_flow_web_src_params pa',
' where pa.id                = cp.web_src_param_id',
'   and pa.flow_id           = cp.flow_id',
'   and pa.security_group_id = cp.security_group_id ',
'    -- ',
'   and cp.search_config_id  = :P1117_ID',
'   and cp.security_group_id = :WORKSPACE_ID',
'   and cp.flow_id           = :FB_FLOW_ID',
'   and pa.is_query_param    = ''N'''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1117_ID'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_web_src_comp_params cp, ',
'       wwv_flow_web_src_params pa',
' where pa.id                = cp.web_src_param_id',
'   and pa.flow_id           = cp.flow_id',
'   and pa.security_group_id = cp.security_group_id',
'    -- ',
'   and cp.security_group_id = :WORKSPACE_ID',
'   and cp.flow_id           = :FB_FLOW_ID',
'   and cp.search_config_id  = :P1117_ID',
'   and pa.is_query_param    = ''N'''))
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'REST-Quellenparameter'
