,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie ein Pfadmuster ein, das im Eigenschaftsgraph gesucht werden soll. Um alle Kanten im Graph zu suchen, verwenden Sie das folgende Muster: <strong>(a) - [e] -> (b)</strong>. Verwenden Sie dar\00FCber hinaus <em>Label-Constraints</em>, um die Ty')
||unistr('pen von Knoten oder Kanten einzuschr\00E4nken.</p>'),
'<p><strong>Beispiele</strong></p>',
'<dl>',
'<dt>Alle Personen suchen, die Autos gekauft haben.</dt><dd><pre>(p is person) - [t is buys] -> (c is car)</pre></dd>',
'<dt>Alle Mitarbeiter suchen, die in Abteilungen arbeiten.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments)</pre></dd>',
'<dt>Alle Mitarbeiter suchen, die in Abteilungen arbeiten und Autos gekauft haben.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments), (e is employees) - [t is buys] -> (c is car)</pre></dd>',
'</dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
