wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2011415257979412.4003)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Source Query'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_document_source_id number;',
'begin',
'',
'    wwv_flow_report_query_dev.get_collection_member(',
'        p_seq                       => :P1119_SEQ_ID,',
'        p_collection_name           => ''REPORT_QUERIES'',',
'        p_name                      => :P1119_NAME,',
'        p_location                  => :P1119_LOCATION,',
'        -- Local',
'        p_source_type               => :P1119_SOURCE_TYPE,',
'        p_table_owner               => :P1119_TABLE_OWNER,',
'        p_table_name                => :P1119_TABLE_NAME,',
'        p_sql_query                 => :P1119_SQL,',
'        p_function_body_language    => :P1119_FUNC_BODY_LANG,',
'        p_function_body             => :P1119_FUNC_BODY,',
'        p_graph_name                => :P1119_GRAPH_NAME,',
'        p_match_clause              => :P1119_PQL_MATCH_CLAUSE,',
'        p_columns_clause            => :P1119_PQL_COLUMNS_CLAUSE,',
'        -- REST data source',
'        p_web_src_module_id         => :P1119_WEB_SRC_MODULE_ID,',
'        p_array_column_id           => :P1119_WEB_SRC_ARRAY_COL_ID,',
'        p_document_source_id        => l_document_source_id,',
'        -- REST enabled SQL',
'        p_remote_server_id          => :P1119_REMOTE_SERVER_ID,',
'        p_remote_source_type        => :P1119_REMOTE_SOURCE_TYPE,',
'        p_remote_sql_query          => :P1119_REMOTE_SQL,',
'        p_remote_table_owner        => :P1119_REMOTE_TABLE_OWNER,',
'        p_remote_table_name         => :P1119_REMOTE_TABLE_NAME );',
'',
'    if :P1119_LOCATION = wwv_flow_exec_api.c_location_duality_view then',
'        :P1119_DUALITY_VIEW_ID := l_document_source_id;',
'    elsif :P1119_LOCATION = wwv_flow_exec_api.c_location_json_source then',
'        :P1119_JSON_SOURCE_ID := l_document_source_id;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P1119_SEQ_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>2011415257979412.4003
);
