,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4003)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select display_name,',
'       object_type,',
'       ''f?p=4000:4500:''||:APP_SESSION||''::NO:1:FB_FLOW_ID,FB_FLOW_PAGE_ID,F4000_P1_FLOW,F4000_P1_PAGE:''||app_id||'',''||page_id||'',''||app_id||'',''||page_id||''#''||component_type||'':''||component_id as object_url,',
'       object_name,',
'       page_id,',
'       page_name',
'  from (',
'        select q.name                                               as display_name,',
'               wwv_flow_lang.system_message(''F4000.DYNAMIC ACTION'') as object_type,',
'               e.name                                               as object_name,',
'               5150                                                 as component_type,',
'               a.id                                                 as component_id,',
'               a.flow_id                                            as app_id,',
'               e.page_id                                            as page_id,',
'               pg.name                                              as page_name',
'          from wwv_flow_shared_queries  q,',
'               wwv_flow_page_da_events  e,',
'               wwv_flow_page_da_actions a,',
'               wwv_flow_steps           pg',
'         where q.flow_id            = :FB_FLOW_ID',
'           and q.security_group_id  = :WORKSPACE_ID',
'           and e.flow_id            = q.flow_id',
'           and e.security_group_id  = q.security_group_id',
'           and a.security_group_id  = q.security_group_id',
'           and pg.security_group_id = q.security_group_id',
'           and a.event_id           = e.id',
'           and a.report_query_id    = q.id',
'           and pg.flow_id           = e.flow_id',
'           and pg.id                = e.page_id',
'        union all',
'        select q.name                                        as display_name,',
'               wwv_flow_lang.system_message(''PAGE PROCESS'')  as object_type,',
'               pr.process_name                               as object_name,',
'               5530                                          as component_type,',
'               pr.id                                         as component_id,',
'               pr.flow_id                                    as app_id,',
'               pr.flow_step_id                               as page_id,',
'               pg.name                                       as page_name',
'          from wwv_flow_shared_queries  q,',
'               wwv_flow_step_processing pr,',
'               wwv_flow_steps           pg',
'         where q.flow_id            = :FB_FLOW_ID',
'           and q.security_group_id  = :WORKSPACE_ID',
'           and pr.security_group_id = q.security_group_id',
'           and pg.security_group_id = q.security_group_id',
'           and pr.flow_id           = q.flow_id',
'           and pr.report_query_id   = q.id',
'           and pg.flow_id           = pr.flow_id',
'           and pg.id                = pr.flow_step_id',
'    )'))
