wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1312877352198970103.4003)
,p_plug_name=>'Feature ist vorhanden'
,p_region_css_classes=>'a-Alert--inlineDialog a-Alert--noTitle'
,p_region_template_options=>'#DEFAULT#:a-Alert--warning:a-Alert--wizard'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4003)
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Dieses Feature ist bereits in Ihrer Anwendung vorhanden. Wenn Sie dieses Feature erneut installieren m\00F6chten, m\00FCssen Sie zun\00E4chst die vorhandenen Seiten, die gemeinsamen Komponenten und die Erstelloption <strong>&P1317_BUILD_OPTION.</strong> entfe')
||'rnen. Gehen Sie wie folgt vor, um die Komponenten zu entfernen:',
'<ol>',
'  <li>Gehen Sie zu "Gemeinsame Komponenten".</li>',
'  <li>Gehen Sie zu "Anwendungslogik", "Erstelloptionen".</li>',
'  <li>Klicken Sie auf <strong>&P1317_BUILD_OPTION.</strong>.</li>',
'  <li>Klicken Sie auf <strong>Komponenten entfernen</strong>.<br>',
unistr('    &nbsp;&nbsp;Aktivieren Sie das Kontrollk\00E4stchen <em>Ja - Komponenten entfernen</em>.<br>'),
'    &nbsp;&nbsp;Klicken Sie auf <strong>Komponenten entfernen</strong>.</li>',
unistr('  <li>Klicken Sie bei "Erstelloption erstellen/bearbeiten" auf <strong>L\00F6schen</strong>.<br>'),
unistr('    &nbsp;&nbsp;Klicken Sie auf <strong>Erstelloption l\00F6schen</strong>.</li>'),
'</ol>',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
