,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Berichtslayouts k\00F6nnen mit einer Berichtsregion oder Berichtsabfrage verwendet werden, um Daten in einem druckbaren Format zu rendern, das vom Remotedruckserver unterst\00FCtzt wird. Je nach Typ des Remotedruckservers kann ein Berichtslayout:'),
'<ul>',
'<li>mit dem Word-Plug-in von Template Builder entworfen und als Datei vom Typ RTF oder XSL-FO hochgeladen werden.</li>',
'<li> mit einem Word-Dokument mit einer speziellen Templatesyntax entworfen werden.</li>',
'</ul>',
'</p>  ',
unistr('<p>Beachten Sie, dass Ihre Anwendung einen Remotedruckserver verwenden muss, um dieses Feature nutzen zu k\00F6nnen.</p>'),
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
