,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Erstellen Sie einen <strong>REST-f\00E4higen SQL</strong>-Service zur Ausf\00FChrung der SQL oder PL/SQL, die in &PRODUCT_NAME.-Komponenten in einer Oracle-Remotedatenbank definiert ist.</p>'),
'',
unistr('<p><strong>Voraussetzung:</strong> Die Remotedatenbank muss Oracle REST Data Services (ORDS) Release 20.3 oder h\00F6her auf dem Frontend enthalten. Au\00DFerdem muss das Feature <em>REST-f\00E4hige SQL</em> aktiviert sein. Alle SQL- und PL/SQL-Anweisungen werde')
||unistr('n an die ORDS-Instanz gesendet und von dieser in der Remotedatenbank ausgef\00FChrt.</p>'),
'',
unistr('<p>REST-f\00E4hige SQL-Referenzen werden auf Workspace-Ebene gespeichert und sind daher in allen Anwendungen sichtbar.</p>'),
'',
unistr('<p>Beim Exportieren einer Anwendung werden die verwendeten REST-f\00E4higen SQL-Referenzen der Exportdatei hinzugef\00FCgt. Wenn Sie eine Anwendung exportieren und in einen anderen Workspace importieren, pr\00FCft &PRODUCT_NAME., ob der Ziel-Workspace bereits RE')
||unistr('ST-f\00E4hige SQL-Referenzen mit derselben <strong>statischen ID</strong> enth\00E4lt. Wenn eine REST-f\00E4hige SQL-Referenz bereits vorhanden ist, verwendet die Anwendung die vorhandene Referenz. Wenn die Referenz nicht vorhanden ist, wird sie im Ziel-Workspac')
||'e erstellt.</p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
