,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie an, ob die Datenbankzugangsdaten f\00FCr das Workspace-Schema oder f\00FCr'),
unistr('    die APEX-Engine verf\00FCgbar sind.'),
'</p>',
'<dl>',
'    <dt>Schema</dt>',
unistr('    <dd>Die Datenbankzugangsdaten sind f\00FCr eines des Workspace-Schemas zug\00E4nglich. Wenn die'),
'        Zugangsdaten von einer Anwendung verwendet werden, muss das <em>Anwendungsparsingschema</em>',
unistr('        auf die Datenbankzugangsdaten zugreifen k\00F6nnen.</dd>'),
'    <dt>Instanz</dt>',
unistr('    <dd>Die Datenbankzugangsdaten sind f\00FCr die APEX-Engine, f\00FCr das'),
unistr('        Schema <code>APEX_NNNNNN</code>, zug\00E4nglich. Wenn Sie diese Option ausw\00E4hlen, werden die ersten'),
unistr('        verf\00FCgbaren Datenbankzugangsdaten vorab im Attribut <strong>Name</strong>'),
unistr('        ausgew\00E4hlt.</dd>'),
'</dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '2',
