wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3367384134004646.4003)
,p_name=>'P1621_VALID_FOR_URLS'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('G\00FCltig f\00FCr URLs')
,p_source=>'VALID_FOR_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>64
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>&PRODUCT_NAME. pr\00FCft, ob die URL, f\00FCr die die Zugangsdaten zur Laufzeit verwendet werden, mit einer der URLs in dieser Liste \00FCbereinstimmt. Wird keine \00DCbereinstimmung gefunden, l\00F6st &PRODUCT_NAME. einen Fehler aus.</p>'),
'<p>Geben Sie jede URL auf einer neuen Zeile ein. Der verwendete URL-Endpunkt muss mit einer der hier angegebenen URLs beginnen.</p>',
'<p>Beispiel:</p>',
'<pre>',
'https://www.example.com/restapis/my-protected-api',
'https://www.example.com/allowed-urls',
'</pre>',
unistr('<p>Wenn die Zugangsdaten zum Aufrufen eines REST-Service unter <strong>https://www.example.com/restapis/my-protected-api/restendpoint</strong> oder <strong>https://www.example.com/allowed-urls/page1</strong> verwendet werden, k\00F6nnen die Zugangsdaten ')
||'verwendet werden, und der Aufruf ist erfolgreich.</p>',
unistr('<p>Wenn die Zugangsdaten zum Aufrufen eines REST-Service unter <strong>https://localhost/myapis/test</strong> oder <strong>https://dev.example.com/myapis/test</strong> verwendet werden, k\00F6nnen die Zugangsdaten <em>nicht</em> verwendet werden, und &PR')
||unistr('ODUCT_NAME. l\00F6st einen Fehler aus.</p>'),
'<p>Beispiel:</p>',
'<pre>',
'ldap://ldap.mycompany.com',
'ldaps://ldap.mycompany.com:389',
'</pre>',
unistr('<p>ldap:// und ldaps:// ist das "Protokoll", mit dem die zul\00E4ssigen URLs f\00FCr einen LDAP-Server angegeben werden.</p>'),
unistr('<p>Zum \00C4ndern dieses Wertes muss das Client Secret erneut eingegeben werden.</p>'),
''))
,p_inline_help_text=>unistr('Beachten Sie, dass Sie bei einer \00C4nderung dieses Wertes das Client Secret erneut eingeben m\00FCssen.')
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
