wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(154593935882686557.4003)
,p_name=>'P1621_CREDENTIALS_TYPE'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BASIC'
,p_prompt=>'Authentifizierungstyp'
,p_source=>'AUTHENTICATION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie hier den Authentifizierungstyp an. &PRODUCT_NAME. unterst\00FCtzt die folgenden Authentifizierungstypen:</p>'),
'<ul>',
'    <li><strong>Basisauthentifizierung</strong>: Sendet Benutzernamen und Kennwort mit Base64 codiert als Header der <strong>Autorisierungsanforderung</strong>.',
'    </li>',
unistr('    <li><strong>OAuth2-Clientzugangsdaten</strong>: &PRODUCT_NAME. tauscht die Client-ID und das Client Secret mit einer Tokenserver-URL gegen ein <strong>Zugriffstoken</strong> aus. Das Zugriffstoken wird dann zum Ausf\00FChren der eigentlichen Anforder')
||'ung verwendet. Wenn das Zugriffstoken abgelaufen ist, fordert &PRODUCT_NAME. transparent ein neues Token an.</li>',
'    <li><strong>Native OCI-Authentifizierung</strong>: &PRODUCT_NAME. signiert Anforderungen an die <em>Oracle Cloud Infrastructure-(OCI-)</em>REST-API, wie in der <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Content/AP'
||unistr('I/Concepts/signingrequests.htm">OCI-Dokumentation</a> beschrieben. Dieser Typ ist nur in Oracle Database 18c und h\00F6her verf\00FCgbar.</li>'),
unistr('    <li><strong>HTTP-Header</strong>: Die Zugangsdaten werden der REST-Anforderung als HTTP-Header hinzugef\00FCgt. Der Name der Zugangsdaten ist der HTTP-Headername, das Secret der Zugangsdaten ist der HTTP-Headerwert. &PRODUCT_NAME. f\00FCgt diese Secrets ')
||'nicht dem Debuglog oder anderen Logs hinzu.</li>',
unistr('    <li><strong>URL-Abfragezeichenfolge</strong>: Die Zugangsdaten werden der URL der REST-Anforderung als <em>Abfragezeichenfolgenparameter</em> hinzugef\00FCgt (Beispiel: <strong>?name=value</strong>). Diese Option kann bei API-Schl\00FCsseln n\00FCtzlich sein')
||unistr('. &PRODUCT_NAME. f\00FCgt diese Secrets nicht dem Debuglog oder anderen Logs hinzu. Webproxy- oder andere Zwischenserver k\00F6nnen diese Zugangsdaten allerdings in ihren Logdateien protokollieren.</li>'),
unistr('    <li><strong>Schl\00FCsselpaar</strong>: Schl\00FCsselpaarzugangsdaten enthalten einen Public Key, der \00F6ffentlich zum Verschl\00FCsseln von Daten verwendet wird, und einen Private Key, der geheim gehalten und zum Entschl\00FCsseln von Daten verwendet wird. Beide ')
||unistr('Schl\00FCssel zusammen sorgen f\00FCr einen sicheren Datenaustausch.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
