,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Endbenutzer k\00F6nnen Probleme dabei haben, die hochzuladenden Spalten basierend auf den Spaltennamen der Tabelle korrekt zu identifizieren. Daher k\00F6nnen Sie Aliasnamen f\00FCr jede Spalte definieren. Diese werden dem Endbenutzer beim Hochladen der Sprea')
||'dsheet-Daten angezeigt.</p>',
unistr('<p>Wenn eine Werteliste erstellt wird, werden die Aliasnamen w\00E4hrend der Datenspaltenzuordnung automatisch von der Anwendung verwendet. Andernfalls verwendet die Anwendung die Tabellenspaltennamen. Nach der Erstellung kann die Werteliste auch bearbei')
||unistr('tet werden, und Spalten k\00F6nnen aus der Liste entfernt werden.</p>')))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
