wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(212980031120458358.4003)
,p_plug_name=>unistr('Nebenl\00E4ufigkeit verwalten')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Mit dieser Option erh\00E4lt der Entwickler die M\00F6glichkeit, eine Spalte anzugeben, mit der eine Pr\00FCfung zur Version der Daten in der zugrunde liegenden Tabelle ausgef\00FChrt werden kann. Dies ist vor allem dann wichtig, wenn der Upload in eine Tabelle v')
||unistr('orgenommen wird, die regelm\00E4\00DFig aktualisiert wird.</p>'),
unistr('<p>Bei allen Aktualisierungen wird die Spalte, mit der die Nebenl\00E4ufigkeit gepr\00FCft wird, abgefragt und mit dem Datenbankwert f\00FCr diese Spalte verglichen, bevor der Datensatz festgeschrieben wird. Wenn die nebenl\00E4ufige Spalte zwischen der Abfrage des ')
||unistr('Datensatzes und der Verarbeitung des Datenuploads ge\00E4ndert wird, wird der Datensatz gekennzeichnet und nicht festgeschrieben. Wenn die Nebenl\00E4ufigkeitsspalte nicht angegeben ist, werden durch den Datenupload stets alle Datens\00E4tze aktualisiert, wobei ')
||unistr('m\00F6glicherweise von anderen Benutzern vorgenommene \00C4nderungen \00FCberschrieben werden.</p>')))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
