,p_item_template_options=>'#DEFAULT#'
,p_help_text=>unistr('Mit dieser Option werden vorhandene statische Anwendungsdateien aus der Datenbank in den Objektspeicher migriert. Wenn Sie sich zu diesem Zeitpunkt gegen die Migration von Dateien entscheiden, k\00F6nnen Sie auf der Seite "Gemeinsame Komponenten", "Stati')
||'sche Anwendungsdateien" unter "Aufgaben" die Option "Synchronisieren" verwenden.'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
