,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'populate items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if nvl(:P1852_FILES_TO, wwv_flow_object_store.c_file_storage_object_store) ',
'       = wwv_flow_object_store.c_file_storage_object_store then',
'    select count(*), sum(sys.dbms_lob.getlength(file_content))',
'      into :P1852_FILE_COUNT, :P1852_TOTAL_BYTES',
'      from wwv_flow_static_files',
'     where security_group_id = :WORKSPACE_ID',
'       and flow_id = :FB_FLOW_ID;',
'else',
'    select count(*), sum(n002)',
'      into :P1852_FILE_COUNT, :P1852_TOTAL_BYTES',
'      from wwv_flow_collections',
'     where collection_name = ''F4000_OB_FILES''',
'       and n001 = :FB_FLOW_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2411614510988432.4003
);
