,p_prompt=>unistr('Pr\00E4fix von URL-Pfad')
,p_source=>'URL_PATH_PREFIX'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>65
,p_cMaxlength=>500
,p_read_only_when=>'P1921_WEB_SOURCE_TYPE'
,p_read_only_when2=>'NATIVE_REST_ENABLED_SQL_QUERY'
,p_read_only_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Das URL-Pfadpr\00E4fix gilt speziell f\00FCr diese REST-Datenquelle. Die URL-Endpunkte aller Vorg\00E4nge in der REST-Datenquelle verwenden dasselbe URL-Pfadpr\00E4fix. Beim Aufruf der REST-Datenquelle erstellt &PRODUCT_NAME. die URL wie folgt:'),
'</p>',
'<ol>',
'    <li><strong>Basis-URL</strong> des <strong>Remoteserver</strong>-Objekts</li> ',
unistr('    <li><strong>Pr\00E4fix von URL-Pfad</strong> der <strong>REST-Datenquelle</strong></li>'),
'    <li><strong>URL-Muster</strong>, das im <strong>Vorgang</strong> der REST-Datenquelle definiert ist</li>',
'</ol>',
'<div>',
'    <p>Beispiel:</p>',
'    <p>',
'        REST-Datenquellen:',
'        <ol>',
'            <li><code>http://api.example.com:8080/root/<strong>service1/</strong>method1</code></li>',
'            <li><code>http://api.example.com:8080/root/<strong>service2/</strong>method1</code></li>',
'            <li><code>http://api.example.com:8080/root/<strong>service2/</strong>method4</code></li>',
'        </ol> ',
'    </p>',
'    <p>',
unistr('        Die URL-Teile <strong>service1/</strong> und <strong>service2/</strong> geh\00F6ren zu einer REST-Datenquelle und werden daher als <strong>Pr\00E4fix von URL-Pfad</strong> verwendet.'),
'    </p>',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
