,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select name, id ',
'  from wwv_remote_servers',
' where server_type = case when :P1921_WEB_SOURCE_TYPE = ''NATIVE_REST_ENABLED_SQL_QUERY'' then ''REMOTE_SQL'' else ''WEB_SERVICE'' end',
'   and security_group_id = :FLOW_SECURITY_GROUP_ID'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Ausw\00E4hlen -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    W\00E4hlen Sie ein <strong>Remoteserver</strong>-Objekt f\00FCr diese REST-Datenquelle aus. &PRODUCT_NAME. teilt den URL-Endpunkt in den ersten Teil (Remoteserver) und den zweiten (servicespezifischen) Teil auf. Ein <strong>Remoteserver</strong>-Objekt k')
||'ann mehrere ',
'    Serviceendpunkte enthalten. Es wird empfohlen, dasselbe Remoteserverobjekt zu REST-Datenquellen zuzuweisen, wenn diese',
unistr('    dieselben Werte f\00FCr Server, Port und URL-Pfadpr\00E4fix verwenden.'),
'</p>',
'<div>',
'    <p>Beispiel:</p>',
'    <p>',
'        REST-Datenquellen:',
'        <ol>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service1/method1</code></li>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service2/method1</code></li>',
'            <li><code><strong>http://api.example.com:8080/root/</strong>service2/method4</code></li>',
'        </ol> ',
'    </p>',
'    <p>',
'        Der URL-Teil <strong>http://api.example.com:8080/root/</strong> ist allen drei REST-Datenquellen gemeinsam.',
unistr('        Er kann also als Remoteserverobjekt verwendet werden und einen Namen erhalten. Wenn diese drei REST-Datenquellen sp\00E4ter auf einen anderen Server verschoben werden, muss das Remoteserverobjekt nur f\00FCr eine ge\00E4ndert werden.'),
'    </p>',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
