,p_source=>'AUTH_REMOTE_SERVER_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_AUTHENT_SERVERS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select name, id ',
'  from wwv_remote_servers',
' where server_type = ''AUTHENTICATION''',
'   and security_group_id = :FLOW_SECURITY_GROUP_ID'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Ausw\00E4hlen -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Wenn die Authentifizierung auf einem (anderen) <em>Authentifizierungsserver</em> ausgef\00FChrt werden muss, erstellen Sie ein <strong>Remoteserver</strong>-Objekt daf\00FCr, und w\00E4hlen Sie dieses hier aus. &PRODUCT_NAME. teilt den URL-Endpunkt in den er')
||'sten Teil (Remoteserver) und den zweiten (servicespezifischen) Teil auf. Ein <strong>Remoteserver</strong>-Objekt kann mehrere ',
'    Serviceendpunkte enthalten. Es wird empfohlen, dasselbe Remoteserverobjekt zu REST-Datenquellen zuzuweisen, wenn diese',
unistr('    dieselben Werte f\00FCr Server, Port und URL-Pfadpr\00E4fix verwenden.'),
'</p>',
'<div>',
'    <p>',
'    Beispiel:        ',
'    </p>',
'    <ol>',
'        <li><code><strong>http://api.example.com:8080/root/</strong>auth/token</code></li>',
'        <li><code><strong>http://api.example.com:8080/root/</strong>auth-prod/token</code></li>',
'    </ol> ',
'    <p>',
'        Der URL-Teil <strong>http://api.example.com:8080/root/</strong> ist beiden Authentifizierungsendpunkten gemeinsam',
'        und kann daher als benanntes Remoteserverobjekt verwendet werden.',
'    </p>',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
