 p_id=>wwv_flow_imp.id(242268510007871834.4003)
,p_plug_name=>unistr('Vorg\00E4nge')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr(' Ein <strong>REST-Quellenvorgang</strong> enth\00E4lt konkrete Informationen zum externen Webservice-Handler. Bei REST-Services besteht ein Vorgang aus einem URL-Muster in Kombination mit einem HTTP-Verb (GET, POST). Eine REST-Datenquelle kann mehrere Vo')
||unistr('rg\00E4nge enthalten.'),
' </p>',
unistr(' <p>Vorg\00E4nge k\00F6nnen <strong>Datenbankvorg\00E4ngen</strong> zugeordnet werden. So k\00F6nnen &PRODUCT_NAME.-Komponenten den richtigen Vorgang ausw\00E4hlen. In Berichten, interaktiven Berichten oder CSS-Kalendern wird der Vorgang ausgew\00E4hlt, der dem Datenbankvor')
||'gang <em>Zeilen abrufen</em> zugeordnet ist.</p>',
'<p>',
unistr('Auf Modulebene definierte Einstellungen werden f\00FCr alle Vorg\00E4nge innerhalb der REST-Datenquelle verwendet. Einstellungen auf Vorgangsebene gelten nur f\00FCr diesen Vorgang.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249280093175575814.4003)
,p_plug_name=>unistr('ORDS-Legacy-JSON-REST-Quelle: Unbekannte feste Seitengr\00F6\00DFe')
,p_region_template_options=>'#DEFAULT#:a-Alert--danger:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4003)
,p_plug_display_sequence=>20
,p_plug_source=>unistr('<p>Diese ORDS-REST-Quelle verwendet die <em>Legacy-JSON-Syntax</em>. Daten werden seitenweise mit einer festen Seitengr\00F6\00DFe zur\00FCckgegeben, die vom Server festgelegt wird. F\00FCr ein korrektes Rendering von &PRODUCT_NAME.-Komponenten muss die <em>Seitengr')
||unistr('\00F6\00DFe</em> in &PRODUCT_NAME. bekannt sein. Navigieren Sie zum Abschnitt <strong>Erweitert</strong>, und legen Sie die Seitengr\00F6\00DFe entsprechend fest. Diese Information erhalten Sie vom Administrator des REST-Service.')
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from ',
