wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(238756237141331835.4003)
,p_name=>'P1922_ALLOW_FETCH_ALL_ROWS'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(3469784605842432.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Abrufen aller Zeilen zulassen'
,p_source=>'ALLOW_FETCH_ALL_ROWS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from ',
'wwv_flow_web_src_modules',
'where id = :P1922_WEB_SRC_MODULE_ID and :P1922_DATABASE_OPERATION = ''FETCH_COLLECTION''',
''))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie an, ob &PRODUCT_NAME.-Komponenten alle Zeilen abrufen und somit mehrere HTTP-Anforderungen von diesem REST-Quellenvorgang ausf\00FChren d\00FCrfen. '),
'</p>',
'<p>',
unistr('   Das gilt f\00FCr REST-Quellen, bei denen Daten seitenweise zur\00FCckgegeben werden, wie bei Oracle REST Data Services. Beispiel: F\00FCr ein Diagramm oder die Ansicht "Gruppieren nach" f\00FCr interaktive Berichte ist ein Zugriff auf alle Zeilen zur Berechnung d')
||unistr('er korrekten Ergebnisse erforderlich. Wenn der REST-Service die Daten seitenweise zur\00FCckgibt, sind hierf\00FCr mehrere HTTP-Anforderungen an den REST-Service erforderlich. '),
'</p>',
'<p>',
unistr('    Wenn die REST-Quelle nur wenige Seiten zur\00FCckgibt, die in wenigen Sekunden abgerufen werden k\00F6nnen, ist das f\00FCr die meisten Anwendungsf\00E4lle akzeptabel. Setzen Sie dieses Attribut f\00FCr diese Services auf <strong>Ein</strong>. Wenn der REST-Service ')
||unistr('hingegen Tausende Zeilen in Hunderten Seiten zur\00FCckgibt, w\00FCrde das Abrufen aller Zeilen zu lange dauern. Setzen Sie dieses Attribut f\00FCr solche Services auf <strong>Aus</strong>.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
