wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3632686934550912649.4003)
,p_name=>'P1922_REST_OPERATION'
,p_is_required=>true
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(3500552115076908.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'HTTP-Methode'
,p_source=>'OPERATION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_HTTP_METHODS'
,p_lov=>'.'||wwv_flow_imp.id(225847729464891335)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Ausw\00E4hlen -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    HTTP-Vorgang oder <em>Methode</em> (GET, POST, PUT, DELETE) zur Ausf\00FChrung auf dem REST-Webservice. Die Kombination aus URL-Muster und HTTP-Vorgang identifiziert den Vorgang innerhalb einer REST-Datenquelle. Eine REST-Datenquelle kann dasselbe UR')
||unistr('L-Muster f\00FCr verschiedene HTTP-Vorg\00E4nge oder unterschiedliche URL-Muster f\00FCr denselben HTTP-Vorgang enthalten.'),
'</p>',
'<p>',
unistr('    Im Folgenden werden die HTTP-Methoden und ihre Verwendung in REST-Services kurz erl\00E4utert. Beachten Sie, dass es sich hierbei lediglich um Konventionen handelt. REST-Services sollten dem entsprechen, aber echte Implementierungen k\00F6nnen abweichen.')
||unistr(' Pr\00FCfen Sie immer in der Dokumentation des REST-Service, auf den Sie zugreifen m\00F6chten, welche Methoden aufgerufen werden k\00F6nnen und wie diese funktionieren.'),
'</p>',
'<ul>',
'    <li>',
unistr('        <strong>GET</strong> zum Abrufen von Daten aus dem REST-Service. GET soll idempotent sein. Der Aufruf \00E4ndert keine Daten auf Serverseite. Aus diesem Grund k\00F6nnen GET-Anforderungen in der Regel gecacht oder mehrmals aufgerufen werden. GET-Anfo')
||'rderungen haben normalerweise auch <em>keinen</em> Anforderungsbody.',
'    </li>',
'    <li>',
unistr('        Mit <strong>POST</strong> wird in der Regel eine neue Ressource auf dem Server erstellt. In der Praxis k\00F6nnen POST-Anforderungen'),
unistr('        jedoch alle m\00F6glichen Aktionen ausf\00FChren. POST-Anforderungen erfordern normalerweise einen Anforderungsbody.'),
'    </li>',
'    <li>',
unistr('        Mit <strong>PUT</strong> wird in der Regel eine neue Ressource auf dem Server <em>ersetzt</em>. Ein Anforderungsbody ist normalerweise erforderlich. Beachten Sie, dass Sie <em>alle</em> Attribute an den Server \00FCbergeben m\00FCssen. Fehlende Attri')
||'bute werden wahrscheinlich als Null- oder leere Werte geschrieben.',
'    </li>',
'    <li>',
'        Mit <strong>DELETE</strong> wird in der Regel eine Ressource auf dem Server entfernt. Ein Anforderungsbody ist normalerweise nicht erforderlich.',
'    </li>',
'    <li>',
unistr('        Mit <strong>PATCH</strong> wird in der Regel eine neue Ressource auf dem Server <em>ge\00E4ndert</em>. Nicht alle REST-Services stellen PATCH-Endpunkte bereit. Ein Anforderungsbody mit Informationen dazu, welches Attribut in welchen Wert ge\00E4ndert')
||unistr(' werden soll, ist erforderlich. PATCH erm\00F6glicht damit Teilaktualisierungen einer Serverressource. Beachten Sie, dass es keinen Standard f\00FCr das Aussehen des Anforderungsbodys f\00FCr einen PATCH-Endpunkt gibt. Pr\00FCfen Sie die Dokumentation Ihres REST-Ser')
||'vice, bevor Sie ihn aufrufen. ',
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
