,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    W\00E4hlen Sie den Typ dieses REST-Quellenparameters aus. Verf\00FCgbare Werte:'),
'</p>',
'<dl>',
'<dt>URL-Muster (IN)</dt>',
'<dd>Ersetzt Platzhalter in der Endpunkt-URL durch Parameterwerte.</dd>',
'<dt>URL-Abfragezeichenfolge (IN)</dt>',
unistr('<dd>F\00FCgt der URL Parameternamen und - wert als Abfragezeichenfolge hinzu</dd>'),
'<dt>HTTP-Header (IN, OUT)</dt>',
unistr('<dd>Sendet den Parameter als HTTP-Anforderungsheader oder empf\00E4ngt ihn von den Antwortheadern</dd>'),
'<dt>Cookie (IN, OUT)</dt>',
unistr('<dd>Sendet den Parameter als Cookie oder empf\00E4ngt ihn von den Antwortcookies</dd>'),
'<dt>Datenprofilspalte (OUT)</dt>',
unistr('<dd>Parst die Antwort anhand des Datenprofils und verwendet den Spaltenwert. Dieser Typ wird nur beim Prozesstyp <strong>API aufrufen</strong> unterst\00FCtzt.</dd>'),
'<dt>Anforderungs- oder Antwortbody (IN, OUT)</dt>',
unistr('<dd>Ersetzt Platzhalter im Anforderungsbody durch den Parameterwert. F\00FCr OUT-Parameter wird die <em>vollst\00E4ndige Antwort</em> abgerufen.</dd>'),
'<dt>Statuscode (OUT)</dt>',
unistr('<dd>Empf\00E4ngt den HTTP-Statuscode</dd>'),
'<dt>Ursachenphrase (OUT)</dt>',
unistr('<dd>Empf\00E4ngt die HTTP-Ursachenphrase</dd>'),
'</dl>',
'<p>',
unistr('    Beispiel f\00FCr Parameter des Typs <strong>URL-Muster</strong>'),
'</p>',
'<ul>',
'    <li>URL-Endpunkt: <code>http://{server}:{port}/ords/:schema/emp/:deptno</code></li>',
'    <li>Parameter 1: <em>URL-Mustervariable</em> "deptno" mit dem Wert "10"</li>',
'    <li>Parameter 2: <em>URL-Mustervariable</em> "schema" mit dem Wert "scott"</li>',
'</ul>',
'<p>',
'<br>',
unistr('    F\00FCgen Sie <em>nicht</em> den Doppelpunkt (:) zum Parameternamen hinzu. &PRODUCT_NAME. erstellt die aufzurufende URL wie folgt:<br>'),
'    <code>http://{server}:{port}/ords/<strong>scott</strong>/emp/<strong>10</strong></code>',
'</p>',
'<p>',
unistr('    Beispiel f\00FCr Parameter des Typs <strong>Abfragezeichenfolge</strong>'),
'</p>',
'<ul>',
'    <li>URL-Endpunkt: <code>http://{server}:{port}/ords/scott/emp</code></li>',
unistr('    <li>Parameter 1: <em>Variable f\00FCr Abfragezeichenfolge</em> "query_filter" mit dem Wert "KING"</li>'),
'</ul>',
'<p>',
'<br>',
'    &PRODUCT_NAME. erstellt die aufzurufende URL wie folgt:<br>',
'    <code>http://{server}:{port}/ords/scott/emp?<strong>query_filter</strong>=<strong>KING</strong></code>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
