,p_item_plug_id=>wwv_flow_imp.id(1718664379469919.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>unistr('F\00FCr Zeilensuche verwenden')
,p_source=>'IS_QUERY_PARAM'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'P1923_WEB_SRC_OPERATION_ID'
,p_display_when_type=>'ITEM_IS_NULL'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Wenn <strong>F\00FCr Zeilensuche verwenden</strong> f\00FCr einen REST-Datenquellenparameter aktiviert ist, werden Abfragen der <em>Zeilensuche</em> (von interaktiven Berichten, interaktiven Grids oder Popup-Wertelisten) mit diesem Parameter an den Webse')
||unistr('rvice \00FCbergeben. Das ist hilfreich, wenn Ihr REST-Service <em>Such</em>- oder <em>Abfrageparameter</em> unterst\00FCtzt.'),
'</p>',
'<p>Beispiel:</p>',
'<p>',
unistr('    Ein REST-Serviceendpunkt wird mit dem Abfrageparameter "q" aufgerufen, z.B. <code>http://{server}/path/to/service?p={search-term}</code>. F\00FCr die REST-Datenquelle ist der Abfragezeichenfolgenparameter <strong>q</strong> definiert. Wenn die Option')
||unistr(' <strong>F\00FCr Zeilensuche verwenden</strong> aktiviert ist, werden Suchbegriffe aus Zeilensuchen in interaktiven Berichten oder interaktiven Grids als Parameter <strong>q</strong> an den REST-Service \00FCbergeben.'),
'</p>',
unistr('<p>Nur auf Ebene der REST-Quelle definierte Parameter k\00F6nnen f\00FCr die Zeilensuche verwendet werden.</p>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
