wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2232893313790545.4003)
,p_computation_sequence=>20
,p_computation_item=>'P1923_DATA_TYPE'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case ',
'    when    :P1923_PARAM_TYPE not in ( ''HEADER'', ''COOKIE'', ''URL_PATTERN'', ''QUERY_STRING'', ''BODY'' )',
'         or :P1923_DIRECTION = ''OUT''',
'    then null',
'    else coalesce( :P1923_DATA_TYPE, ''VARCHAR2'' )',
'end'))
,p_compute_when=>'APPLY_CHANGES,CREATE,CREATE_AND_ANOTHER'
,p_compute_when_type=>'REQUEST_IN_CONDITION'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(3161301742926713.4003)
,p_computation_sequence=>30
,p_computation_item=>'P1923_FORMAT_MASK'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case when    :P1923_BOOLEAN_FALSE is not null',
'          or :P1923_BOOLEAN_TRUE is not null',
'     then :P1923_BOOLEAN_TRUE || '','' || :P1923_BOOLEAN_FALSE',
'end'))
,p_compute_when=>'P1923_DATA_TYPE'
,p_compute_when_text=>'BOOLEAN'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(1717483734469907.4003)
,p_computation_sequence=>10
,p_computation_item=>'P1923_PROFILE_COLUMN'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'ITEM_VALUE'
,p_computation=>'P1923_NAME'
,p_compute_when=>'P1923_PARAM_TYPE'
,p_compute_when_text=>'DATA_PROFILE'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(3161498249926714.4003)
,p_computation_sequence=>20
,p_computation_item=>'P1923_BOOLEAN_TRUE'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'substr( :P1923_FORMAT_MASK, 1, instr( :P1923_FORMAT_MASK, '','' ) - 1 )',
''))
,p_compute_when=>'P1923_DATA_TYPE'
,p_compute_when_text=>'BOOLEAN'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(3161534595926715.4003)
,p_computation_sequence=>30
,p_computation_item=>'P1923_BOOLEAN_FALSE'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case when instr( :P1923_FORMAT_MASK, '','' ) > 0 ',
