,p_parent_plug_id=>wwv_flow_imp.id(3439310821106145.4003)
,p_template=>wwv_flow_imp.id(770240542605907344.4003)
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:a-Alert--info:a-Alert--horizontal'
,p_component_template_options=>'#DEFAULT#:a-Report--staticRowColors:a-Report--noBorders:a-Report--stretch'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select listagg( name, '','' ) within group (order by null ) as cols',
'  from wwv_flow_data_profile_cols',
' where security_group_id         = :FLOW_SECURITY_GROUP_ID',
