wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226131367554626803.4003)
,p_name=>'P1925_ROW_SELECTOR'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(225858059630926546.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Zeilenselektor'
,p_source=>'ROW_SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie f\00FCr ein Datenprofil, das eine Tabelle zur\00FCckgibt, den Ausdruck ein, um die Collection der Zeilen in der Datenquelle auszuw\00E4hlen. Die Zeilen-Collection ist in der Regel ein JSON-Array oder eine XML-<em>Collection</em> (in XML eine Sequen')
||unistr('z von Tags mit demselben Namen). Verschachtelte Arrays oder verschachtelte XML-<em>Collections</em> werden nicht unterst\00FCtzt.'),
'</p>',
'<p>',
'    Wenn der Zeilenselektor ',
unistr('    ein einzelnes JSON-Objekt oder ein XML-Tag, das keine Collection ist, referenziert, muss das Datenprofilattribut <strong>Enth\00E4lt einzelne Zeile</strong> auf <strong>Ja</strong> gesetzt werden. Lassen Sie das Attribut leer, oder geben Sie <strong>')
||'"."</strong> ein, wenn das JSON-Array oder -Objekt sich auf Root-Ebene befindet. ',
'</p>',
'<h2>',
'    Beispiel 1:',
'</h2>',
'<pre>',
'{ "items": [',
'    { "ename": "SMITH", "sal": 200 },',
'    { "ename": "SCOTT", "sal": 100 } ] }',
'</pre>',
'<p>',
unistr('    Das JSON-Attribut enth\00E4lt ein Array im Attribut <strong>items</strong>. W\00E4hlen Sie dieses also als Zeilenselektor aus. Ein Element in diesem Array wird als Zeile betrachtet, und jedes Attribut wird als Spalte betrachtet.'),
'</p>',
'<h2>',
'    Beispiel 2:',
'</h2>',
'<pre>',
'{ "header": { "generated": "2018-10-19", "version": "1.0" },',
'  "body": { "items": [',
'          { "ename": "SMITH", "sal": 200 },',
'          { "ename": "SCOTT", "sal": 100 } ] } }',
'</pre>',
'<p>',
unistr('    Das JSON-Attribut enth\00E4lt ein Array im Attribut <strong>body.items</strong>. W\00E4hlen Sie dieses also als Zeilenselektor aus. Ein Element in diesem Array wird als Zeile betrachtet, und jedes Attribut wird als Spalte betrachtet.'),
'</p>',
' <h2>',
'    Beispiel 3:',
'</h2>',
'<pre>',
'&lt;xml-document&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SMITH&lt;/ename&gt;&lt;sal&gt;200&lt;/sal&gt;',
'  &lt;/row&gt;',
'  &lt;row&gt;',
'    &lt;ename&gt;SCOTT&lt;/ename&gt;&lt;sal&gt;100&lt;/sal&gt;',
'  &lt;/row&gt;',
'&lt;xml-document&gt;',
'</pre>   ',
'    <p>',
unistr('    Das XML-Tagattribut <strong>/xml-document/row</strong> enth\00E4lt eine <em>Collection</em>. W\00E4hlen Sie dieses also als Zeilenselektor aus. Jedes <strong>Zeilenobjekt</strong> wird als Zeile betrachtet, und jedes untergeordnete Tag von &lt;row&gt; wi')
||'rd als Spalte betrachtet.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
