wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1719176547469924.4003)
,p_name=>'P1926_PARENT_COLUMN'
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(225899656946244521.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('\00DCbergeordnete Spalte')
,p_source=>'PARENT_COLUMN_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'P1926_PARENT_COLUMNS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with msgs as (',
'    select wwv_flow_lang_dev.builder_message( ''WWV_FLOW_DATA_PROFILE.ARRAY_COLUMNS'' ) as array_cols_msg,',
'           wwv_flow_lang_dev.builder_message( ''WWV_FLOW_DATA_PROFILE.TABLE_COLUMNS'' ) as table_cols_msg',
'      from sys.dual )',
'select msg.array_cols_msg as column_type,',
'       dpc.display_name,',
'       dpc.id',
'  from wwv_flow_src_arr_cols_dev dpc,',
'       msgs                      msg',
' where dpc.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and dpc.flow_id           = :FB_FLOW_ID',
'   and dpc.data_profile_id   = :P1926_DATA_PROFILE_ID  ',
'union all ',
'select msg.table_cols_msg as column_type,',
'       dpc.name,',
'       dpc.id',
'  from wwv_flow_data_profile_cols dpc,',
'       msgs                       msg',
' where dpc.security_group_id     = :FLOW_SECURITY_GROUP_ID',
'   and dpc.flow_id               = :FB_FLOW_ID',
'   and dpc.data_profile_id       = :P1926_DATA_PROFILE_ID  ',
'   and dpc.data_type            in ( ''DOCUMENT_FRAGMENT'',''ARRAY'')',
'   and dpc.column_type           = ''TABLE'''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Kein Wert'
,p_cHeight=>1
,p_display_when=>'P1926_FORMAT'
,p_display_when2=>'JSON'
,p_display_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Wenn diese Spalte ein Attribut von <em>verschachtelten Zeilen</em> in der JSON-Antwort darstellt,',
unistr('    w\00E4hlen Sie die \00FCbergeordnete Spalte aus.'),
'</p>',
'<p>',
unistr('    <em>Rekursive Beziehungen verschachtelter Zeilen werden nicht unterst\00FCtzt.</em>'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
