,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    W\00E4hlen Sie eine einfache Transformationsregel zum \00C4ndern des hochgeladenen Wertes aus. Beispiel: Wenn die Quelldaten Spaltendaten in einem Format mit gemischter Gro\00DF-/Kleinschreibung enth\00E4lt, k\00F6nnen Sie die Daten mit <strong>In Kleinbuchstaben</s')
||unistr('trong> oder <strong>In Gro\00DFbuchstaben</strong> in die gew\00FCnschte Schreibweise konvertieren.'),
'    </p>',
'<ul>',
'    <li><strong>Links abschneiden</strong>, <strong>Rechts abschneiden</strong> und <strong>Abschneiden</strong>:<br> Zeichen abschneiden, die unter <strong>Ausdruck 1</strong> angegeben sind, und zwar links, rechts oder auf beiden Seiten des hochgel'
||'adenen Datenwertes.</li>',
'    <li><strong>Ersetzen</strong>:<br> Einfaches Ersetzen von <strong>Ausdruck&nbsp;1</strong> durch <strong>Ausdruck&nbsp;2</strong>.</li>',
unistr('    <li><strong>In Gro\00DFbuchstaben</strong>:<br> Wert in Gro\00DFbuchstaben konvertieren.</li>'),
'    <li><strong>In Kleinbuchstaben</strong>:<br> Wert in Kleinbuchstaben konvertieren.</li>',
'    <li><strong>Null if</strong>:<br> Wenn der hochgeladene Wert der unter <strong>Ausdruck&nbsp;1</strong> angegebenen Zeichenfolge entspricht, wird der Wert als NULL hochgeladen.</li>',
unistr('    <li><strong>Regul\00E4rer Ausdruck - Ersetzen</strong>:<br> Den unter <strong>Ausdruck&nbsp;1</strong> angegebenen regul\00E4ren Ausdruck anwenden und alle \00DCbereinstimmungen durch <strong>Ausdruck&nbsp;2</strong> ersetzen.</li>'),
unistr('    <li><strong>Regul\00E4rer Ausdruck - Null, wenn</strong>:<br> Bei einer \00DCbereinstimmung mit dem unter <strong>Ausdruck&nbsp;1</strong> angegebenen regul\00E4ren Ausdruck wird der Spaltenwert als NULL hochgeladen.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
