wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(7236251665718401.4003)
,p_validation_name=>'VARCHAR2 length is within limits'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'to_number( :P1926_MAX_LENGTH ) <= case ',
'                                  when :P1926_FORMAT in (''XML'', ''JSON'') ',
'                                      then case ',
'                                           when wwv_flow_db_version.c_has_extended_string_size',
'                                               then 32767',
'                                               else 4000 ',
'                                           end',
'                                  else 4000',
'                                  end'))
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>unistr('#LABEL# \00FCberschreitet den zul\00E4ssigen H\00F6chstwert')
,p_validation_condition=>':P1926_DATA_TYPE = ''VARCHAR2'' and :P1926_MAX_LENGTH is not null and :REQUEST in ( ''CREATE'',''APPLY_CHANGES'' )'
,p_validation_condition2=>'PLSQL'
