,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Informationen zum REST-Datenquellenserver werden als <strong>Remoteserverobjekt</strong> gespeichert. Remoteserver k\00F6nnen von mehreren REST-Datenquellen gemeinsam verwendet werden. \00C4nderungen der Eigenschaften von Remoteservern wirken sich auf all')
||unistr('e REST-Datenquellen aus, die dieses Objekt referenzieren. (Beispiel: Sie k\00F6nnen ein Remoteserverobjekt von einem Test- in ein Produktionssystem \00E4ndern.)</p>'),
'',
unistr('<p>Remoteserver werden auf Workspace-Ebene gespeichert und sind daher in allen Anwendungen sichtbar. Beim Exportieren einer Anwendung werden die verwendeten Remoteserver der Exportdatei hinzugef\00FCgt. Beim Importieren der Anwendung in einen anderen Wor')
||unistr('kspace pr\00FCft &PRODUCT_NAME., ob der Ziel-Workspace bereits Remoteserver mit derselben <strong>statischen ID</strong> enth\00E4lt. Wenn ein Remoteserver bereits vorhanden ist, verwendet die Anwendung diesen. Andernfalls werden die Remoteserver aus der Imp')
||'ortdatei im Ziel-Workspace erstellt.</p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249349483233883038.4003)
,p_plug_name=>'Remoteserver'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4003)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with data as (',
'    select s.id,',
'           s.name,',
'           s.server_type,',
'           s.base_url,',
'           s.static_id,',
'           nvl2( s.configuration_procedure, ''Y'', ''N'' ) dynamic,',
'           count(m.id)  module_references,',
'           count(ma.id) auth_references,',
'           count(f.id)  app_references',
'      from wwv_remote_servers s',
'           left outer join wwv_flow_web_src_modules m ',
'                      on (     s.security_group_id = m.security_group_id',
'                           and s.id                = m.remote_server_id )',
'           left outer join wwv_flow_web_src_modules ma ',
'                      on (     s.security_group_id = ma.security_group_id',
'                           and s.id                = ma.auth_remote_server_id )',
'           left outer join wwv_flows f ',
'                      on (     s.security_group_id = f.security_group_id',
'                           and (    s.id = f.print_remote_server_id ',
'                                 or s.id = f.file_remote_server_id ) )',
'        --',
'     where s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'', ''PRINT_SERVER'', ''CLOUD_OBJECT_STORE'' )',
'       and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'       and not exists ( select 1 ',
'                          from wwv_flow_language_map ',
'                         where translation_flow_id in ( m.flow_id, ma.flow_id, f.id ) )',
'     group by s.id, s.name, s.server_type, s.base_url, s.static_id, s.credential_id, s.configuration_procedure',
') ',
'select ',
'    id,',
'    name,',
'    server_type,',
'    base_url,',
'    static_id,',
'    dynamic,',
'    module_references + auth_references + app_references as references',
'from data',
''))
,p_plug_source_type=>'NATIVE_IR'
