wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2000804282223106.4003)
,p_name=>'P1932_CONFIGURATION_PROCEDURE'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(225856843527926534.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Konfigurationsprozedur'
,p_source=>'CONFIGURATION_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den Namen einer Prozedur ein, die die Endpunkt-URL zur Laufzeit konfiguriert.',
'Dabei kann es sich um eine gespeicherte oder eine im Element <em>PL/SQL-Code</em> definierte Prozedur handeln.',
unistr('Der Code unten ist f\00FCr eine Anwendung bestimmt, die Mehrmandantenf\00E4higkeit implementiert und'),
unistr('verschiedene <em>Endpunkt-URL</em>-Varianten f\00FCr die Mandanten unterst\00FCtzt.'),
unistr('Dabei wird je nach Kunde der Domainname in der URL ge\00E4ndert (Beispiel-URLs: '),
'https://cust-01.example.com, https://cust-02.example.com):',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'</code></pre><p>',
unistr('Die Prozedur kann 2 Attribute des in/out-Parameters <code>p_config</code> \00E4ndern,'),
'beide optional:',
'<ul>',
'    <li><code>base_url</code>:',
unistr('    \00C4ndert die <em>Endpunkt-URL</em>.'),
'    </li>',
'    <li><code>substitutions</code>:',
'    Weisen Sie Name/Wert-Paare mit <code>apex_t_varchar2</code> zu.',
'    &PRODUCT_NAME. ersetzt jeden <code>#NAME#</code> in der <em>Basis-URL</em> oder <em>Endpunkt-URL</em>.',
'    </li>',
'</ul>',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2000966576223107.4003)
,p_name=>'P1932_PLSQL_CODE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(225856843527926534.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'PL/SQL-Code'
,p_source=>'PLSQL_CODE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>50
,p_cMaxlength=>32000
,p_cHeight=>6
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Hier kann eine Prozedur, die die Endpunkt-URL zur',
'Laufzeit konfiguriert,',
'definiert werden.',
'Beispiele</p>',
'<pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'  p_config.base_url := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'end;',
'',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    -- expect endpoint url to be #host#/my_service',
'    p_config.substitutions := apex_t_varchar2();',
'    apex_string.plist_put( p_config.substitutions, ''host'', sys.owa_util.get_cgi_env(''HTTP_HOST'') );',
'end;',
'</code></pre>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL_FUNCTIONS',
