wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3850682801212121729.4003)
,p_name=>'P1941_WEB_SRC_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(3850682090247121721.4003)
,p_item_default=>'NATIVE_HTTP'
,p_prompt=>'REST-Datenquellentyp'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Bestimmt den Typ der REST-Datenquelle.',
'<ul>',
unistr('<li><strong>Einfaches HTTP</strong> gibt einen einfachen HTTP-Datenfeed an. &PRODUCT_NAME. geht davon aus, dass alle Daten bei der ersten Anforderung zur\00FCckgegeben werden und dass der Server keine serverseitige Filterung, Sortierung oder anderen erwe')
||unistr('iterten REST-Servicefeatures unterst\00FCtzt. Alle Aufrufdetails und -parameter m\00FCssen manuell konfiguriert werden.</li>'),
unistr('<li><strong>Oracle REST Data Services</strong> (ORDS) gibt von ORDS bereitgestellte RESTful Services an. Diese REST-Services entsprechen dem <em>Oracle-REST-Standard</em>, d.h. GET-, POST-, PUT- und DELETE-Vorg\00E4nge sind standardisiert. Serverseitige ')
||unistr('Filterung und Sortierung werden unterst\00FCtzt. &PRODUCT_NAME. kann diese Features nutzen, indem "Anordnen nach"-Attribute und Filter des Berichts an den REST-Service delegiert werden.</li>'),
unistr('<li>Eine <strong>REST-f\00E4hige SQL-Abfrage</strong> bezeichnet eine REST-Quelle auf einer SQL-Abfrage, die auf einer REST-f\00E4higen SQL-Referenz ausgef\00FChrt wird. &PRODUCT_NAME. unterst\00FCtzt auf diesen Endpunkten Filterung und Paginierung, aber keine DML.<')
||'/li>',
unistr('<li><strong>Oracle Cloud Applications (SaaS) REST Service</strong> gibt RESTful Webservices an, die von Oracle Cloud-SaaS-Anwendungen bereitgestellt werden. Mit diesem Webservicetyp k\00F6nnen Sie Oracle-SaaS-REST-Services in Ihre &PRODUCT_NAME.-Anwendun')
||unistr('g integrieren. &PRODUCT_NAME. unterst\00FCtzt die Paginierung f\00FCr diese Services.</li>'),
unistr('<li><strong>Oracle Cloud Infrastructure (OCI) REST Service</strong> gibt RESTful Webservices an, die von Oracle Cloud Infrastructure bereitgestellt werden. Mit diesem Webservicetyp k\00F6nnen Sie OCI-REST-Services (wie z.B. Zugriff auf den Objektspeicher')
||unistr(') in Ihre &PRODUCT_NAME.-Anwendung integrieren. &PRODUCT_NAME. unterst\00FCtzt die Paginierung f\00FCr diese Services.</li>'),
'<li><strong>OData REST Service</strong> gibt einen REST-Service an, der das Open Data-(OData-)Protokoll implementiert. Dabei handelt es sich um einen von ISO/IEC genehmigten OASIS-Standard, der Best Practices zum Erstellen und Nutzen von RESTful APIs'
||unistr(' definiert. <em>&PRODUCT_NAME. unterst\00FCtzt derzeit nur die <em>Abruf</em>-APIs (Daten lesen). DML-Vorg\00E4nge f\00FCr OData werden noch nicht unterst\00FCtzt.</em></li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
