,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load REST Enabled SQL Endpoint'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_exec_remote.get_configured_base_url(',
'    p_remote_server_id =>  id,',
'    p_application_id   => :FB_FLOW_ID ), ',
'       ''/_/sql'' ',
'  into :P1942_SERVER_URL,',
'       :P1942_WEB_SOURCE_PATH',
'  from wwv_remote_servers',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and id                = :P1941_REST_SQL_SERVER;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3850682751787121728.4003)
,p_process_when=>'P1941_WEB_SRC_TYPE'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'NATIVE_REST_ENABLED_SQL_QUERY'
,p_internal_uid=>2106434000647608.4003
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(226684303829475205.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Invoke URL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if wwv_flow_plugin_dev.has_standard_attribute(',
'       p_application_id => :FB_FLOW_ID,',
'       p_plugin_type    => wwv_flow_plugin.c_plugin_type_web_source,',
'       p_plugin_name    => :P1941_WEB_SRC_TYPE,',
'       p_feature        => ''NO_TEST_ENDPOINT'' )',
'then',
'    :P1941_SUCCESS           := ''Y'';',
'    :P1941_MUST_AUTHENTICATE := ''N'';',
'else',
'    wwv_flow_web_src_dev.f4000_test_endpoint_url(',
'        p_application_id   => :FB_FLOW_ID,',
'        p_endpoint_url     => :P1941_ENDPOINT_URL,',
'        p_https_host       => :P1941_HTTPS_HOST,',
'        p_web_source_type  => :P1941_WEB_SRC_TYPE,',
'        p_url_param1_name  => :P1941_URL_PARAM1_NAME,',
'        p_url_param1_value => :P1941_URL_PARAM1_VALUE,',
'        p_url_param2_name  => :P1941_URL_PARAM2_NAME,',
'        p_url_param2_value => :P1941_URL_PARAM2_VALUE,',
'        --',
'        p_param1_name      => :P1944_PARAM_NAME_1,',
'        p_param1_type      => :P1944_PARAM_TYPE_1,',
'        p_param1_value     => :P1944_PARAM_VALUE_1,',
'        p_param2_name      => :P1944_PARAM_NAME_2,',
'        p_param2_type      => :P1944_PARAM_TYPE_2,',
'        p_param2_value     => :P1944_PARAM_VALUE_2,',
'        --',
'        p_auth_required    => :P1941_MUST_AUTHENTICATE,',
'        p_success          => :P1941_SUCCESS,',
'        p_message          => :P1941_MESSAGE );',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3850682751787121728.4003)
,p_internal_uid=>226684303829475205.4003
);
end;
