wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226574766423012964.4003)
,p_name=>'P1943_AUTH_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(229756918559737172.4003)
,p_prompt=>'Authentifizierungstyp'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Ausw\00E4hlen -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie hier den Authentifizierungstyp an. Oracle APEX unterst\00FCtzt derzeit die folgenden Authentifizierungstypen:'),
'</p>',
'<ul>',
'    <li><strong>Basisauthentifizierung</strong>: Sendet Benutzernamen und Kennwort mit Base64 codiert als Header der <strong>Autorisierungsanforderung</strong>.',
'    </li>',
unistr('    <li><strong>OAuth2-Clientzugangsdaten</strong>: Oracle APEX tauscht die Client-ID und das Client Secret mit einer Tokenserver-URL gegen ein <strong>Zugriffstoken</strong> aus. Das Zugriffstoken wird dann zum Ausf\00FChren der eigentlichen Anforderung')
||' verwendet. Wenn das Zugriffstoken abgelaufen ist, fordert APEX transparent ein neues Token an.</li>',
'    <li><strong>Native OCI-Authentifizierung</strong>: Oracle APEX signiert Anforderungen an die <em>Oracle Cloud Infrastructure-(OCI-)</em>REST-API, wie in der <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Content/API/C'
||unistr('oncepts/signingrequests.htm">OCI-Dokumentation</a> beschrieben. Dieser Typ ist nur in Oracle Database 18c und h\00F6her verf\00FCgbar.</li>'),
unistr('    <li><strong>HTTP-Header</strong>: Die Zugangsdaten werden der REST-Anforderung als HTTP-Header hinzugef\00FCgt. Der Name der Zugangsdaten ist der HTTP-Headername, das Secret der Zugangsdaten ist der HTTP-Headerwert. Oracle APEX f\00FCgt diese Secrets nic')
||'ht dem Debuglog oder anderen Logs hinzu.</li>',
unistr('    <li><strong>URL-Abfragezeichenfolge</strong>: Die Zugangsdaten werden der URL der REST-Anforderung als <em>Abfragezeichenfolgenparameter</em> hinzugef\00FCgt (Beispiel: <strong>?name=value</strong>). Diese Option kann bei API-Schl\00FCsseln n\00FCtzlich sein')
||unistr('. Oracle APEX f\00FCgt diese Secrets nicht dem Debuglog oder anderen Logs hinzu. Proxy- oder andere Zwischenserver protokollieren diese Zugangsdaten allerdings in ihren Logdateien.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
