wwv_flow_imp_page.create_page(
 p_id=>1951.4003
,p_name=>'REST-Synchronisierung'
,p_alias=>'REST-DATA-SOURCE-SYNCHRONIZATION'
,p_step_title=>'REST-Synchronisierung'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(213347710073256556)
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var gCheckJobInterval = 0;',
'',
'function buildInterval() {',
'    var lIntervalString = ''FREQ='' + $v("P1951_INT_FREQUENCY") +',
'                          '';INTERVAL='' + $v("P1951_INT_INTERVAL");',
'    ',
'    if ( $v("P1951_BYDAY") !== "" && $v("P1951_INT_FREQUENCY") !== "DAILY" && $v("P1951_BYDAY") !== "MON:TUE:WED:THU:FRI:SAT:SUN" ) {',
'       lIntervalString =  lIntervalString + ";BYDAY=" + $v("P1951_BYDAY").replace(/:/g,",");',
'    }',
'    if ( $v("P1951_BYHOUR") !== "" && $v("P1951_INT_FREQUENCY") !== "HOURLY") {',
'       lIntervalString =  lIntervalString + ";BYHOUR=" + $v("P1951_BYHOUR");',
'    }',
'    if ( $v("P1951_BYMINUTE") !== "" && $v("P1951_INT_FREQUENCY") !== "MINUTELY" ) {',
'       lIntervalString =  lIntervalString + ";BYMINUTE=" + $v("P1951_BYMINUTE");',
'    }',
'    ',
'    lIntervalString =  lIntervalString + ";BYSECOND=0";',
'    ',
'    return lIntervalString;',
'}',
'',
'function setCheckJobTimeout() {',
'    //',
'    // the interval starts with 2 seconds, and is then increased by 2 seconds',
'    // for each iteration. However, the maximum interval is 10 seconds.',
'    //',
'    if ( gCheckJobInterval < 10000 ) {',
'        gCheckJobInterval = gCheckJobInterval + 2000;        ',
'    } else {',
'        gCheckJobInterval = 10000;',
'    }',
'    window.setTimeout( ',
'        function() {apex.event.trigger( $("#P1951_JOB_STATE"), "checkJobState" );},',
'        gCheckJobInterval );',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#sync-steps {min-height: 100px;}',
'',
'tr#MESSAGES {width: 200px;}',
'td[headers=MESSAGES] {width: 200px;}',
'',
'.log-messages {',
'    margin: 0px;',
'    max-width: 400px;}',
'       '))
,p_step_template=>wwv_flow_imp.id(689605897838965863.4003)
,p_page_template_options=>'#DEFAULT#'
);
