,p_plug_display_sequence=>70
,p_plug_source=>unistr('Diese Synchronisierung verwendet den Synchronisierungstyp "Konsolidieren", aber f\00FCr das Datenprofil ist keine Prim\00E4rschl\00FCsselspalte definiert. Daher treten Fehler bei Synchronisierungsjobs auf.')
,p_plug_display_condition_type=>'FUNCTION_BODY'
