wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3802161062901510.4003)
,p_plug_name=>'REST-Synchronisierung'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>40
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Mit der <strong>REST-Synchronisierung</strong> k\00F6nnen Sie die Inhalte einer lokalen Tabelle automatisch mit den Daten aus einem REST-Service synchronisieren. Die Synchronisierung kann manuell oder mit einem Scheduler-Job nach einem regelm\00E4\00DFigen Zeitp')
||unistr('lan ausgef\00FChrt werden.'),
'</p>',
'<p>',
unistr('APEX kann die lokale Tabelle basierend auf den sichtbaren Spalten im <strong>Datenprofil</strong> der REST-Datenquelle erstellen. Die Tabelle ist aber ein <em>sichtbares Objekt</em> im Datenbankschema. Das hei\00DFt, Entwickler <em>k\00F6nnen</em> Indizes hi')
||unistr('nzuf\00FCgen, physische Eigenschaften \00E4ndern oder sogar weitere Spalten zur Tabelle hinzuf\00FCgen. '),
'</p>',
'<p>',
unistr('Wenn die Tabelle <em>nicht</em> mit dem Datenprofil synchron ist, funktioniert die REST-Synchronisierung weiterhin f\00FCr Spalten, die <em>sowohl</em> in der Tabelle als auch im Datenprofil vorhanden sind (andere Spalten werden ignoriert). APEX generier')
||unistr('t allerdings SQL-DDL-Anweisungen zum Synchronisieren von Tabellenspalten mit dem Datenprofil. Diese k\00F6nnen der Anwendung als unterst\00FCtzende Objekte hinzugef\00FCgt werden.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
