' where collection_name = ''WWV_FLOW_IMPORT_CREDENTIALS''',
'   and c003 = ''Y'''))
,p_plug_footer=>unistr('<p>Zugangsdaten, die bereits im Workspace vorhanden sind, k\00F6nnen \00FCber <strong>Workspace-Utilitys</strong> bearbeitet werden.</p>')
