'with list_items as (',
'  select',
'    list_item_link_text,  ',
'    id, ',
'    list_item_display_sequence, ',
'    list_item_type, ',
'    substr(list_item_link_target,1,50) list_item_link_target, ',
'    parent_list_item_id,',
'    required_patch build_option,',
'    LIST_ITEM_DISP_COND_TYPE,',
'    last_updated_on, LIST_ITEM_ICON',
'  from wwv_flow_list_items',
'  where list_id = replace(:P2222_LIST_ID,''%''||''null%'',null)',
'    and flow_id = :FB_FLOW_ID',
'    and security_group_id = :WORKSPACE_ID',
