wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3302810263286926.4003)
,p_name=>'P2501_FORM_PAGE_MODE'
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(12401772860612912.4003)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if wwv_flow_user_interface_dev.drawer_page_template_exists(',
'                     p_application_id => :FB_FLOW_ID ) then ',
'    return ''DRAWER'';',
'elsif wwv_flow_user_interface_dev.dialog_page_template_exists(',
'                     p_application_id => :FB_FLOW_ID ) then ',
'    return ''MODAL'';',
'else',
'    return ''NORMAL'';',
'end if;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Formularseitenmodus'
,p_display_as=>'NATIVE_RADIOGROUP'
