,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'FUNCTION_BODY'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Identifizieren Sie den Seitenmodus basierend auf den folgenden Optionen: <p/>',
'<ul>',
'<li><strong>Normal</strong>: Die Seite wird als normale &PRODUCT_NAME.-Anwendungsseite angezeigt.</li>',
unistr('<li><strong>Modales Dialogfeld</strong>: Die Seite wird als modales Dialogfeld dargestellt. Ein modales Dialogfeld ist ein \00DCberlagerungsfenster innerhalb des Viewports, das aktiv und fokussiert bleibt, bis der Endbenutzer es verwirft (schlie\00DFt). Die ')
||'zugrunde liegende Seite ist ausgegraut, und der Endbenutzer kann nicht mehr mit der restlichen Seite interagieren, bis das Dialogfeld geschlossen wird.</li>',
unistr('<li><strong>Drawer</strong>: Setzt den Seitenmodus auf <strong>Modales Dialogfeld</strong> und verwendet das <strong>Drawer</strong>-Template f\00FCr die Seite. Diese Option ist nur verf\00FCgbar, wenn das aktuelle Anwendungs-Theme das Seitentemplate <strong')
||unistr('>Drawer</strong> enth\00E4lt.</li>'),
'</ul>',
'<br><p>',
unistr('Beachten Sie, dass die Option "Modales Dialogfeld" nur ausgew\00E4hlt werden kann, wenn das aktuelle Anwendungs-Theme mindestens ein Seitentemplate vom Typ <strong>Dialogseite</strong> enth\00E4lt.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
