,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Identifizieren Sie eine Symbolklasse f\00FCr das mit diesem Listeneintrag verkn\00FCpfte Symbol.'),
'<br><br>',
'<strong>Universal Theme verwenden</strong>',
'<br>',
unistr('Die meisten Universal Theme-Apps verwenden die Symbol-Library Font APEX. W\00E4hlen Sie in der integrierten Symbolauswahl im Popup-Fenster ein Symbol aus:<br><br>'),
'<ul>',
'    <li><code>fa-cloud</code>: Zeigt das Cloud-Symbol an</li>',
