wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1711877889712206.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Page Pattern Conditions'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_has_breadcrumb boolean := false;',
'begin',
'    select page_mode',
'      into :p2501_page_mode',
'      from wwv_flow_steps',
'     where flow_id           = :fb_flow_id',
'       and security_group_id = :workspace_id',
'       and id                = :p2501_page_pattern_page_id;',
'',
'    if :p2501_page_mode in (''MODAL'',''NON_MODAL'') then',
'        :p2501_use_breadcrumb := ''N'';',
'        :p2501_use_navlist    := ''N'';',
'    else',
'        --',
'        -- Check if the pattern has a breadcrumb',
'        --',
'        for c in (',
'            select plug_source_type',
'              from wwv_flow_page_plugs',
'             where flow_id           = :fb_flow_id',
'               and security_group_id = :workspace_id',
'               and page_id           = :p2501_page_pattern_page_id',
'               and plug_source_type = ''NATIVE_BREADCRUMB'' )',
'        loop',
'            l_has_breadcrumb := true;',
'            exit;',
'        end loop;',
'        if not l_has_breadcrumb then',
'            :p2501_use_breadcrumb := ''N'';',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P2500_CATEGORY'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'PATTERN'
,p_internal_uid=>1711877889712206.4003
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4220811154605008.4003)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update APEX Dictionary Cache'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_object_type wwv_flow_tables_views_dev.object_type%type;',
'begin',
'    select object_type',
'      into l_object_type',
'      from wwv_flow_tables_views_dev',
'     where owner       = :P2501_TABLE_OWNER',
'       and object_name = :P2501_TABLE_NAME;',
'',
'    --- if table, set APEX dictionary cache',
'    if l_object_type = ''TABLE'' then',
'        wwv_dictionary_cache_dev.set_dictionary_table_cache(',
'             p_workspace_name          => htmldb_util.find_workspace( p_security_group_id => :WORKSPACE_ID ),',
'             p_schema                  => :P2501_TABLE_OWNER,',
'             p_table_name              => :P2501_TABLE_NAME,',
'             p_flow_id                 => :FB_FLOW_ID,',
'             p_cache_fk_references     => true );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P2501_SHOW_DATA_SOURCE = ''Y'' and :P2501_LOCATION = ''LOCAL'' and :P2501_SOURCE_TYPE = ''TABLE'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>4220811154605008.4003
);
wwv_flow_imp_page.create_page_process(
