wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19904252956194932.4003)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_number number;',
'    l_collection_name varchar2(20) := ''CREATE_WIZARD'';',
'begin',
'    -- this collection is cleared during the brnach process to this page',
'    -- wwv_flow_collection.create_or_truncate_collection( l_collection_name );',
'    -- by default add 3 wizard steps',
'    if wwv_flow_collection.collection_member_count( p_collection_name => ''CREATE_WIZARD'') = 0 then',
'        for i in 1..3',
'        loop',
'            l_page_number := wwv_flow_utilities.minimum_free_page(:FB_FLOW_ID,1);',
'            wwv_flow_collection.add_member(',
'                p_collection_name => l_collection_name,',
'                p_c001            => i,',
