wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4405671361104842.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Tree Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_start_value              varchar2(4000) := null;',
'  l_start_sql                varchar2(4000) := null;',
'  l_default_region_template  wwv_flow_themes.default_region_template%type;',
'begin',
'  -- Start With Column Value',
'  if :P2512_START_TREE = ''ITEM'' then',
'      l_start_value := '':''||:P2512_START_ITEM;',
'  elsif :P2512_START_TREE = ''STATIC'' then',
'      l_start_value := :P2512_START_STATIC_VALUE;',
'  elsif :P2512_START_TREE = ''SQL'' then',
'      l_start_sql   := trim(trailing '';'' from :P2512_SQL);',
'      l_start_value := ''(''||l_start_sql||'')'';',
'  end if;',
'  ',
'  select default_region_template',
'    into l_default_region_template',
'    from wwv_flow_themes',
'   where flow_id           = :FB_FLOW_ID',
'     and security_group_id = :WORKSPACE_ID',
'     and theme_id          = :FB_THEME_ID;',
'',
'  wwv_flow_wizard_api.create_jstree (',
'     p_flow_id                  => :FB_FLOW_ID,',
'     p_page_id                  => :P2501_PAGE_ID,',
'     p_page_name                => :P2501_PAGE_NAME,',
'     p_page_mode                => :P2501_PAGE_MODE,',
'     --',
'     p_nav_list_id              => :P2500_NAVLIST_ID,',
'     p_nav_list_parent_item_id  => :P2501_NAVLIST_PARENT_ID,',
'     p_nav_list_child_item_name => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'     p_nav_list_item_icon       => :P2501_PAGE_ICON,',
'     --',
'     p_breadcrumb_id            => :P2501_BREADCRUMB_ID,',
'     p_breadcrumb_name          => :P2501_PAGE_NAME,',
'     p_parent_bc_id             => :P2501_BREADCRUMB_PARENT_ID,',
'     --',
'     p_region_template          => l_default_region_template,',
'     p_region_name              => :P2501_PAGE_NAME, ',
'     --',
'     p_tree_query               => wwv_flow_wizard_api.generate_tree_region_query (',
'                                       p_flow_id      => :FB_FLOW_ID,',
'                                       p_owner        => wwv_flow_wizard_api.get_owner(',
'                                                            :FB_FLOW_ID,',
'                                                            :P2501_TAB_OWNER ),',
'                                       p_table_name   => :P2501_TAB_NAME,',
'                                       p_id           => :P2512_ID,',
'                                       p_pid          => :P2512_PID,',
'                                       p_name         => :P2512_NAME,',
'                                       p_start_item   => :P2512_START_NODE,',
'                                       p_start_value  => l_start_value,',
'                                       p_link_option  => null,',
'                                       p_link_page_id => null,',
'                                       p_link_item    => null,',
'                                       p_where        => null,',
'                                       p_order_by     => :P2512_NAME,',
'                                       p_tooltip      => null,',
'                                       p_icon         => null),',
'     p_tree_button_option       => :P2512_TREE_BUTTON_OPTIONS,',
'     p_show_hints               => null,',
'     p_tree_hint_text           => null,',
'     p_tree_click_action        => ''S'',',
'     p_selected_node            => null );',
'       ',
'  :F4000_RUN_EDIT_PAGE   := :P2501_PAGE_ID;',
'  :FB_FLOW_PAGE_ID       := :P2501_PAGE_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Baumseite kann nicht erstellt werden.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8501210649264168.4003)
,p_internal_uid=>4405671361104842.4003
);
