wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(11528602845540901.4003)
,p_computation_sequence=>10
,p_computation_item=>'P2513_MEDIA_LIST_EXISTS'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for l_media_list in (',
'        select r.id',
'          from wwv_flows f,',
'               wwv_flow_themes t,',
'               wwv_flow_row_templates r',
'         where f.id                  = :FB_FLOW_ID',
'           and f.security_group_id   = :WORKSPACE_ID',
'           and t.flow_id             = f.id',
'           and t.theme_id            = f.theme_id',
'           and t.security_group_id   = f.security_group_id',
'           and t.theme_internal_name = ''UNIVERSAL_THEME''',
'           and ( r.flow_id, f.theme_id, r.security_group_id ) in',
'               ( ( :FB_FLOW_ID, t.theme_id, :WORKSPACE_ID ),',
'                 ( ( select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, t.theme_id ) from sys.dual ),',
'                   ( select wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, t.theme_id ) from sys.dual ),',
'                   ( select wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, t.theme_id ) from sys.dual ) ) )',
'           and r.internal_name       = ''MEDIA_LIST'' )',
'    loop',
'        return ''Y'';',
'    end loop;',
'    return ''N'';',
'end;'))
);
