,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update APEX Dictionary Cache'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_object_type wwv_flow_tables_views_dev.object_type%type;',
'begin',
'    select object_type',
'      into l_object_type',
'      from wwv_flow_tables_views_dev',
'     where owner       = :P3113_ORATEXT_TABLE_OWNER',
'       and object_name = :P3113_ORATEXT_TABLE_NAME;',
'',
'    --- if table, set APEX dictionary cache',
'    if l_object_type = ''TABLE'' then',
'        wwv_dictionary_cache_dev.set_dictionary_table_cache(',
'             p_workspace_name          => htmldb_util.find_workspace( p_security_group_id => :WORKSPACE_ID ),',
'             p_schema                  => :P3113_ORATEXT_TABLE_OWNER,',
