wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1760805302180991.4003)
,p_name=>'P3120_SEARCH_PREFIX'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1757925019180889.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4003)
,p_prompt=>unistr('Suchabfragepr\00E4fix')
,p_source=>'SEARCH_PREFIX'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>60
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie ein Pr\00E4fix ein, das von Endbenutzern in Suchabfragen verwendet werden soll. Ein Suchbegriff mit Pr\00E4fix wird nur f\00FCr Suchkonfigurationen'),
unistr('    mit demselben Pr\00E4fix verwendet. Wenn eine Suchabfrage ein Pr\00E4fix enth\00E4lt, das in '),
unistr('    <em>keiner</em> Suchkonfiguration definiert wird, wird das Pr\00E4fix ignoriert, und der vollst\00E4ndige Begriff wird f\00FCr die Suche verwendet.'),
'</p>',
'<p>Beispiele:</p>',
unistr('<p> Es gibt zwei Suchkonfigurationen: <strong>Mitarbeiter</strong> mit dem Pr\00E4fix <strong>emp</strong>, '),
unistr('    und <strong>Jobs</strong> mit dem Pr\00E4fix <strong>job</strong>.'),
'</p>',
'<dl>',
'    <dt>emp:king president</dt>',
unistr('    <dd>Das Schl\00FCsselwort <strong>king</strong> wird nur in der Suchkonfiguration <strong>Mitarbeiter</strong> '),
'        gesucht, <strong>president</strong> hingegen in beiden Konfigurationen.</dd>',
'    <dt>emp:king job:president</dt>',
unistr('    <dd>Das Schl\00FCsselwort <strong>king</strong> wird nur in der Suchkonfiguration <strong>Mitarbeiter</strong> '),
unistr('        gesucht, w\00E4hrend <strong>president</strong> nur in <strong>Jobs</strong> gesucht wird.</dd>'),
'    <dt>emp:king depts:"new york"</dt>',
unistr('    <dd>Das Schl\00FCsselwort <strong>king</strong> wird nur in der Suchkonfiguration <strong>Mitarbeiter</strong> '),
'        gesucht. <strong>depts:"new york"</strong> wird in beiden Konfigurationen gesucht,',
unistr('        weil das Pr\00E4fix <strong>depts</strong> nicht definiert wurde.</dd>'),
'</dl>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
