,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'  <li>',
'    <strong>Standard:</strong>',
'    Definieren Sie eine durchsuchbare Datenquelle. Dabei kann es sich um eine Tabelle, SQL-Abfrage oder REST-Datenquelle handeln. ',
unistr('    Die Suche wird mit einer SQL-Abfrage mit LIKE-Ausdr\00FCcken ausgef\00FChrt. '),
'  </li>',
'  <li>',
'    <strong>Oracle-Vektorsuche:</strong>',
unistr('    Suche mit der Oracle-Vektorsuche (erfordert Oracle Database 23ai oder h\00F6her).<br/>'),
'    Erfordert einen Vektorprovider, mit dem die Einbettung einer Suchphrase abgerufen wird.',
'  </li>',
'  <li>',
'     <strong>Oracle Text:</strong>',
unistr('    Definieren Sie eine durchsuchbare Tabelle oder SQL-Abfrage, f\00FCr die bereits ein Oracle Text-Index erstellt wurde. Die Suche'),
unistr('    wird mit der Oracle Text-Funktionalit\00E4t ausgef\00FChrt, die linguistische und Fuzzysuchen'),
unistr('    erm\00F6glicht.'),
'  </li>',
'  <li>',
'    <strong>Umfassende Datenbanksuche:</strong>',
unistr('    Suchen Sie anhand eines umfassenden Suchindex (erfordert Oracle Database 23ai oder h\00F6her).<br/>'),
'    <em>Der Index muss sich im Parsingschema der Anwendung befinden.</em>',
'  </li>',
'  <li>',
'    <strong>Liste:</strong>',
unistr('    Suchen Sie innerhalb einer ausgew\00E4hlten <em>Liste</em> unter "Gemeinsame Komponenten".'),
'  </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'Y',
  'show_line_breaks', 'Y')).to_clob
);
