wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1776874750181057.4003)
,p_name=>'P3120_DEFAULT_ROW_HTML_EXPR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>170
,p_item_plug_id=>wwv_flow_imp.id(6700676601775302.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4003)
,p_prompt=>unistr('Standardtemplate f\00FCr Ergebniszeilen')
,p_source=>'DEFAULT_ROW_HTML_EXPR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>60
,p_cMaxlength=>4000
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Geben Sie zum Anzeigen einer Suchergebniszeile einen HTML-Ausdruck ein. Mit der <code>&COLUMN.</code>-Syntax werden Spaltenwerte in HTML angezeigt. Unterst\00FCtzt Templatedirektiven. Au\00DFerdem sind folgende Ersetzungen verf\00FCgbar:'),
'</p>',
'<dl>',
'<dt>ICON_TYPE</dt>',
'<dd>Stellt den Symboltyp dar: Kann <strong>CLASS</strong>, <strong>URL</strong> oder <strong>INITIALS</strong> sein.</dd>',
'<dt>ICON_VALUE</dt>',
unistr('<dd>Der tats\00E4chliche Symbolwert, je nach dem Wert von <strong>ICON_TYPE</strong></dd>'),
'<dt>RESULT_CSS_CLASSES</dt>',
'<dd>Die auf jedes Ergebnis angewendeten CSS-Klassen, basierend auf dem Attribut <strong>Ergebnis-CSS-Klassen</strong>.</dd>',
'<dt>APEX$ORATEXT_SCORE</dt>',
unistr('<dd>Spalte, die den Oracle Text-Score f\00FCr Oracle Text-Suchtypen darstellt.</dd>'),
'<dt>APEX$VECTOR_DISTANCE</dt>',
unistr('<dd>Spalte, die den Vektorabstand f\00FCr die Suchtypen der Oracle-Vektorsuche darstellt.</dd>'),
'</dl>',
'<p>Beispiel:</p>',
'<pre>',
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
'        &lt;div class="a-ResultItem-image"&gt;&lt;img src="&amp;ICON_VALUE!ATTR." alt="&amp;ENAME!ATTR." role="presentation" /&gt;&lt;/div&gt;',
'      {when CLASS/}',
'        &lt;div class="a-ResultItem-icon u-color-var"&gt;&lt;span class="fa &amp;ICON_VALUE!ATTR." aria-hidden="true"&gt;&lt;/span&gt;&lt;/div&gt;',
'    {endcase/}',
'  {endif/}',
'  &lt;div class="a-ResultsItem-content"&gt;',
'    &lt;div class="a-ResultsItem-header"&gt;',
'      &lt;span class="a-ResultsItem-title"&gt;&lt;a href="f?p=&amp;APP_ID.:&amp;20:&amp;SESSION.::::P20_EMPNO:&amp;EMPNO."&gt;&amp;ENAME.&lt;/a&gt;&lt;/span&gt;',
'      &lt;span class="a-ResultsItem-badge"&gt;&amp;SAL.&lt;/span&gt;',
'    &lt;/div&gt;',
'    &lt;div class="a-ResultsItem-description"&gt;&amp;RESUMEE.&lt;/div&gt;',
'    &lt;div class="a-ResultsItem-attributes"&gt;',
'      {if ?COMM/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;COMM.&lt;/span&gt;{endif/}',
'      {if ?JOB/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;JOB.&lt;/span&gt;{endif/}',
'    &lt;/div&gt;',
'    &lt;div class="a-ResultsItem-misc"&gt;&amp;HIREDATE.&lt;/div&gt;',
'  &lt;/div&gt;',
'&lt;/div&gt;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
