'           p_location               => :P3120_LOCATION,',
'           --  ',
'           p_query_type             => :P3120_QUERY_TYPE,',
'           p_table_owner            => :P3120_QUERY_OWNER,',
'           p_table_name             => :P3120_QUERY_TABLE,',
'           p_where_clause           => case when :P3120_QUERY_TYPE = ''GRAPH'' then :P3120_PQL_WHERE_CLAUSE else :P3120_QUERY_WHERE end,',
'           p_match_clause           => :P3120_PQL_MATCH_CLAUSE,',
'           p_columns_clause         => :P3120_PQL_COLUMNS_CLAUSE,',
'           p_order_by_clause        => :P3120_QUERY_ORDER_BY,',
'           p_sql_query              => :P3120_QUERY_SQL,',
'           p_function_body          => :P3120_QUERY_SQL,',
'           p_function_body_language => :P3120_QUERY_FUNC_LANG,',
'           p_optimizer_hint         => :P3120_OPTIMIZER_HINT );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>':P3120_SEARCH_TYPE = ''SIMPLE'' and :P3120_LOCATION = ''LOCAL'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_when_button_pressed=>wwv_flow_imp.id(1799745296181261.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(4203820270667407.4003)
,p_validation_name=>'Valid Oracle Text Search Config Query'
,p_validation_sequence=>190
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--',
'-- validate_query also validates that required items actually contain',
'-- a value (e.g. Table Name for Query Type = TABLE)',
'return wwv_flow_exec_dev.validate_query (',
'           p_application_id       => :FB_FLOW_ID,',
'           p_location             => wwv_flow_exec_api.c_location_local_db,',
'           --',
'           p_query_type           => :P3120_ORATEXT_SOURCE_TYPE,',
'           p_table_owner          => :P3120_ORATEXT_OWNER,',
'           p_table_name           => :P3120_ORATEXT_TABLE,',
'           p_where_clause         => :P3120_ORATEXT_WHERE,',
'           p_order_by_clause      => :P3120_ORATEXT_ORDER_BY,',
'           p_sql_query            => :P3120_ORATEXT_SQL );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P3120_SEARCH_TYPE = ''TEXT_MANUAL'' and',
'   :P3120_ORATEXT_TABLE is not null and',
'   wwv_flow_f4000_util.does_table_view_exist (',
'            p_owner       => :P3120_ORATEXT_OWNER,',
'            p_object_name => :P3120_ORATEXT_TABLE ) then',
'    -- if Text Search, text table not null',
'    -- and correct P3120_ORATEXT_TABLE entered',
'    -- validate',
'    return true;',
'else',
'    -- if NOT Text Search, do NOT validate',
'    return false;',
'end if;'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'FUNCTION_BODY'
,p_when_button_pressed=>wwv_flow_imp.id(1799745296181261.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
