wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2419634810518824.4003)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Distribute Item Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    procedure clear_local_source is',
'    begin',
'        :P3120_QUERY_TYPE            := null;',
'        :P3120_QUERY_OWNER           := null;',
'        :P3120_QUERY_TABLE           := null;',
'        :P3120_QUERY_SQL             := null;',
'        :P3120_QUERY_FUNC_LANG       := null;',
'        :P3120_QUERY_FUNC_BODY       := null;',
'        :P3120_QUERY_WHERE           := null;',
'        :P3120_QUERY_ORDER_BY        := null;',
'        :P3120_OPTIMIZER_HINT        := null;',
'    end clear_local_source;',
'begin',
'    if :P3120_SEARCH_TYPE in ( ''SIMPLE'', ''TEXT_MANUAL'', ''TEXT_DBMS_SEARCH'', ''VECTOR'' ) then',
'    ',
'        if :P3120_SEARCH_TYPE = ''TEXT_MANUAL'' then',
'            :P3120_ORATEXT_SOURCE_TYPE := :P3120_QUERY_TYPE;',
'            :P3120_ORATEXT_OWNER       := :P3120_QUERY_OWNER;',
'            :P3120_ORATEXT_TABLE       := :P3120_QUERY_TABLE;',
'            :P3120_ORATEXT_WHERE       := :P3120_QUERY_WHERE;',
'            :P3120_ORATEXT_ORDER_BY    := :P3120_QUERY_ORDER_BY;',
'            case :P3120_ORATEXT_SOURCE_TYPE',
'                when ''SQL'' then :P3120_ORATEXT_SQL := :P3120_QUERY_SQL;',
'                else null;',
'            end case;',
'',
'            clear_local_source;',
'        elsif :P3120_SEARCH_TYPE = ''TEXT_DBMS_SEARCH'' then',
'            :P3120_SEARCH_SOURCE_OWNER := :P3120_QUERY_OWNER;',
'            :P3120_SEARCH_SOURCE_NAME  := :P3120_QUERY_TABLE;',
'            :P3120_SEARCH_ORDER_BY     := :P3120_QUERY_ORDER_BY;',
'',
'            clear_local_source;',
'        elsif :P3120_SEARCH_TYPE = ''VECTOR'' then',
'            :P3120_VECTOR_SOURCE_TYPE := :P3120_QUERY_TYPE;',
'            :P3120_VECTOR_OWNER       := :P3120_QUERY_OWNER;',
'            :P3120_VECTOR_TABLE       := :P3120_QUERY_TABLE;',
'            :P3120_VECTOR_COLUMN      := :P3120_ORATEXT_INDEX_COLUMN;',
'            :P3120_VECTOR_WHERE       := :P3120_QUERY_WHERE;',
'            case :P3120_VECTOR_SOURCE_TYPE',
'                when ''SQL'' then :P3120_VECTOR_SQL := :P3120_QUERY_SQL;',
'                else null;',
'            end case;',
'',
'            clear_local_source;',
'        else',
'            if :P3120_LOCATION = ''LOCAL'' then',
'                case :P3120_QUERY_TYPE',
'                    when ''FUNC_BODY_RETURNING_SQL'' then :P3120_QUERY_FUNC_BODY  := :P3120_QUERY_SQL;',
'                    when ''GRAPH''                   then :P3120_GRAPH_NAME       := :P3120_QUERY_TABLE;',
'                                                        :P3120_PQL_WHERE_CLAUSE := :P3120_QUERY_WHERE;',
'                                                        :P3120_QUERY_TABLE      := null;',
'                                                        :P3120_QUERY_WHERE      := null;',
'                    else null;',
'                end case;',
'            elsif :P3120_LOCATION = ''REMOTE'' then',
'                :P3120_REMOTE_SOURCE_TYPE      := :P3120_QUERY_TYPE;',
'                :P3120_REMOTE_TABLE_OWNER      := :P3120_QUERY_OWNER;',
'                :P3120_REMOTE_TABLE_NAME       := :P3120_QUERY_TABLE;',
'                :P3120_REMOTE_WHERE            := :P3120_QUERY_WHERE;',
'                :P3120_REMOTE_ORDER_BY         := :P3120_QUERY_ORDER_BY;',
'    ',
'                case :P3120_REMOTE_SOURCE_TYPE',
'                    when ''SQL''                     then :P3120_REMOTE_SQL := :P3120_QUERY_SQL;',
'                    when ''FUNC_BODY_RETURNING_SQL'' then',
'                        :P3120_REMOTE_FUNC_BODY_LANG := :P3120_QUERY_FUNC_LANG;',
'                        :P3120_REMOTE_FUNC_BODY      := :P3120_QUERY_SQL;',
'                    else null;',
'                end case;',
'    ',
'                clear_local_source;',
'                ',
'            elsif :P3120_LOCATION = ''WEB_SOURCE'' then',
'                if :P3120_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P3120_POST_PROC_WHERE          := :P3120_QUERY_WHERE;',
'                    :P3120_POST_PROC_ORDER_BY       := :P3120_QUERY_ORDER_BY;',
'                elsif :P3120_POST_PROC_TYPE = ''SQL'' then',
'                    :P3120_POST_PROC_SQL            := :P3120_QUERY_SQL;',
'                elsif :P3120_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P3120_POST_PROC_FUNC_LANG      := :P3120_QUERY_FUNC_LANG;',
'                    :P3120_POST_PROC_FUNC_BODY      := :P3120_QUERY_SQL;',
'                end if;',
'    ',
'                :P3120_POST_PROC_TYPE := coalesce( :P3120_POST_PROC_TYPE, ''NONE'' );',
'    ',
'                clear_local_source;',
'',
'            elsif :P3120_LOCATION = ''JSON_COLLECTION'' then',
'                if :P3120_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P3120_JSON_POST_WHERE          := :P3120_QUERY_WHERE;',
'                    :P3120_JSON_POST_ORDER_BY       := :P3120_QUERY_ORDER_BY;',
'                elsif :P3120_POST_PROC_TYPE = ''SQL'' then',
'                    :P3120_JSON_POST_SQL            := :P3120_QUERY_SQL;',
'                elsif :P3120_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P3120_JSON_POST_FUNC_LANG      := :P3120_QUERY_FUNC_LANG;',
'                    :P3120_JSON_POST_FUNC_BODY      := :P3120_QUERY_SQL;',
'                end if;',
'',
'                :P3120_JSON_SOURCE_ID        := :P3120_DOCUMENT_SOURCE_ID;',
'                :P3120_JSON_SRC_ARRAY_COL_ID := :P3120_WEB_SRC_ARRAY_COL_ID;',
'    ',
'                :P3120_JSON_POST_TYPE := coalesce( :P3120_POST_PROC_TYPE, ''NONE'' );',
'    ',
'                clear_local_source;',
'',
'            elsif :P3120_LOCATION = ''DUALITY_VIEW'' then',
'                if :P3120_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P3120_DV_POST_WHERE          := :P3120_QUERY_WHERE;',
'                    :P3120_DV_POST_ORDER_BY       := :P3120_QUERY_ORDER_BY;',
'                elsif :P3120_POST_PROC_TYPE = ''SQL'' then',
'                    :P3120_DV_POST_SQL            := :P3120_QUERY_SQL;',
'                elsif :P3120_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P3120_DV_POST_FUNC_LANG      := :P3120_QUERY_FUNC_LANG;',
'                    :P3120_DV_POST_FUNC_BODY      := :P3120_QUERY_SQL;',
'                end if;',
'',
'                :P3120_DUALITY_VIEW_ID   := :P3120_DOCUMENT_SOURCE_ID;',
'                :P3120_DV_ARRAY_COL_ID   := :P3120_WEB_SRC_ARRAY_COL_ID;',
'    ',
'                :P3120_DV_POST_TYPE := coalesce( :P3120_POST_PROC_TYPE, ''NONE'' );',
'    ',
'                clear_local_source;                ',
'            end if;',
'',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2419634810518824.4003
);
