wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2317449986492645.4003)
,p_name=>'P3505_SQL'
,p_data_type=>'CLOB'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(2316239026492633.4003)
,p_prompt=>'SQL-Abfrage'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cMaxlength=>32767
,p_cHeight=>14
,p_field_template=>wwv_flow_imp.id(561549716994252345.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie als Kontext f\00FCr den KI-Service die SQL-Abfrage an, die die CSV-Ausgabe generiert. In der Abfrage k\00F6nnen Sie die folgenden speziellen Bind-Variablen verwenden, um den Prompt des Benutzers abzurufen und auszuwerten:'),
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
'    <dd>Ruft den zuletzt von einem Benutzer eingegebenen Prompt ab.</dd>',
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Ruft alle Benutzer-Prompts ab, verkettet zu einer Zeichenfolge.</dd>',
'</dl>',
'</p>',
unistr('<p>Hinweis: Die Anzahl der Zeilen, die in die Ausgabe aufgenommen werden, ist auf das im Attribut <em>Maximale Anzahl Token</em> angegebene Maximum beschr\00E4nkt. Der absolute Grenzwert betr\00E4gt 10000 Zeilen.</p>'),
'',
'<p>Beispiel:</p>',
'<pre>',
'select e.empno as "Employee No",',
'       e.ename as "Employee Name",',
'       e.job   as "Job",',
'       e.sal   as "Salary",',
'       d.dname as "Department"',
'  from emp e',
'  left join dept d on d.deptno = e.deptno',
' order by e.ename',
'fetch first 100 rows only',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'SQL',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
