,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie einen PL/SQL-Funktionsbody an, der ein CLOB zur\00FCckgibt und den Kontext f\00FCr den KI-Service generiert. In dem Code k\00F6nnen Sie die folgenden speziellen Bind-Variablen verwenden um den Prompt des Benutzers abzurufen und auszuwerten:'),
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
'    <dd>Ruft den zuletzt vom Benutzer eingegebenen Prompt ab.</dd>',
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Ruft alle Benutzer-Prompts ab, verkettet zu einer Zeichenfolge.</dd>',
'</dl>',
'</p>',
'',
'<p>Beispiel:</p>',
'<pre>',
'begin',
'    if lower( :APEX$AI_LAST_USER_PROMPT ) like ''%employee%'' then',
'        return ''Employee data'';',
'    else',
'        return ''Other data'';',
'    end if;',
'end;',
'</pre>'))
