,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Gibt an, ob die Anwendung verf\00FCgbar ist. <p>'),
unistr('M\00F6gliche Optionen:<br>'),
'<ul>',
unistr('<li><strong>Verf\00FCgbar</strong> - Die Anwendung ist uneingeschr\00E4nkt verf\00FCgbar.</li>'),
unistr('<li><strong>Mit Entwicklersymbolleiste verf\00FCgbar</strong> - Die Anwendung ist verf\00FCgbar. Entwicklern wird hierbei die Entwicklersymbolleiste unten auf den Seiten angezeigt, wenn sie bei App Builder in derselben Browsersession angemeldet sind.</li>'),
unistr('<li><strong>Nur verf\00FCgbar f\00FCr Entwickler</strong> - Die Anwendung steht nur Benutzern mit Entwicklerberechtigungen zur Verf\00FCgung.</li>'),
unistr('<li><strong>Eingeschr\00E4nkter Zugriff</strong> - Die Anwendung ist f\00FCr Entwickler verf\00FCgbar, die unter "Auf durch Kommas getrennte Benutzerliste einschr\00E4nken" genannt werden.</li>'),
unistr('<li><strong>Nicht verf\00FCgbar</strong> - Die Anwendung kann nicht ausgef\00FChrt oder bearbeitet werden. Wenn Benutzer versuchen, auf die Anwendung zuzugreifen, wird die Meldung wegen nicht verf\00FCgbarer Anwendung angezeigt.</li>'),
unistr('<li><strong>Nicht verf\00FCgbar (Status mit PL/SQL anzeigen)</strong> - Die Anwendung kann nicht ausgef\00FChrt oder bearbeitet werden.</li>'),
unistr('<li><strong>Nicht verf\00FCgbar (Zu URL umleiten)</strong> - Die Anwendung kann nicht ausgef\00FChrt werden. Der Benutzer wird zu der URL weitergeleitet, die in der Nichtverf\00FCgbarkeitsmeldung angegeben wurde.</li>'),
'</ul>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
