wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1378952136513217.4003)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Name der benutzerdefinierten Funktion'
,p_source=>'ORACLE_TEXT_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Geben Sie den Namen einer benutzerdefinierten PL/SQL-Funktion an, die eine Endbenutzereingabe in eine Oracle Text-Abfrage konvertiert. ',
unistr('    Die Funktion akzeptiert die Endbenutzereingabe als VARCHAR2 und gibt die Oracle Text-Abfrage als Ergebnis zur\00FCck.</p>'),
'<p>',
unistr('    Bei diesem Beispiel wird die <em>Abfrage-Relaxation von Oracle Text </em> verwendet: Erst wird die genaue Abfrage ausgef\00FChrt,'),
unistr('    dann werden aufsteigende Ebenen der <em>Fuzzysuche</em> durchgef\00FChrt, bis die angeforderte Anzahl von Zeilen'),
unistr('    zur\00FCckgegeben wird. All diese Vorg\00E4nge sind f\00FCr den Endbenutzer transparent.'),
'</p>',
'<pre>',
'create or replace function convert_end_user_search (',
'    p_search in varchar2 )',
'    return varchar2 ',
'is',
'    c_xml constant varchar2(32767) := ',
'        ''&lt;query&gt;&lt;textquery>&lt;progression&gt;''          ||',
'          ''&lt;seq&gt;       #SEARCH#            &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,80, 100,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,50,1000,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,20,3000,W) &lt;/seq&gt;'' ||',
'        ''&lt;/progression>&lt;/textquery>&lt;/query&gt;'';',
'',
'    l_search varchar2(32767) := p_search;',
'begin',
'    --',
'    -- remove special characters; ',
'    -- these are irrelevant for full text search',
'    --',
'    l_search := regexp_replace(',
'        srcstr  => l_search, ',
'        pattern => ''[&lt;&gt;{}/()*%&!$?.:,;\+#]'' );',
'',
'    return replace( ',
'        srcstr  => c_xml, ',
'        oldsub  => ''#SEARCH#'', ',
'        newsub  => ''{'' || l_search || ''}'' );',
'end;',
'</pre>',
'<p>',
'    Weitere Informationen zur Abfragesyntax von Oracle Text und zum Abfrage-Relaxation-Feature',
unistr('    finden Sie im <a rel="noopener noreferrer" target="_blank" href="https://docs.oracle.com/en/database/oracle/oracle-database/23/ccapp/index.html">Handbuch f\00FCr Oracle Text-Anwendungsentwickler</a>.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
