wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1931095356915001.4003)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION_TYPE'
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Textabfragefunktion'
,p_source=>'ORACLE_TEXT_FUNCTION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'TEXT_QUERY_FUNCTION_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(1936977999928971)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Kein Wert'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Oracle Text-Abfragesyntax ist sehr komplex und leistungsf\00E4hig. Sie stellt ein umfassendes Set von Operatoren f\00FCr die Arbeit mit Platzhalterzeichen, Wortstammsuchen, Fuzzysuchen usw. bereit. F\00FCr Endbenutzer ist diese Syntax h\00E4ufig schwer zu ver')
||unistr('stehen. Um den Suchprozess f\00FCr Benutzer zu vereinfachen, k\00F6nnen Sie eine Funktion ausw\00E4hlen, die eine einfache Endbenutzereingabe automatisch in eine Oracle Text-Abfrage konvertiert. Dabei werden die erweiterten Suchfeatures automatisch angewendet. O')
||'ptionen:</p>',
'<ul>',
unistr('    <li><strong>Kein Wert</strong>: &PRODUCT_NAME. schlie\00DFt jeden Abfragebegriff in "{" und "}" ein, mit Ausnahme der Schl\00FCsselw\00F6rter <strong>and</strong> und <strong>or</strong>.</li>'),
unistr('    <li><strong>Suchmaschine</strong>: Diese Funktion f\00FChrt eine Abfrage-Relaxation-Suche aus, um neben genauen \00DCbereinstimmungen noch weitere relevante Ergebnisse zu finden. Ziel ist es, m\00F6glichst viele verwandte Ergebnisse zu erhalten, damit Benutz')
||unistr('er leicht die gesuchten Informationen finden, ohne pr\00E4zise Abfragen eingeben zu m\00FCssen. Der Suchprozess beginnt mit der Suche nach einer genauen \00DCbereinstimmung. Danach wird die Abfrage mit Techniken wie Wortstammsuche und Fuzzysuche zunehmend erweit')
||unistr('ert. Die Suchmaschinenfunktion maximiert die Anzahl der Ergebnisse und stellt dabei sicher, dass die genauesten und relevantesten \00DCbereinstimmungen immer am Anfang der Suchergebnisse stehen.</li>'),
unistr('    <li><strong>Expertensuche</strong>: Diese Funktion unterst\00FCtzt erweiterte Suchoperatoren f\00FCr pr\00E4zise Abfragen. Sie erm\00F6glicht das Suchen nach genauen \00DCbereinstimmungen, mit booleschen Operatoren (AND, OR, NOT), nach Priorit\00E4t mit Klammern und die')
||unistr(' N\00E4herungssuche. Zus\00E4tzliche Parameter erm\00F6glichen die Anpassung des Suchverhaltens. Das ist zu empfehlen, wenn Sie hochpr\00E4zise Ergebnisse aus sehr spezifischen Abfragen ben\00F6tigen. Siehe auch die Funktion <code>QUERY_EXPERT_SEARCH</code> im Package <')
||'code>APEX_SEARCH</code>.</li>',
'    <li><strong>Benutzerdefiniert</strong>: Eingabe einer benutzerdefinierten Funktion.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1950100044091138.4003)
,p_name=>'P4001_TOKENIZE_ROW_SEARCH'
,p_is_required=>true
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tokenisierte Zeilensuche'
,p_source=>'TOKENIZE_ROW_SEARCH'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie an, wie die Suchbegriffe angewendet werden, wenn eine <em>Zeilensuche</em> in einer Komponente ausgef\00FChrt wird.</p>'),
unistr('<p>Wenn Sie <strong>Ein</strong> ausw\00E4hlen, wird jedes Wort eines Suchbegriffs separat behandelt. Dadurch werden Datens\00E4tze zur\00FCckgegeben, bei denen die W\00F6rter in einer der Spalten vorkommen (einzeln oder zusammenh\00E4ngend). Um nach einer genauen Wortg')
||unistr('ruppe zu suchen, setzen Sie die Suchbegriffe in doppelte Anf\00FChrungszeichen ("). Beispiel: "ui developer". Um ein doppeltes Anf\00FChrungszeichen in einem Suchbegriff zu maskieren, verwenden Sie ein doppeltes Anf\00FChrungszeichen ("").'),
'</p> ',
'<h4>Beispiele</h4>',
'<dl>',
unistr('<dt>1. Alle Datens\00E4tze mit den W\00F6rtern "red" und "shoes"<dt><dd>Suchbegriff: red shoes</dd>'),
unistr('<dt>2. Alle Datens\00E4tze mit dem Wort "developer" und dem genauen Ausdruck "ui designer"</dt><dd>Suchbegriff: developer "ui designer"</dd>'),
unistr('<dt>3. Alle Datens\00E4tze mit dem Wort "author" und dem genauen Ausdruck "the sky is "blue" and nice"</dt><dd>Suchbegriff: author "the sky is ""blue"" and nice"</dd>'),
'</dl>',
unistr('<p>Bei <strong>Aus</strong> wird der gesamte Suchbegriff als genaue \00DCbereinstimmung behandelt.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2001338047304309.4003)
,p_name=>'P4001_TASK_VACATION_RULE_PROC'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(2200978967294804.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Urlaubsregelprozedur der Aufgabe'
,p_source=>'TASK_VACATION_RULE_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>100
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den Namen einer PL/SQL-Prozedur im Format <strong>[schemaName.[packageName.]]procedureName</strong> an. ',
unistr('Die Prozedur soll zus\00E4tzliche alternative Teilnehmer f\00FCr Aufgabendefinitionen in dieser Anwendung zur\00FCckgeben.'),
'Die Urlaubsregelprozedur muss die folgende Schnittstelle implementieren.</p>',
'<pre>',
'    procedure my_vacation_rule (',
'        p_param   in apex_approval.t_vacation_rule_input,',
'        p_result  out apex_approval.t_vacation_rule_output );',
'</pre>',
'<p>Die Prozedureingabe hat den Typ <strong>apex_approval.t_vacation_rule_input</strong> und die Ergebnisausgabe den Typ <strong>apex_approval.t_vacation_rule_output</strong> </p>',
'<p>',
unistr('Dieses Beispiel zeigt die Implementierung einer Urlaubsregelprozedur, bei der SCOTT als alternativer Teilnehmer hinzugef\00FCgt wird, weil JANE '),
'in den Mutterschutz geht.</p>',
'<pre>',
'',
'    procedure alternate_job_approvers(',
'                p_param    in apex_approval.t_vacation_rule_input,',
'                p_result  out apex_approval.t_vacation_rule_result)',
'    is ',
'        l_result            apex_approval.t_vacation_rule_result;',
'        l_changes           apex_approval.t_task_participant_changes;',
'        l_participants      apex_approval.t_task_participants;',
'        l_new_participant   apex_approval.t_task_participant;',
'        l_old_participant   apex_approval.t_task_participant;',
'        l_has_changed       boolean                             := false;',
'        l_index             pls_integer                         := 1;',
'    begin',
'        l_participants := p_param.original_participants;',
'        for i in 1..l_participants.count loop',
'            if l_participants(i).value = ''JANE'' then',
'                l_old_participant               :=  l_participants(i);',
'                l_new_participant.value         := ''SCOTT'';',
'                l_new_participant.type          := ''POTENTIAL_OWNER'';',
'                l_new_participant.identity      := ''USER'';',
'                l_has_changed                   := true;',
'            end if;',
'        end loop;',
'        if l_has_changed then',
'            l_participants(l_participants.count + 1) := l_new_participant;',
'        ',
'            l_changes(l_index).old_participant   := l_old_participant;',
'            l_changes(l_index).new_participant   := l_new_participant;',
'            l_changes(l_index).change_reason     := ''Jane is out on maternity leave'';',
'        end if;',
'        l_result.participant_changes            := l_changes;',
'        l_result.has_participant_changes        := l_has_changed;',
'        p_result                                := l_result;',
'    end;',
'</pre>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
