wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(919320760230919.4003)
,p_name=>'P4052_PARENT_LIST_ITEM_ID'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(430041099.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('\00DCbergeordneter Listeneintrag')
,p_source=>'PARENT_LIST_ITEM_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'LIST ITEMS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html(list_item_link_text) d, id',
'  from (',
'           select lpad('' '', 4 * (level - 1), ''.'') || list_item_link_text list_item_link_text, id',
'             from (',
'                      select id, parent_list_item_id, list_item_display_sequence, list_item_link_text',
'                        from wwv_flow_list_items i',
'                       where flow_id = :fb_flow_id',
'                         and security_group_id = :WORKSPACE_ID',
'                         and list_id = :f4000_p4052_list_id',
'                         and id not in (',
'                                 select id',
'                                   from wwv_flow_list_items',
'                                  where flow_id           = :fb_flow_id',
'                                    and security_group_id = :workspace_id',
'                                    and list_id           = :f4000_p4052_list_id',
'                                  start with id = :f4000_p4052_id',
'                                connect by prior id = parent_list_item_id',
'                             )',
'                         and sub_list_id is null',
'                  )',
'            start with parent_list_item_id is null',
'          connect by prior id = parent_list_item_id',
'            order siblings by list_item_display_sequence',
'       );'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Kein \00FCbergeordnetes Listenelement -')
,p_lov_null_value=>'%null%'
,p_cHeight=>1
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id ',
'  from wwv_flow_list_items ',
' where flow_id = :FB_FLOW_ID',
'   and list_id = :F4000_P4052_LIST_ID',
'   and security_group_id = :WORKSPACE_ID   '))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Geben Sie das \00FCbergeordnete Element f\00FCr diesen Listeneintrag an. Mit diesem Attribut k\00F6nnen Sie eine hierarchische Liste erstellen.'),
unistr('<p>Um eine hierarchische Liste zu erstellen, w\00E4hlen Sie ein Listentemplate, das hierarchische Listen unterst\00FCtzt. Um derartige Listentemplates zu ermitteln, suchen Sie nach Templates mit der Namenskonvention "with Sublist". Weitere Informationen zur ')
