,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Autorisierung f\00FCr Anwendungen, Seiten und die meisten anderen Komponenten wird \00FCber Autorisierungsschemas verwaltet.</p>'),
unistr('<p>Sie verkn\00FCpfen ein Autorisierungsschema mit einer Anwendung, einer Seite oder einer anderen Komponente auf der Attributseite der jeweiligen Komponente.</p>'),
unistr('<p>Ein Autorisierungsschema \00FCberpr\00FCft, ob vorgegebene Autorisierungskriterien erf\00FCllt werden oder nicht. Zu den g\00E4ngigen Autorisierungsschematypen geh\00F6ren SQL-Abfragen auf der Basis "Exists" und "Not Exists" sowie die PL/SQL-Funktion zur R\00FCckgabe von')
||' booleschen Werten.</p>',
'<p>Das Ergebnis von Autorisierungsschemas wird pro Session oder pro Seitenansicht gecacht, um die Performance zu verbessern.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
