wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(125268524262083710.4003)
,p_plug_name=>'Beispiel: Dynamische Wertelisten bei SQL-Abfragen'
,p_parent_plug_id=>wwv_flow_imp.id(202306103707329518.4003)
,p_region_template_options=>'#DEFAULT#:is-collapsed:a-Region--noBorder'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(689970285456172024.4003)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Beispiel 1 (mit Bind-Variable): ',
'<pre>',
'SELECT ename d, empno r',
'FROM  emp ',
'WHERE deptno = :my_item ',
'ORDER BY 1',
'</pre>',
unistr('Beispiel 2 (Abfrage enth\00E4lt Inline-Abfrage. Es muss sichergestellt werden, dass die erste FROM-Klausel in der SQL-Anweisung kein Bestandteil der Inline-Abfrage ist):'),
'<pre>',
'SELECT c1, c2 ',
'  FROM ',
'(SELECT decode(',
'         (SELECT count(*) ',
'            FROM emp2 b ',
'           WHERE a.ename = b.ename), ',
'          1, ''+'' || ename, ename) c1, ',
'         ename c2 ',
'   FROM emp a)</pre>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(233330927108902814.4003)
,p_name=>'Verwendung'
,p_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_display_sequence=>140
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--sideRegion'
,p_new_grid_row=>false
,p_display_column=>1
,p_display_point=>'REGION_POSITION_03'
,p_item_display_point=>'BELOW'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select i.flow_step_id as page_id,',
'       to_char(i.flow_step_id)||''. ''||substr(i.name,1,15) as page',
'  from wwv_flow_step_items i',
' where i.flow_id           = :FB_FLOW_ID',
'   and i.security_group_id = :WORKSPACE_ID',
'   and exists ( select 1 ',
'                  from wwv_flow_lists_of_values$ l',
'                 where l.security_group_id = :WORKSPACE_ID',
'                   and l.id                = :F4000_P4111_ID',
'                   and l.lov_name          = i.named_lov )',
'    --',
' union',
'select r.page_id,',
'       to_char(r.page_id)||''. ''||substr(r.plug_name,1,15) as page',
'  from wwv_flow_page_plugs           r,',
'       wwv_flow_region_report_column c,',
'       wwv_flow_lists_of_values$     l',
' where r.security_group_id  = c.security_group_id',
'   and c.security_group_id  = l.security_group_id',
'   and l.security_group_id  = :WORKSPACE_ID',
'    -- ',
'   and r.id                 = c.region_id',
'   and l.id                 = c.named_lov',
'    --',
'   and r.flow_id            = to_number( :FB_FLOW_ID )',
'   and l.id                 = to_number( :F4000_P4111_ID )',
'    --',
' union',
'select r.page_id,',
'       to_char(r.page_id)||''. ''||substr(r.plug_name,1,15) as page',
'  from wwv_flow_worksheet_columns c,',
'       wwv_flow_worksheets        w,',
'       wwv_flow_page_plugs        r',
' where r.security_group_id  = c.security_group_id',
'   and c.security_group_id  = w.security_group_id',
'   and w.security_group_id  = :WORKSPACE_ID',
'    --',
'   and w.id                = c.worksheet_id',
'   and r.id                = w.region_id',
'    --',
'   and c.flow_id           = to_number(:FB_FLOW_ID)',
'   and c.rpt_named_lov     = to_number(:F4000_P4111_ID)',
'    --',
' union',
'select r.page_id,',
'       to_char(r.page_id)||''. ''||substr(r.plug_name,1,15) as page',
'  from wwv_flow_page_plugs        r,',
'       wwv_flow_region_columns    c,',
'       wwv_flow_lists_of_values$  l',
' where r.security_group_id  = c.security_group_id',
'   and c.security_group_id  = l.security_group_id',
'   and l.security_group_id  = :WORKSPACE_ID',
'    --',
'   and r.id                 = c.region_id',
'   and (    c.lov_id        = l.id ',
'         or c.filter_lov_id = l.id )',
'    --',
'   and r.flow_id            = to_number( :FB_FLOW_ID )',
'   and r.security_group_id  = to_number( :WORKSPACE_ID )',
'   and l.id                 = to_number( :F4000_P4111_ID )',
' order by page_id, page',
''))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(11667910335347890.4003)
,p_query_num_rows=>5000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>' - '
,p_query_no_data_found=>'Diese Werteliste wird nicht verwendet.'
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
);
