,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Oracle Optimizer-Hinweis ein, der beim Ausf\00FChren der SQL-Abfrage der obersten Anweisung hinzugef\00FCgt wird. Ein Hinweis ist eine Anweisung f\00FCr den Optimizer. Beim Schreiben von SQL haben Sie m\00F6glicherweise Informationen zu den Daten, d')
||unistr('ie dem Optimizer unbekannt sind. Mit Hinweisen k\00F6nnen Sie Entscheidungen treffen, die normalerweise vom Optimizer getroffen werden. So k\00F6nnte der Optimizer in manchen F\00E4llen einen Plan ausw\00E4hlen, den er eigentlich als kostenintensiver betrachtet.</p>'),
'',
unistr('<p>Beispiel: Sie wissen, dass ein bestimmter Index f\00FCr gewisse Abfragen selektiver ist. Aufgrund dieser Informationen k\00F6nnen Sie einen effizienteren Ausf\00FChrungsplan ausw\00E4hlen als der Optimizer. Verwenden Sie in einem solchen Fall Hinweise, um den Opt')
||unistr('imizer zur Verwendung des optimalen Ausf\00FChrungsplans zu zwingen.</p>'),
'',
'<p>Beispiel:</p>',
'<p>Verwenden Sie beim Zugriff auf die Tabelle <code>employees</code> den Index <code>emp_department_ix</code>:</p>',
'<pre>INDEX (employees emp_department_ix)</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
