'        p_application_id   => :FB_FLOW_ID ) is null then ',
'        ''COMM_FAILURE''',
'    when not wwv_flow_exec_remote.test_authentication(',
'        p_remote_server_id => :P4111_REMOTE_SERVER_ID,',
'        p_application_id   => :FB_FLOW_ID ) then',
'        ''AUTH_FAILURE''',
'    when wwv_flow_exec_remote.test_authentication(',
'        p_remote_server_id => :P4111_REMOTE_SERVER_ID,',
'        p_application_id   => :FB_FLOW_ID ) then',
'        ''AUTH_PASSED''',
'    end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
