'             then :P4111_LOV_QUERY_FUNC_BODY',
'        end',
'',
'    when ''REMOTE'' then',
'        :P4111_REMOTE_SQL',
'    when ''WEB_SOURCE'' then',
'        case :P4111_SOURCE_POST_PROC_TYPE',
