'            when ''SQL''                     then :P4111_DVPOST_SQL',
'        end',
'    when ''JSON_COLLECTION'' then',
'        case :P4111_JSPOST_TYPE',
'            when ''FUNC_BODY_RETURNING_SQL'' then :P4111_JSPOST_FUNC_BODY',
'            when ''SQL''                     then :P4111_JSPOST_SQL',
'        end',
'end',
''))
);
