'let lDelCount = 0,',
'    lAllCount = 0;',
'    ',
'const model = apex.region("COL_IG").widget().interactiveGrid("getCurrentView").model;',
'',
'model.forEach( function( record, index, id ) {',
'    lAllCount = lAllCount + 1;',
'    let meta = model.getRecordMetadata(id);',
'    if ( meta.deleted ){',
'      lDelCount = lDelCount + 1;',
'    }',
'});',
'',
'// set IG row count and deleted rows count to hidden items',
'// we need them for validations',
'apex.item("P4111_ADDITIONAL_COL_COUNT").setValue(lAllCount);',
'apex.item("P4111_DEL_COL_COUNT").setValue(lDelCount);'))
