'p_rowid       => v(''F4000_P4111_ID''),',
'p_alt_rowid   => ''ID'');',
'exit;',
'end loop;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Fehler beim Verarbeiten von Zeile.'
,p_process_when=>':REQUEST IN (''Create'',''ApplyChanges'',''REFRESH_COLUMN_INFO'',''CREATE_STATIC'')'
