wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(17314311266994460.4003)
,p_name=>'P4303_PROTECTION_LEVEL'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(17312310527965891.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(454431825.4003)
,p_item_default=>'I'
,p_prompt=>unistr('Schutz f\00FCr den Sessionzustand')
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ITEM PROTECTION LEVEL D'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select nvl(PAGE_PROTECTION_ENABLED_Y_N,''N'') p from wwv_flows where id = :FB_FLOW_ID) loop',
'    if c1.p = ''Y'' then',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_APPLICATION'''') d, ''''B'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_USER'''') d, ''''P'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_SESSION'''') d, ''''S'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    else',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    end if;',
'end loop;'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('W\00E4hlen Sie den Schutz f\00FCr den Sessionzustand f\00FCr dieses Element:'),
'<ul>',
unistr('<li><strong>Uneingeschr\00E4nkt</strong> - Das Element kann festgelegt werden, indem der Name oder Wert des Elements in einer URL oder Form \00FCbergeben wird. In der URL ist keine Pr\00FCfsumme erforderlich.</li><br />       '),
unistr('<li><strong>Eingeschr\00E4nkt: Darf nicht vom Browser festgelegt werden</strong> - Das Element darf nicht \00FCber die URL oder POSTDATA ge\00E4ndert werden. Verwenden Sie diese Option, wenn Sie festlegen m\00F6chten, dass der Elementwert nur eingeschr\00E4nkt auf inter')
||unistr('ne Prozesse, Berechnungen usw. gesetzt werden kann. Dieses Attribut ist nur auf Elemente anwendbar, die nicht als Dateneintragselemente verwendet werden k\00F6nnen. Das Attribut wird auch dann beachtet, wenn der Schutz f\00FCr den Sessionzustand deaktiviert ')
||unistr('ist. Dieses Attribut kann f\00FCr Anwendungselemente oder Seitenelemente verwendet werden, die einen der folgenden Anzeigetypen haben:'),
'<br />',
'<ul>',
'<li>Nur anzeigen (Speicherstatus=Nein)</li>   ',
'<li>Textfeld (deaktiviert, hat keinen Speicherstatus)</li>                          ',
'<li>Grid-Layout stoppen und starten (zeigt nur das Label an)</li>',
'</li></ul>',
unistr('<li><strong>Pr\00FCfsumme erforderlich: Anwendungsebene</strong> - Das Element kann festgelegt werden, indem Sie den Namen oder Wert des Elements in einer URL \00FCbergeben, wenn auch eine Pr\00FCfsumme angegeben wird, die sich auf den Workspace und die Anwendun')
||unistr('g bezieht. Mit dieser Option k\00F6nnen Sie bestimmen, dass dieses Element nur von URLs festgelegt werden kann, deren Pr\00FCfsummen von einem Benutzer generiert wurden, der dieselbe Anwendung im aktuellen Workspace, jedoch in einer anderen Session ausf\00FChrt.')
||'</li>',
unistr('<li><strong>Pr\00FCfsumme erforderlich: Benutzerebene</strong> - Das Element kann festgelegt werden, indem Sie den Namen oder Wert des Elements in einer URL \00FCbergeben, wenn auch eine Pr\00FCfsumme angegeben wird, die sich auf den Workspace, die Anwendung und')
||unistr(' den Benutzer bezieht. Mit dieser Option k\00F6nnen Sie bestimmen, dass dieses Element nur von URLs festgelegt werden kann, deren Pr\00FCfsummen von demselben benannten Benutzer generiert wurden, der dieselbe Anwendung im aktuellen Workspace, jedoch in einer')
||unistr(' anderen Session ausf\00FChrt.</li>      '),
unistr('<li><strong>Pr\00FCfsumme erforderlich: Sessionebene</strong> - Das Element kann festgelegt werden, indem Sie den Namen oder Wert des Elements in einer URL \00FCbergeben, wenn auch eine Pr\00FCfsumme angegeben wird, die sich auf die aktuelle Session bezieht. Mit')
||unistr(' dieser Option k\00F6nnen Sie bestimmen, dass dieses Element nur von URLs festgelegt werden kann, deren Pr\00FCfsummen in der aktuellen Session generiert wurden.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
