wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(34391125123007081.4003)
,p_name=>'P4307_CSS_FILE_URLS'
,p_item_sequence=>930
,p_item_plug_id=>wwv_flow_imp.id(34390928027007081.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Datei-URLs'
,p_source=>'CSS_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie URLs der CSS-Datei an, die auf dieser Seite geladen werden sollen. Jede URL muss in eine neue Zeile geschrieben werden. Wenn Sie eine minimierte Version der Datei angeben, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#MIN#</code> oder <co')
||unistr('de>#MIN_DIRECTORY#</code>verwenden, um <code>.min</code> bzw. <code>minified/</code> in der Datei-URL f\00FCr eine regul\00E4re Seitenansicht aufzunehmen, sowie eine leere Zeichenfolge, wenn die Seite im Debugmodus angezeigt wird. Sie haben au\00DFerdem Zugriff ')
||unistr('auf die Ersetzungszeichenfolge <code>#APP_VERSION#</code>, wenn Sie die Version der Anwendung in die Datei-URL aufnehmen m\00F6chten.</p>'),
'',
'<p>Die Ersetzungszeichenfolge <code>#TEMPLATE_CSS#</code> wird durch die hier eingegebenen Datei-URLs im Template ersetzt.</p>',
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>link</code>-Tags aufnehmen. Nehmen Sie einfach die Datei-URL auf.</p>'),
'',
'<p>',
'Beispiele:',
'<ul>',
'  <li>Standarddateireferenz',
'      <pre>/mycss/main.css</pre>',
'  </li>',
unistr('  <li>Standarddateireferenz, die die minimierte Datei main.min.css aus /mycss/minified/ f\00FCr regul\00E4re Seitenansichten und main.css aus /mycss/ im Debugmodus l\00E4dt.'),
'      <pre>/mycss/#MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
'  <li>Bedingte Medienabfrage',
'      <pre>[media="only screen and (max-device-width: 480px)"]/mycss/smartphone.css</pre>',
'  </li>',
unistr('  <li>Dateireferenz mit einer Abfragezeichenfolge in der URL, die die Anwendungsversion referenziert, sodass der Browser beim Upgrade der Anwendung (und Erh\00F6hen der Version) angewiesen wird, immer die neue Datei zu laden und alle zuvor gecachten Date')
||'ien zu ignorieren.',
'      <pre>/mycss/main.css?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'NONE')).to_clob
);
