,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Cascading Style Sheet-Code ein, der f\00FCr dieses Seitentemplate verwendet werden soll. Sie k\00F6nnen den Code in einer externen Datei ablegen, um Duplizierungen zu vermeiden und das Browser-Caching von statischen Dateien zu nutzen.</p>'),
'',
'<p>Der hier eingegebene Code ersetzt die Ersetzungszeichenfolge <code>#TEMPLATE_CSS#</code> im Template.</p>',
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>style</code>-Tags einf\00FCgen. F\00FCgen Sie einfach den Cascading Style Sheet-Code ein.</p>'),
'',
'<p>',
'Beispiel: So setzen Sie die CSS-Klasse <code>display_only</code> auf "Fett"',
'<pre>',
'.display_only {',
'  font-weight:bold;',
'}',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'CSS',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
