 p_id=>wwv_flow_imp.id(34407825067341355.4003)
,p_name=>'P4307_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(34407606078341355.4003)
