'select ''- '' || lower(wwv_flow_lang.system_message(''NO_TEMPLATE'')) || '' -'' d, 0 r ',
'  from sys.dual ',
' union all',
'select flow_id ||'' : ''|| name || nvl2( theme_id, '' ('' || theme_id || '')'', '''' ) d, id r',
