wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(203351726181564628.4003)
,p_name=>'P4307_GRID_TEMPLATE'
,p_item_sequence=>400
,p_item_plug_id=>wwv_flow_imp.id(131914703603.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Container-Template'
,p_source=>'GRID_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Gibt das Markup zum Starten eines neuen Layouts an. Sie m\00FCssen mindestens #ROWS# in dieses Template aufnehmen. Die folgenden Ersetzungszeichenfolgen sind im Containertemplate zul\00E4ssig:</p>'),
'<ul>',
'<li><strong>#USED_COLUMNS_NUMBER#</strong> - Anzahl der verwendeten Grid-Spalten. Beispiel: 1, 2, 3, ...</li>',
'<li><strong>#USED_COLUMNS_ALPHA#</strong> - Buchstabe, der die Anzahl der verwendeten Spalten darstellt. Beispiel: a, b, c, ...</li>',
unistr('<li><strong>#USED_COLUMNS_ALPHA_MINUS#</strong> - Buchstabe, der die Anzahl der verwendeten Spalten darstellt, die um eine Spalte reduziert werden. Beispiel: Zwei Grid-Spalten geben "a" zur\00FCck.</li>'),
'<li><strong>#USED_COLUMNS_WORD#</strong> - Wort, das die Anzahl der verwendeten Spalten darstellt. Beispiel: eins, zwei, drei, ...</li>',
unistr('<li><strong>#USED_COLUMNS_PLURAL#</strong> - Wird durch "s" ersetzt, wenn die Anzahl der Spalten gr\00F6\00DFer als eins ist. Verwenden Sie dies, wenn das Grid den Klassennamen "column" f\00FCr eine einzelne Spalte und "columns" bei Angabe von mehreren Spalten e')
||'rfordert. Beispiel: class="#USED_COLUMNS_WORD# column#USED_COLUMNS_PLURAL#"</li>',
'<li><strong>#ROWS#</strong> - Wird durch das "Zeilentemplate" ersetzt.</li>',
'</ul>',
'<p>',
'Beispiel:',
'<pre>',
'&lt;div class="ui-grid-#USED_COLUMNS_ALPHA_MINUS#"&gt;#ROWS#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
