wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(203353124660580498.4003)
,p_name=>'P4307_GRID_COLUMN_TEMPLATE'
,p_item_sequence=>420
,p_item_plug_id=>wwv_flow_imp.id(131914703603.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Spaltentemplate'
,p_source=>'GRID_COLUMN_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Gibt das Markup zum Starten einer neuen Layoutspalte an. Sie m\00FCssen mindestens #CONTENT# in dieses Template aufnehmen. Die folgenden Ersetzungszeichenfolgen sind im Spaltentemplate zul\00E4ssig:</p>'),
'<ul>',
'<li><strong>#COLUMN_NUMBER#</strong> - Nummer der Spalte. Beispiel: 1, 2, 3, ...</li>',
unistr('<li><strong>#COLUMN_ALPHA#</strong> - Buchstabe, der f\00FCr die Spalte steht. Beispiel: a, b, c, ...</li>'),
unistr('<li><strong>#COLUMN_WORD#</strong> - Wort, das f\00FCr die Spalte steht. Beispiel: eins, zwei, drei, ...</li>'),
unistr('<li><strong>#COLUMN_PLURAL#</strong> - Wird durch "s" ersetzt, wenn die Spalte gr\00F6\00DFer als eins ist. Verwenden Sie dies, wenn das Layout den Klassennamen "column" f\00FCr die erste Spalte und "columns" f\00FCr die folgenden Spalten erfordert. Beispiel: class=')
||'"#COLUMN_WORD# column#COLUMN_PLURAL#"</li>',
'<li><strong>#COLUMN_SPAN_NUMBER#</strong> - Nummer des Spaltenbereichs. Beispiel: 1, 2, 3, ...</li>',
'<li><strong>#COLUMN_SPAN_ALPHA#</strong> - Buchstabe, der den Spaltenbereich darstellt. Beispiel: a, b, c, ...</li>',
'<li><strong>#COLUMN_SPAN_WORD#</strong> - Wort, das den Spaltenbereich darstellt. Beispiel: eins, zwei, drei, ...</li>',
unistr('<li><strong>#COLUMN_SPAN_PLURAL#</strong> - Wird durch "s" ersetzt, wenn der Spaltenbereich gr\00F6\00DFer als eins ist. Verwenden Sie dies, wenn das Layout den Klassennamen "column" f\00FCr eine einzelne Spalte und "columns" bei Angabe von mehreren Spalten erfo')
||'rdert. Beispiel: class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL#"</li>',
'<li><strong>#CSS_CLASSES#</strong> - Wird durch den Wert ersetzt, der als "Spalten-CSS-Klassen" angegeben wird. Dadurch kann eine Spalte mit CSS-Klassen weiter angepasst werden.</li>',
unistr('<li><strong>#ATTRIBUTES#</strong> - Wird durch den f\00FCr "Spaltenattribute" angegebenen Wert ersetzt. Dadurch kann eine Spalte weiter angepasst werden.</li>'),
'<li><strong>#FIRST_LAST_COLUMN_ATTRIBUTES#</strong> - Wird durch den in "Attribute der ersten Spalte" und "Attribute der letzten Spalte" angegebenen Wert ersetzt, je nachdem, ob es sich um die erste oder letzte Spalte handelt.</li>',
unistr('<li><strong>#CONTENT#</strong> - Wird durch die Regionen, Seitenelemente oder Schaltfl\00E4chen ersetzt, die in der Spalte angezeigt werden.</li>'),
'</ul>',
'<p>',
'Beispiel:',
'<pre>',
'&lt;div class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL# #CSS_CLASSES#"&gt;#CONTENT#&lt;/div&gt;',
'</pre>',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
