wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(864568260573731002.4003)
,p_name=>'P4307_DIALOG_BROWSER_FRAME'
,p_item_sequence=>1350
,p_item_plug_id=>wwv_flow_imp.id(53603513531407414.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Einbettung in Frame zulassen'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'   l_value wwv_flow_global.vc_arr2;',
'begin ',
'   select dialog_browser_frame ',
'   bulk collect into l_value ',
'   from wwv_flow_templates ',
'   where id = :F4000_P4307_ID',
'   and security_group_id in ( :WORKSPACE_ID, 11, 12 );',
'',
'   return wwv_flow_utilities.table_to_string2(l_value,'':''); ',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'DIALOG_PAGE_MODE_OPTIONS'
,p_lov=>'.'||wwv_flow_imp.id(887851591470130537)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Die Browserframeoptionen auf Seitentemplateebene werden unten zusammen mit der aktuellen Einstellung f\00FCr jede Option aufgef\00FChrt.'),
unistr('Aktivieren Sie das K\00E4stchen neben einem Seitenmodus, um mit diesem Attribut zu bestimmen, ob der Browser die Seiten Ihrer Anwendung in einem Frame anzeigen kann.'),
unistr('Die aktuelle Einstellung wird zur Standardeinstellung f\00FCr jedes modale und nicht-modale Dialogfeld, das dieses Seitentemplate verwendet.'),
'<p/>',
'<p>',
unistr('Die Anzeige von Seiten innerhalb von Frames kann f\00FCr "Clickjacking"-Angriffe missbraucht werden.'),
unistr('Bei einem Clickjacking-Angriff verwendet der Angreifer mehrere Layer, um einen Benutzer zu verleiten, auf eine Schaltfl\00E4che oder einen Link auf einer anderen Seite zu klicken, w\00E4hrend er vermeintlich auf die Seite der obersten Ebene klickt.'),
unistr('Somit missbraucht der Angreifer Klicks (oder Tastenanschl\00E4ge), die f\00FCr die Benutzerseite gedacht waren, und leitet sie zu einer anderen Seite um.'),
'<p/>',
'<p>',
'&PRODUCT_NAME. bettet modale Dialogfelder in iframes ein.',
'Wenn Sie das Anwendungssicherheitsattribut <em>Browserframe</em> auf "Ablehnen" setzen,',
unistr('verwendet die Auswahl <em>Einbettung in Frame zulassen</em> f\00FCr "Modales Dialogfeld" stattdessen "Aus selbem Ursprung zulassen" f\00FCr Dialogseiten, die dieses Template verwenden. '),
'</p>'))
