,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<P>W\00E4hlen Sie eine der vordefinierten Bedingungen, wenn diese Registerkarte nur in bestimmten Situationen angezeigt werden soll:<P>'),
'',
'<UL>',
'',
unistr('<LI>CURRENT_PAGE_NOT_EQUALS_CONDITION: Die Registerkarte wird nur angezeigt, wenn die aktuelle Seite nicht die Seite ist, die im Feld f\00FCr die Anzeigebedingung angegeben ist.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_EQUALS_CONDITION: Die Registerkarte wird nur angezeigt, wenn die aktuelle Seite die Seite ist, die im Feld f\00FCr die Anzeigebedingung angegeben ist.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_NOT_IN_CONDITION: Die Registerkarte wird nur angezeigt, wenn die aktuelle Seite nicht in der durch Kommas getrennten Liste der Seiten enthalten ist, die im Feld f\00FCr die Anzeigebedingung angegeben ist.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_IN_CONDITION: Die Registerkarte wird nur angezeigt, wenn die aktuelle Seite in der durch Kommas getrennten Liste der Seiten enthalten ist, die im Feld f\00FCr die Anzeigebedingung angegeben ist.</LI>'),
'',
unistr('<LI>USER_IS_NOT_PUBLIC_USER: Die Registerkarte wird nur angezeigt, wenn der aktuelle Benutzer kein \00F6ffentlicher Benutzer ist. Es ist kein Eintrag im Feld f\00FCr die Anzeigebedingung erforderlich.</LI>'),
'',
unistr('<LI>USER_IS_PUBLIC_USER: Die Registerkarte wird nur angezeigt, wenn der aktuelle Benutzer ein \00F6ffentlicher Benutzer ist. Es ist kein Eintrag im Feld f\00FCr die Anzeigebedingung erforderlich.</LI>'),
'',
unistr('<LI>EXISTS: Die Registerkarte wird nur angezeigt, wenn die Abfrage im Feld f\00FCr die Anzeigebedingung mindestens eine Zeile zur\00FCckgibt.</LI>'),
'',
unistr('<LI>ITEM_IS_NOT_NULL: Die Registerkarte wird nur angezeigt, wenn f\00FCr das Element im Feld f\00FCr die Anzeigebedingung NOT NULL gilt.</LI>'),
'',
unistr('<LI>ITEM_IS_NULL: Die Registerkarte wird nur angezeigt, wenn f\00FCr das Element im Feld f\00FCr die Anzeigebedingung NULL gilt.</LI>'),
'',
unistr('<LI>NOT_EXISTS: Die Registerkarte wird nur angezeigt, wenn die Abfrage im Feld f\00FCr die Anzeigebedingung keine Zeilen zur\00FCckgibt.</LI>'),
'',
unistr('<LI>PLSQL_EXPRESSION: Die Registerkarte wird nur angezeigt, wenn f\00FCr den PL/SQL-Ausdruck im Feld f\00FCr die Anzeigebedingung TRUE gilt.</LI>'),
'',
unistr('<LI>SQL_EXPRESSION: Die Registerkarte wird nur angezeigt, wenn f\00FCr den SQL-Ausdruck im Feld f\00FCr die Anzeigebedingung TRUE gilt.</LI></UL>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
