wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3053446993523770.4003)
,p_plug_name=>'Hilfe - Slots'
,p_region_template_options=>'#DEFAULT#:js-dialog-size720x480'
,p_plug_template=>wwv_flow_imp.id(557449278618308550.4003)
,p_plug_display_sequence=>220
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li>Wenn die Templatekomponente in einer Region mit Anzeige als Bestandteil verwendet wird, rendert &PRODUCT_NAME. nur Slots im Teiltemplate. Dabei ist keine dynamische Aktualisierung und kein Lazy Loading m\00F6glich.</li>'),
unistr('    <li>Wenn die Templatekomponente in einer Region mit Anzeige als Bericht verwendet wird, rendert &PRODUCT_NAME. nur Slots im Berichtscontainertemplate. Das Berichtscontainertemplate umschlie\00DFt das Template f\00FCr den Hauptteil des Berichts.</li>'),
unistr('    <li>Es k\00F6nnen keine Slots in den Berichtszeilen oder interaktiven Berichtsspalten gerendert werden, da Slotinhalt nicht f\00FCr die Wiederholbarkeit beim Seitenrendering konzipiert ist.</li>'),
unistr('    <li>Sie k\00F6nnen pr\00FCfen, ob Slotinhalt vorhanden ist, um zus\00E4tzliches Markup nur zu rendern, wenn der Slot verwendet wird. Beispiel:'),
'        <pre><code>',
'            &lt;div class="outer-div"&gt;',
'            {if SLOT_A/}',
'            &lt;div class="inner-div"&gt;#SLOT_A#&lt;/div&gt;',
'            {endif/}',
'            &lt;/div&gt;',
'        </code></pre>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
