,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen der PL/SQL-Funktion ein, die aufgerufen werden soll, um gesperrte Ressourcen freizugeben oder damit verkn\00FCpfte Zeilen in einem Workflowkontext zu stoppen, besonders dann, wenn ein Plug-in einen Wait-Status bewirkt. '),
unistr('Durch Aufrufen der Beendigungsfunktion kann das Plug-in Ressourcen effektiv freigeben, wenn die damit verkn\00FCpfte Workflowinstanz beendet wird.'),
'Sie kann eine Funktion des anonymen PL/SQL-Codeblocks, eine Packagefunktion oder eine Einzelfunktion in der Datenbank referenzieren. Beispiel:',
'<pre>',
'terminate_proc',
'</pre></p>',
'',
unistr('<p>Wenn Sie eine PL/SQL-Datenbankpackage- oder eine Einzelfunktion referenzieren, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#OWNER#</code> zum Referenzieren des Parsingschemas der aktuellen Anwendung verwenden. Beispiel:'),
'<pre>',
'#OWNER#.terminate_proc',
'</pre></p>',
'',
unistr('<p>Plug-in-Beendigungsfunktionen des Prozesstyps m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'function name_of_function (',
'    p_process in apex_plugin.t_process,',
'    p_plugin  in apex_plugin.t_plugin )',
'    return apex_plugin.t_process_terminate_result',
'',
'</pre>',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
