wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(9811750713144402.4003)
,p_name=>'P4410_PARTIAL_TEMPLATE'
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Teilweise'
,p_source=>'PARTIAL_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>25
,p_field_template=>wwv_flow_imp.id(561549716994252345.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie das Markup f\00FCr das Template ein. Die statischen IDs der benutzerdefinierten Attribute des Geltungsbereichs "Komponente" k\00F6nnen mit <code>#STATIC_ID#</code>-Syntax referenziert werden.'),
unistr('Mit der Schaltfl\00E4che <strong>Aus Templates synchronisieren</strong> k\00F6nnen Sie schnell alle Platzhalter als benutzerdefinierte Attribute synchronisieren.'),
'</p>',
'<p>',
unistr('Die folgenden vordefinierten Templateplatzhalter werden unterst\00FCtzt:'),
'<dl>',
'<dt>APEX$DOM_ID</dt>',
unistr('<dd>Eindeutige DOM-ID, die beim Aufrufen des Templates generiert wird. Sie ist n\00FCtzlich zum Referenzieren anderer DOM-Elemente im angegebenen HTML-Markup.</dd>'),
'<dt>APEX$IS_LAZY_LOADING</dt>',
'<dd>Setzen Sie diesen Platzhalter auf <code>T</code>, wenn die Region Lazy Loading zum Laden der Daten verwendet und stattdessen Skeleton-Markup gerendert werden soll.</dd>',
'<dt>APEX$HAS_ACTION_BUTTONS</dt>',
unistr('<dd>Setzen Sie diesen Platzhalter auf <code>T</code>, wenn mindestens eine Schaltfl\00E4chen- oder Schaltfl\00E4chenmen\00FCaktion gerendert wird.</dd>'),
'<dt>APEX$TITLE</dt>',
'<dd>Titel der Region.</dd>',
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
unistr('<dd>F\00FCr die Region angegebene CSS-Klassen.</dd>'),
'<dt>APEX$SELECTOR</dt>',
unistr('<dd>F\00FCr Unterst\00FCtzung der Zeilenauswahl. Wird als Optionsfeld oder Kontrollk\00E4stchen gerendert, f\00FCr Einzel- bzw. Mehrfachauswahl. Dieser Platzhalter wird nur im Kontext eines Templatekomponentenberichts aufgef\00FCllt.</dd>'),
'<dt>APEX$VALUE_IDENTIFIES_ROW</dt>',
unistr('<dd>Enth\00E4lt Zeilenwerte von Berichtsspalten, bei denen die f\00FCr die Barrierefreiheit relevante Spalteneinstellung "Wert identifiziert Zeile" aktiviert ist. Wenn Sie diese Einstellung f\00FCr mehrere Berichtsspalten aktivieren, werden die Werte durch Leerz')
||unistr('eichen getrennt ausgegeben. Dieser Platzhalter wird nur im Kontext eines Templatekomponentenberichts aufgef\00FCllt.</dd>'),
'</dl>',
'</p>',
unistr('<p>Die statischen IDs von Aktionspositionen k\00F6nnen mit <code>#STATIC_ID#</code>-Syntax referenziert werden.'),
'Wenn die Aktionsposition den Typ "Link" aufweist, kann <code>#STATIC_ID_ATTR#</code> verwendet werden, um den Wert des Linkattributs zu referenzieren.</p>',
unistr('<p>Sie k\00F6nnen auch Slotplatzhalter verwenden, damit dieser Bestandteil Seitenkomponenten (Regionen, Elemente, Schaltfl\00E4chen) rendern kann. Slots k\00F6nnen mit <code>#SLOT_STATIC_ID#</code>-Syntax referenziert werden. F\00FCr bedingtes Rendering eines Slots ')
||unistr('abh\00E4ngig von seiner Verwendung nutzen Sie die Syntax <code>{if SLOT_STATIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code>. Damit wird zus\00E4tzliches Markup nur gerendert, wenn der Slot verwendet wird. Slots im Teiltemplate')
||unistr(' werden nur gerendert, wenn die zugeh\00F6rige Region <strong>Anzeigen als: Einzelne (Teilweise)</strong> verwendet</p>'),
'',
unistr('<p>Unterst\00FCtzt Templatedirektiven.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
