wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(20527901230873212.4003)
,p_name=>'P4410_SUBSTITUTE_ATTRIBUTES'
,p_item_sequence=>340
,p_item_plug_id=>wwv_flow_imp.id(48467930491898431.4003)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Attributwerte ersetzen'
,p_source=>'SUBSTITUTE_ATTRIBUTES'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Benutzerdefinierte Attributwerte, die vom Entwickler angegeben werden, k\00F6nnten Elemente enthalten, die mit Ersetzungssyntax referenziert werden. Beispiel: <code>&amp;P1_DNAME.</code>'),
'</p>',
'<p>Wenn "Attributwerte ersetzen" auf <strong>Ein</strong> gesetzt ist, ersetzt &PRODUCT_NAME. diese Referenzen automatisch durch ihren eigentlichen Wert, bevor das Plug-in aufgerufen wird.',
'</p>',
unistr('<p>Wenn "Attributwerte ersetzen" auf <strong>Aus</strong> gesetzt ist, werden die Werte unver\00E4ndert in die Datensatztypattribute <code>attribute_01 - attribute_25</code> von <code>p_plugin, p_item, p_region, ...</code> geschrieben. Der Plug-in-Entwic')
||unistr('kler ist dann daf\00FCr verantwortlich, diese Ersetzungssyntaxreferenzen durch einen Aufruf von <code>apex_plugin_util.replace_substitutions</code> zu ersetzen oder \00E4hnliche Ersetzungen vorzunehmen.'),
'</p>',
unistr('<p>Ein Anwendungsfall f\00FCr <strong>Aus</strong> w\00E4re beispielsweise, wenn das benutzerdefinierte Plug-in-Attribut als Template verwendet wird und die Ersetzungssyntax zur Referenzierung von Seitenelementen und Spalten der SQL-Anweisung verwendet wird,')
||unistr(' die vom Plug-in ausgef\00FChrt wird. Da die Spaltenwerte der SQL-Anweisung beim Aufruf des Plug-ins nicht verf\00FCgbar sind, muss die Ersetzung vom Plug-in selbst vorgenommen werden.'),
'</p>',
unistr('<p>Beispiel f\00FCr die manuelle Ersetzung von Spaltenwerten f\00FCr jede Zeile:</p>'),
'<pre>',
'/* Read data */',
'l_column_value_list := apex_plugin_util.get_data2 (',
'                           p_sql_statement => p_region.source,',
'                           p_region        => p_region );',
'/* Emit rows */',
'for l_row_num in 1 .. l_column_value_list( 1 ).value_list.count loop',
'    begin',
'        -- Assign the column values of the current row',
'        -- into session state',
'        apex_plugin_util.set_component_values (',
'            p_column_value_list => l_column_value_list,',
'            p_row_num           => l_row_num );',
'',
'        ...',
'',
'        -- Link Attribute: Replace substitution variables',
'        -- (including column values of the current row)',
'        l_link := apex_plugin_util.replace_substitutions(',
'                      p_value => p_region.attribute_01 );',
'        ...',
'',
'        apex_plugin_util.clear_component_values;',
'    exception when others then',
'        apex_plugin_util.clear_component_values;',
'        raise;',
'    end;',
'end loop;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
