,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie einen internen Namen f\00FCr das Plug-in ein. Der interne Name wird von &PRODUCT_NAME. zur Identifikation des Plug-ins verwendet und nicht angezeigt. Der interne Name muss in Ihrer aktuellen Anwendung eindeutig sein.</p>'),
'',
unistr('<p>Es wird empfohlen, den Domainnamen Ihrer Organisation als Pr\00E4fix von Plug-in-Namen zu verwenden, sodass ein global eindeutiger Name entsteht. Zum Beispiel w\00FCrde der Domainname "mycompany.com" als Pr\00E4fix des Elementtyp-Plug-ins mit dem Namen "Slide')
||'r" einen internen Namen wie den folgenden ergeben: <code>COM.MYCOMPANY.SLIDER</code></p>',
'',
unistr('<p>Dem internen Namen eines Templatekomponenten-Plug-ins, das Teil eines Themes ist, wird immer das Pr\00E4fix "THEME$" vorangestellt: <code>THEME$COM.MYCOMPANY.BADGE</code>.'),
unistr('Verwenden Sie diesen internen Namen, um eine Templatekomponente manuell dort anzuwenden, wo serverseitige Templatedirektiven unterst\00FCtzt werden.'),
'<pre><code>',
'{with/}',
'MY_ARGUMENT:=foo',
'{apply THEME$COM.MYCOMPANY.BADGE/}    ',
'</code></pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'text_case', 'UPPER',
  'trim_spaces', 'BOTH')).to_clob
);
