,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Bestimmt den virtuellen Pfad, den der Webserver verwendet, um auf die Dateien des Plug-ins zu verweisen.</p>',
'',
'<p>Machen Sie keine Angaben zur Referenzierung von Dateien, die mit Ihrer Plug-in-Definition in der Datenbank gespeichert sind.</p>',
'',
unistr('<p>Aus Performancegr\00FCnden k\00F6nnen Sie die Plug-in-Dateien auch auf dem Webserver speichern. Verwenden Sie <code>#APEX_FILES#</code> oder eine g\00FCltige URL zur Referenzierung der Dateien.</p>'),
'',
