wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27936921271036180.4003)
,p_name=>'P4410_RENDER_FUNCTION'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Prozedur-/Funktionsbezeichnung rendern'
,p_source=>'RENDER_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den Namen der PL/SQL-Prozedur/-Funktion ein, die zum Rendern des Plug-ins aufgerufen werden soll. Dieser kann eine Prozedur oder Funktion des anonymen PL/SQL-Codeblocks, eine Packageprozedur oder -funktion oder eine Standalone-Prozedur o'
||'der -Funktion in der Datenbank referenzieren. Beispiel:',
'<pre>',
'render_slider',
'</pre></p>',
'',
unistr('<p>Wenn Sie eine Datenbank-PL/SQL-Package- oder Standalone-Prozedur/-Funktion referenzieren, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#OWNER#</code> zum Referenzieren des Parsingschemas der aktuellen Anwendung verwenden. Beispiel:'),
'<pre>',
'#OWNER#.render_slider',
'</pre></p>',
'',
unistr('<p>Renderingprozeduren von Elementtyp-Plug-ins m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'procedure &lt;Name der Prozedur&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_render_param,',
'    p_result in out nocopy apex_plugin.t_item_render_result )',
'</pre>',
'</p>',
'',
unistr('<p>Renderingprozeduren von Regionstyp-Plug-ins m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'procedure &lt;Name der Prozedur&gt; (',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_region in            apex_plugin.t_region,',
'    p_param  in            apex_plugin.t_region_render_param,',
'    p_result in out nocopy apex_plugin.t_region_render_result )',
'</pre>',
'</p>',
'',
unistr('<p>Renderingfunktionen von Plug-ins f\00FCr dynamische Aktionen m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'function &lt;Name der Funktion&gt; (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_dynamic_action_render_result',
'</pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27937216900044386.4003)
,p_name=>'P4410_AJAX_FUNCTION'
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'AJAX Prozedur-/Funktionsbezeichnung'
,p_source=>'AJAX_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen der PL/SQL-Prozedur/-Funktion ein, mit der das Plug-in zus\00E4tzliche Daten mit einem Ajax-Aufruf l\00E4dt. Dieser kann eine Prozedur oder Funktion des anonymen PL/SQL-Codeblocks, eine Packageprozedur oder -funktion oder eine Standalo')
||'ne-Prozedur oder -Funktion in der Datenbank referenzieren. Beispiel:',
'<pre>',
'ajax_slider',
'</pre></p>',
'',
unistr('<p>Wenn Sie eine Datenbank-PL/SQL-Package- oder Standalone-Prozedur oder -Funktion referenzieren, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#OWNER#</code> zum Referenzieren des Parsingschemas der aktuellen Anwendung verwenden. Beispiel:'),
'<pre>',
'#OWNER#.ajax_slider',
'</pre></p>',
'',
unistr('<p>Der Ajax-Prozedur-Callback funktioniert genauso wie ein Ajax-Callback-Prozess und kann auf die generischen globalen Variablen <code>apex_application.g_x01 - g_x10</code> zugreifen, um Daten vom Browser an das Backend zu \00FCbertragen. Er kann au\00DFerde')
||'m wie ein Ajax-Callback-Prozess den Sessionzustand lesen und festlegen.</p>',
'',
unistr('<p>Zum Aufrufen der Ajax-Callback-Funktion aus JavaScript verwenden Sie dieselbe Methode wie f\00FCr Ajax-Callback-Prozesse. Anstelle von <code>APPLICATION_PROCESS=[process name]</code> verwenden Sie <code>PLUGIN=[p_ajax_identifier]</code>, wobei "p_ajax')
||'_identifier" der mit der Funktion "apex_plugin.get_ajax_identifier" generierte Wert in der Renderingfunktion ist.</p>',
'',
unistr('<p>Ajax-Prozeduren von Elementtyp-Plug-ins m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'procedure &lt;Name der Prozedur&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_ajax_param,',
'    p_result in out nocopy apex_plugin.t_item_ajax_result )',
'</pre>',
'</p>',
'',
unistr('<p>Ajax-Prozeduren von Regionstyp-Plug-ins m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'procedure &lt;Name der Prozedur&gt; (',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_region in            apex_plugin.t_region,',
'    p_param  in            apex_plugin.t_region_ajax_param,',
'    p_result in out nocopy apex_plugin.t_region_ajax_result )',
'</pre>',
'</p>',
'',
unistr('<p>Ajax-Funktionen von Plug-ins f\00FCr dynamische Aktionen m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'function &lt;Name der Funktion&gt; (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_dynamic_action_ajax_result',
'</pre>',
'</p>',
'',
'',
unistr('<p>Ajax-Funktionen von Authentifizierungsschema-Plug-ins m\00FCssen die folgende Schnittstelle implementieren:'),
'',
'<pre>',
'function &lt;Name der Funktion&gt; (',
'    p_authentication in apex_plugin.t_authentication,',
'    p_plugin         in apex_plugin.t_plugin )',
'    return apex_plugin.t_authentication_ajax_result',
'</pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(27937500062049023.4003)
,p_name=>'P4410_VALIDATION_FUNCTION'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Validierungsprozedurname'
,p_source=>'VALIDATION_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen der PL/SQL-Prozedur ein, mit der das Plug-in Basisvalidierungen der weitergeleiteten Daten ausf\00FChren kann. Dieser kann eine Prozedur des anonymen PL/SQL-Codeblocks, eine Packageprozedur oder eine Standalone-Prozedur in der Date')
||'nbank referenzieren. Beispiel:',
' <pre> ',
'validate_slider',
'</pre></p>',
'',
unistr('<p>Wenn Sie eine Datenbank-PL/SQL-Package- oder Standalone-Prozedur referenzieren, k\00F6nnen Sie mit der Ersetzungszeichenfolge <code>#OWNER#</code> das Parsingschema der aktuellen Anwendung referenzieren. Beispiel:'),
'<pre>',
'#OWNER#.validate_slider',
'</pre></p>',
'',
unistr('<p>Der Validierungsprozedur-Callback wird aufgerufen, nachdem die von &PRODUCT_NAME. ausgef\00FChrten Basispr\00FCfungen abgeschlossen sind und bevor die benutzerdefinierten Validierungen verarbeitet werden. Verwenden Sie den Platzhalter <em>#LABEL#</em> in ')
||unistr('der Fehlermeldung, wenn Sie das aktuelle Label des Seitenelements abrufen m\00F6chten. Wenn <code>message</code> einen Wert nach dem Aufruf enth\00E4lt, wird die Meldung in der <em>Standardposition f\00FCr die Fehleranzeige</em> angezeigt, die auf Anwendungseben')
||unistr('e definiert wurde. Wenn Sie die Standardposition \00FCberschreiben m\00F6chten, kann <code>display_location</code> einen der konstanten Werte enthalten, die in <code>apex_plugin</code> definiert sind. Wenn Sie den Fehler mit einem anderen Seitenelement als d')
||unistr('em gerade verarbeiteten anzeigen m\00F6chten, legen Sie f\00FCr <code>page_item_name</code> den Namen dieses Seitenelements fest.</p> '),
'',
'<p>Validierungsprozedur von Elementtyp-Plug-ins muss die folgenden Schnittstelle implementieren:',
'',
'<pre>',
'procedure &lt;Name der Prozedur&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_validation_param,',
'    p_result in out nocopy apex_plugin.t_item_validation_result )',
'</pre>',
'</p>',
'',
unistr('<p>Regionstyp-Plug-ins unterst\00FCtzen keine Validierungsfunktionen.</p>'),
'',
unistr('<p>Plug-ins f\00FCr dynamische Aktionen unterst\00FCtzen keine Validierungsfunktionen.</p>'),
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
