wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(439396713209952288.4003)
,p_name=>'P4410_REGION_ATTRIBUTES'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(439386704233826730.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Attribute:'
,p_source=>'P4410_STANDARD_ATTRIBUTES'
