,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'PLUGIN.REGION_ATTRIBUTES'
,p_lov=>'.'||wwv_flow_imp.id(439394121736945367)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Pr\00FCfen Sie bei Regions-Plug-ins Folgendes, um Optionen wie hier beschrieben zu aktivieren:'),
'</p>',
'<p>',
'<ul>',
unistr('<li>Regionsquelle ist eine SQL-Anweisung:  Die Regionsquelle ist eine SQL-Anweisung. Wenn diese Option aktiviert ist, kann eine minimale und maximale Anzahl von Spalten angegeben werden, die die Abfrage zur\00FCckgeben kann. Au\00DFerdem k\00F6nnen SQL-Beispiele')
||unistr(' zur Unterst\00FCtzung des Benutzers angezeigt werden.</li>'),
'<li>Regionsquelle ist einfacher Text: Die Regionsquelle ist Klartext.</li>',
'<li>Regionsquelle erforderlich: Wenn die Regionsquelle eine SQL-Anweisung ist, wird sie durch dieses Attribut zu einem obligatorischen Wert.</li>',
unistr('<li>Hat Attribut "Weiterzuleitende Seitenelemente": Wenn die Regionsquelle eine SQL-Anweisung ist, k\00F6nnen Sie mit diesem Attribut die Seitenelemente angeben, die im Sessionzustand festgelegt werden m\00FCssen, wenn ein AJAX-Aufruf f\00FCr diese Region ausgef')
||unistr('\00FChrt wird.</li>'),
unistr('<li>Hat Attribut "Anzahl abgerufener Zeilen": Die Region enth\00E4lt die Felder "Anzahl abgerufener Zeilen" im Abschnitt "Erweitert", wenn die Region bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Attribut "Meldung bei nicht gefundenen Daten": Die Region enth\00E4lt das Feld "Meldung bei nicht gefundenen Daten" im Abschnitt "Erweitert", wenn die Region bearbeitet wird.</li>'),
unistr('<li>Hat Attribut "Sonderzeichen maskieren": Die Region enth\00E4lt das Feld "Escape bei Sonderzeichen" im Abschnitt "Sicherheit", wenn die Region bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt "Regionsspalten": In der Region k\00F6nnen Sie zus\00E4tzliche benutzerdefinierte Attribute f\00FCr jede Spalte der SQL-Anweisung der Regionsquelle angeben.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "\00DCberschrift": Regionspalten enthalten das Feld "\00DCberschrift" im Abschnitt "\00DCberschrift", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "\00DCberschriftenausrichtung": Regionsspalten enthalten das Feld "Ausrichtung" im Abschnitt "\00DCberschrift", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "Ausrichtung": Regionsspalten enthalten das Feld "Spaltenausrichtung" im Abschnitt "Layout", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "CSS-Klassen": Regionsspalten enthalten das Feld "CSS-Klassen" im Abschnitt "Darstellung", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "Benutzerdefinierte Attribute": Regionsspalten enthalten das Feld "Benutzerdefinierte Attribute" im Abschnitt "Erweitert", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Spaltenattribut "Sonderzeichen maskieren": Regionsspalten enthalten das Feld "Escape bei Sonderzeichen" im Abschnitt "Sicherheit", wenn die Spalte bearbeitet wird.</li>'),
unistr('<li>Enth\00E4lt Attribut "Initialisierungs-JavaScript-Code": Das Feld "Initialisierungs-JavaScript-Code" ist f\00FCr die Aktion verf\00FCgbar.</li>'),
unistr('<li>Unterst\00FCtzt Facet-Suche/intelligente Filter: Die Region kann mit einer Region f\00FCr Facet-Suche oder intelligente Filter verbunden werden. "Regionsquelle ist eine SQL-Anweisung" ist daf\00FCr erforderlich.</li>'),
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
