wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(573060960895794186.4003)
,p_name=>'P4410_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(538625467201238345.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'JavaScript'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cMaxlength=>4000
,p_cHeight=>3
,p_tag_css_classes=>'a-Form-textarea--code'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie JavaScript-Datei-URLs f\00FCr Code ein, der mit diesem Plug-in geladen werden soll. Jede URL muss in einer eigenen Zeile stehen. Wenn Sie eine minimierte Version der Datei angeben, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#MIN#</code> ode')
||unistr('r <code>#MIN_DIRECTORY#</code> verwenden, um <code>.min</code> bzw. <code>minified/</code> in die Datei-URL f\00FCr eine regul\00E4re Seitenansicht aufzunehmen, bzw. eine leere Zeichenfolge, wenn die Seite im Debug-Modus angezeigt wird. Au\00DFerdem haben Sie Zu')
||unistr('griff auf die Ersetzungszeichenfolge <code>#PLUGIN_FILES#</code>, um den Wert des Dateipr\00E4fixes des Plug-ins zu ersetzen.</p>'),
'',
'<p>JavaScript-Datei-URLs, die Sie hier eingeben, werden in der Ersetzungszeichenfolge <code>#GENERATED_JAVASCRIPT#</code> im Seitentemplate ausgegeben.</p>',
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>script</code>-Tags einbeziehen. Schreiben Sie einfach die Datei-URL.'),
'',
'<p>',
'Beispiele:',
'<ul>',
'  <li>Standarddateireferenz',
'      <pre>#PLUGIN_FILES#main.js</pre>',
'  </li>',
unistr('  <li>Standarddateireferenz, die die minimierte Datei main.min.js aus #PLUGIN_FILES#minified/ bei regul\00E4ren Seitenansichten und main.js aus #PLUGIN_FILES# im Debug-Modus l\00E4dt.'),
'      <pre>#PLUGIN_FILES##MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Library auch \00FCber einen Require-Aufruf "RequireJS" verwendet wird. Der Define-Name muss mit den Angaben in den requirejs.config-Pfaden \00FCbereinstimmen, und der Wert muss das globale Symbol sein, das von der L')
||unistr('ibrary verf\00FCgbar gemacht wird. Gilt nur, wenn RequireJS verwendet wird. Dadurch wird verhindert, dass RequireJS diese Library ein zweites Mal l\00E4dt.'),
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Datei von Oracle JET abh\00E4ngig ist. Dadurch werden RequireJS, die Oracle JET RequireJS-Konfiguration und das gemeinsame JET-Modul-Bundle automatisch vor dieser Datei geladen.'),
'      <pre>[require jet]/myjs/main.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Datei von RequireJS abh\00E4ngig ist. Dadurch wird RequireJS automatisch vor dieser Datei geladen.'),
'      <pre>[require requirejs]/myjs/main.js</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'NONE')).to_clob
);
