,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Bei <strong>Ein</strong> wird die Bedingung immer ausgewertet. Als Vorbedingung muss das "Depending-On"-Attribut gerendert werden. Bei <strong>Aus</strong> wird die Bedingung auch ausgewertet, wenn das "Depending-On"-Attribut gerendert wurde. Wenn'
||' das "Depending-On"-Attribut jedoch NICHT gerendert wurde, wird die Bedingung nicht ausgewertet.</p>',
'',
unistr('<p>Dies ist beispielsweise n\00FCtzlich, wenn das "Depending-On"-Attribut selbst eine Bedingung enth\00E4lt (es unterst\00FCtzt z.B. nur bestimmte Komponententypen) und wenn Sie das Rendering des aktuellen Attributs auch w\00FCnschen, wenn die Bedingung des "Dependi')
||unistr('ng-On"-Attributs nicht erf\00FCllt ist.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
