,p_prompt=>'Abonnieren von'
,p_source=>'REFERENCE_ID'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''|| b.display_name d,',
'       b.id r',
'  from wwv_flow_plugin_settings_dev b,',
'       wwv_flows f',
' where b.flow_id          != nvl(:FB_FLOW_ID,0)',
'   and b.flow_id           = f.id',
'   and f.build_status      not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
'   and b.security_group_id = :WORKSPACE_ID',
'   and f.security_group_id = :WORKSPACE_ID',
'   -- limit to current plugin and plugin type',
'   and ((    b.plugin      = :P4446_PLUGIN',
'         and b.plugin_type = :P4446_PLUGIN_TYPE )',
'         -- always show selected master record',
'          or b.id = :P4446_REFERENCE_ID_INIT )',
'order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Keine Subscription -'
,p_lov_cascade_parent_items=>'P4446_PLUGIN,P4446_PLUGIN_TYPE,P4446_REFERENCE_ID_INIT'
,p_ajax_optimize_refresh=>'Y'
