,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('W\00E4hlen Sie eine Masterkomponente zum Abonnieren aus. Wenn Sie eine Masterkomponente ausw\00E4hlen und auf die Schaltfl\00E4che <strong>\00C4nderungen anwenden</strong> klicken, werden die Komponenteneinstellungen automatisch anhand des ausgew\00E4hlten Masters aktua')
||unistr('lisiert.<br /><br />Wenn die Komponenteneinstellungen bereits abonniert wurden, verwenden Sie die Schaltfl\00E4che <strong>Komponenteneinstellungen aktualisieren</strong>, um die Komponenteneinstellungen anhand der Masterkomponente zu aktualisieren.')
