wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346057922272119929.4003)
,p_name=>'P4495_POST_AUTH_PROCESS'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(345924009281078364.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Name der Post-Authentifizierungsprozedur'
,p_source=>'POST_AUTH_PROCESS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den Namen einer Prozedur an, die von der &PRODUCT_NAME.-Anmeldeprozedur (Anmelde-API) nach',
unistr('der Authentifizierung (Pr\00FCfung der Anmeldedaten) ausgef\00FChrt werden muss. Die Anmeldeprozedur f\00FChrt diesen Code aus, nachdem'),
unistr('die Zugangsdaten des Benutzers gepr\00FCft wurden, jedoch bevor der Benutzer in der Session registriert und an die'),
unistr('gew\00FCnschte Anwendungsseite umgeleitet wird. Die Prozedur kann im Attribut "PL/SQL Code" oder'),
'innerhalb der Datenbank definiert werden.</p>',
'',
'<p>Beispiel: Um den authentifizierten Benutzernamen <code>JOHNDOE@EXAMPLE.COM</code> in',
