wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346898909384210784.4003)
,p_name=>'P4495_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(345889721617072434.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Schematyp'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHENTICATION_SCHEME_TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHENTICATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHENTICATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHENTICATION TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Legen Sie fest, wie dieses Authentifizierungsschema angewendet wird. Die folgenden integrierten Typen werden unterst\00FCtzt (sie k\00F6nnen mit Plug-ins erweitert werden):</p>'),
'<ul>',
unistr('    <li><strong>Anmeldung \00FCber Builder-Erweiterung</strong>: Damit k\00F6nnen Sie diese Anwendung in die APEX-Entwicklungsumgebung integrieren.</li>'),
unistr('    <li><strong>Benutzerdefiniert</strong>: Hiermit k\00F6nnen Sie ein neues benutzerdefiniertes Authentifizierungsschema erstellen, mit dem Sie die vollst\00E4ndige Kontrolle \00FCber die Authentifizierungsschnittstelle erhalten.</li>'),
'    <li><strong>Datenbankaccounts</strong>: Dieses Authentifizierungsschema erfordert, dass ein Datenbankbenutzer (Schema) in der lokalen Datenbank vorhanden ist. Bei Verwendung dieser Methode werden der Benutzername und das Kennwort des Datenbankacc'
||'ounts zur Authentifizierung des Benutzers verwendet.</li>',
'    <li><strong>HTTP-Headervariable</strong>: Nimmt eine externe Authentifizierung vor, bei der der Benutzername in einer HTTP-Headervariable gespeichert wird, die vom Webserver festgelegt wird.</li>',
unistr('    <li><strong>Erweiterung f\00FCr interne Anwendung</strong>: Verwenden Sie dieses Schema f\00FCr Erweiterungen zu internen Anwendungen.</li>'),
'    <li><strong>LDAP-Verzeichnis</strong>: Authentifizierung von Benutzer/Kennwort mit einer Authentifizierungsanforderung an einen LDAP-Server.</li>',
unistr('    <li><strong>Keine Authentifizierung</strong>: \00DCbernimmt den aktuellen Datenbankbenutzer.</li>'),
unistr('    <li><strong>Open-Door-Zugangsdaten</strong>: Erm\00F6glicht jedem den Zugriff auf die Anwendung mit einer Anmeldeseite, die einen Benutzernamen erfasst.</li>'),
'    <li><strong>Oracle APEX-Accounts</strong>: &PRODUCT_NAME.-Accountzugangsdaten sind interne Benutzeraccounts, die innerhalb des &PRODUCT_NAME.-Benutzer-Repositorys erstellt und verwaltet werden. Wenn Sie diese Methode verwenden, wird die Anwendung'
||' mit diesen Accounts authentifiziert.</li>',
unistr('    <li><strong>SAML-Anmeldung</strong>: Unterst\00FCtzt die Authentifizierung mit SAML2-Identit\00E4tsprovidern.</li>'),
unistr('    <li><strong>Social Sign-In</strong>: Unterst\00FCtzt die Authentifizierung mit Google, Facebook, generischem OpenID Connect und generischen OAuth2-Identit\00E4tsprovidern.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
