,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">Regionstemplates bestimmen die Darstellung eines Teils einer Seite, der als Region bezeichnet wird. Mit Ersetzungszeichenfolgen geben Sie das Vorhandensein und die Position einer Komponente in der Region an.</div>',
'<div class="htmldbInfoBodyP">#BODY# ist die einzige erforderliche Ersetzungszeichenfolge. Sie gibt an, wo die Quelle der Region positioniert werden soll. Alle anderen Ersetzungszeichenfolgen sind optional.</div>',
unistr('<div class="htmldbInfoBodyP">Folgende Ersetzungszeichenfolgen sind g\00FCltig:'),
'<ul class="noIndent">',
'<li>#TITLE#</li>',
'<li>#PAGE_TITLE#</li>',
'<li>#EXPAND#</li>',
'<li>#CHANGE#</li>',
'<li>#BODY#</li>',
'<li>#SUB_REGION_HEADERS#</li>',
'<li>#SUB_REGIONS#</li>',
'<li>#FORM_OPEN#</li> ',
'<li>#FORM_CLOSE#</li>',
'<li>#REGION_ID#</li>',
'<li>#REGION_STATIC_ID#</li>',
'<li>#REGION_CSS_CLASSES#</li>',
'<li>#REGION_ATTRIBUTES#</li>',
'<li>#REGION_HEADER#</li>',
'<li>#REGION_FOOTER#</li>',
'<li>#REGION_IMAGE#</li>',
'<li>#REGION_IMAGE_URL#</li>',
'<li>#REGION_IMAGE_ALT_TEXT#</li>',
'<li>#REGION_IMAGE_ATTRIBUTES#</li>',
'<li>#REGION_LANDMARK_ATTRIBUTES#</li>',
'</ul>',
'</div>',
unistr('<div class="htmldbInfoBodyP">Sie k\00F6nnen Slots von Schaltfl\00E4chen in dieser Region auch mit den folgenden Ersetzungszeichenfolgen angeben:</div>'),
'<ul class="noIndent">',
'<li>#EDIT#</li>',
'<li>#CLOSE#</li>',
'<li>#CREATE#</li>',
'<li>#CREATE2#</li>',
'<li>#EXPAND#</li>',
'<li>#HELP#</li>',
'<li>#DELETE#</li>',
'<li>#COPY#</li>',
'<li>#NEXT#</li>',
'<li>#PREVIOUS#</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
