wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1094586109106933030.4003)
,p_name=>'P4653_JAVASCRIPT_FILE_URLS'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(1094586036782933029.4003)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Datei-URLs'
,p_source=>'JAVASCRIPT_FILE_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cHeight=>3
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie JavaScript-Datei-URLs f\00FCr Code ein, der auf dieser Seite geladen werden soll. Jede URL muss in einer eigenen Zeile stehen. Wenn Sie eine minimierte Version der Datei angeben, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#MIN#</code> oder ')
||unistr('<code>#MIN_DIRECTORY#</code> verwenden, um <code>.min</code> bzw. <code>minified/</code> in der Datei-URL f\00FCr eine regul\00E4re Seitenansicht aufzunehmen, bzw. eine leere Zeichenfolge, wenn die Seite im Debug-Modus angezeigt wird. Au\00DFerdem haben Sie Zugr')
||unistr('iff auf die Ersetzungszeichenfolge <code>#APP_VERSION#</code>, wenn Sie die Version der Anwendung in die Datei-URL einbeziehen m\00F6chten.</p>'),
'',
unistr('<p>Hinweis: Sie m\00FCssen keine \00F6ffnenden oder schlie\00DFenden <code>script</code>-Tags einbeziehen. Schreiben Sie einfach die URL.'),
'',
'<p>',
'Beispiele:',
'<ul>',
'  <li>Standarddateireferenz',
'      <pre>/myjs/main.js</pre>',
'  </li>',
unistr('  <li>Standarddateireferenz, die die minimierte Datei main.min.js aus /myjs/minified/ bei regul\00E4ren Seitenansichten und main.js aus /myjs/ im Debug-Modus l\00E4dt.'),
'      <pre>/myjs/#MIN_DIRECTORY#main#MIN#.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Library auch aus einem Require-Aufruf "RequireJS" verwendet wird. Der Define-Name muss mit den Angaben in den requirejs.config-Pfaden \00FCbereinstimmen, und der Wert muss das globale Symbol sein, das von der Li')
||unistr('brary verf\00FCgbar gemacht wird. Gilt nur, wenn RequireJS verwendet wird. Dadurch wird verhindert, dass RequireJS diese Library ein zweites Mal l\00E4dt.'),
'      <pre>[define hammerjs=Hammer]/myjs/hammer.js</pre>',
'  </li>',
unistr('  <li>Verwenden Sie diese Syntax, wenn die Datei von RequireJS abh\00E4ngig ist. Dadurch wird RequireJS automatisch vor dieser Datei geladen.'),
'      <pre>[require requirejs]/myjs/main.js</pre>',
'  </li>',
unistr('   <li>Verwenden Sie diese Syntax, wenn die Datei von Oracle JET abh\00E4ngig ist. Dadurch werden RequireJS und die Oracle JET RequireJS-Konfiguration automatisch vor dieser Datei geladen.'),
'      <pre>[require jet]/myjs/main.js</pre>',
'  </li>',
unistr('  <li>Dateireferenz, die eine Abfragezeichenfolge in der URL verwendet, die die Anwendungsversion referenziert, sodass beim Upgrade der Anwendung (und beim Erh\00F6hen der Version) der Browser angewiesen wird, immer die neue Datei zu laden und vorher gec')
||'achte Dateien zu ignorieren.',
'      <pre>/myjs/main.js?version=#APP_VERSION#</pre>',
'  </li>',
'</ul>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'Y',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
