,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>unistr('<p>Geben Sie den HTML-Code ein, der am Anfang eines Berichtstemplates angezeigt wird.</p><p>Dieses Attribut wird in der Regel zum \00D6ffnen einer HTML-Tabelle verwendet:</p><pre>&lt;table&gt;</pre><p>Sie k\00F6nnen hier auch die Tabellenspalten-Header angeb')
||unistr('en:</p><pre>&lt;th&gt;#1#&lt;/th&gt;&lt;th&gt;#2#&lt;/th&gt;&lt;th&gt;#3#&lt;/th&gt;</pre><p>Wenn Sie eine Paginierung \00FCber den Berichten anzeigen m\00F6chten, muss Ihr Template folgende Ersetzungszeichenfolge angeben:</p><pre>#TOP_PAGINATION#</pre>Die #')
||unistr('TOP_PAGINATION#-Ersetzungszeichenfolge generiert HTML-Code, der mit einem \00F6ffnenden &lt;tr&gt;-Tag beginnt und mit einem schlie\00DFenden &lt;/tr&gt;-Tag endet. Im Idealfall beziehen Sie ein \00F6ffnendes &lt;table&gt;-Tag und eine #TOP_PAGINATION#-Ersetzung')
||unistr('szeichenfolge folgenderma\00DFen ein:</p><pre>&lt;table&gt;#TOP_PAGINATION#</pre><p>Sie k\00F6nnen auch die Ersetzungszeichenfolge #CSV_LINK# verwenden, wenn Sie den Export Ihres Berichts im CSV-Format f\00FCr Arbeitsbl\00E4tter unterst\00FCtzen m\00F6chten.</p>')
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
