,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Row of WWV_FLOW_ROW_TEMPLATES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'    select 1 ',
'      from sys.dual',
'     where :F4000_P4654_ID is null or exists ( select 1 ',
'                                                 from wwv_flow_row_templates',
'                                                where security_group_id = :FLOW_SECURITY_GROUP_ID ',
'                                                  and flow_id           = :FB_FLOW_ID ',
'                                                  and id                = :F4000_P4654_ID ',
'                                             )',
') loop',
'',
'    wwv_flow_dml.process(',
'        p_action      => wwv_flow.g_request,',
'        p_table_owner => ''#OWNER#'',',
'        p_table_name  => ''WWV_FLOW_ROW_TEMPLATES'',',
'        p_rowid       => v(''F4000_P4654_ID''),',
'        p_alt_rowid   => ''ID'');',
'',
'    exit;',
'',
'end loop;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Fehler beim Verarbeiten von Zeile.'
,p_process_when=>'COPY_TEMPLATE'
,p_process_when_type=>'REQUEST_NOT_IN_CONDITION'
,p_process_success_message=>unistr('\00C4nderungen an Zeilentemplate &F4000_P4654_ROW_TEMPLATE_NAME. wurden verarbeitet.')
,p_internal_uid=>324434648.4003
);
