wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(116587152007891268.4003)
,p_validation_name=>'unique template name'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4655_THEME_ID ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4655_THEME_ID )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4655_THEME_ID )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_list_templates lt,',
'       central_theme ct',
' where ( lt.flow_id, lt.theme_id, lt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4655_THEME_ID, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and list_template_name = :F4000_P4655_LIST_TEMPLATE_NAME',
'   and id                != :F4000_P4655_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Templatename muss eindeutig sein'
,p_associated_item=>wwv_flow_imp.id(53957891426.4003)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
