wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1591026164633612.4003)
,p_plug_name=>unistr('Anwendungs\00FCbersetzung')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>60
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Anwendungen k\00F6nnen von einer prim\00E4ren Sprache in andere Sprachen \00FCbersetzt werden. Durch jede \00DCbersetzung wird eine neue \00FCbersetzte Anwendung erstellt. F\00FCr jede \00DCbersetzung ist eine Zuordnung erforderlich, die die Zielsprache und die ID der \00FCberse')
||unistr('tzten Anwendung identifiziert. \00DCbersetzte Anwendungen k\00F6nnen nicht direkt in App Builder bearbeitet werden.<p/>'),
'',
unistr('<p>Wenn die \00DCbersetzungszuordnungen eingerichtet sind, wird der \00FCbersetzbare Text in der Anwendung in einem \00DCbersetzungs-Repository vordefiniert. Dieses Repository kann dann zur \00DCbersetzung in eine XLIFF-Datei exportiert werden.</p>'),
'',
unistr('<p>Wenn die \00DCbersetzungen in die XLIFF-Datei eingef\00FCgt wurden (jeweils eine Datei pro Sprache), wird die XLIFF-Datei wieder in das \00DCbersetzungs-Repository hochgeladen. Der letzte Schritt ist die Ver\00F6ffentlichung der einzelnen \00FCbersetzten Anwendungen ')
||unistr('aus dem \00DCbersetzungs-Repository.</p>'),
'',
unistr('<p>\00DCbersetzte Anwendungen m\00FCssen synchronisiert werden, wenn die prim\00E4re Anwendung seit der letzten Ver\00F6ffentlichung der \00FCbersetzten Version ge\00E4ndert wurde. Auch \00C4nderungen an der Anwendungslogik erfordern eine Synchronisierung. Zum Synchronisieren m')
||unistr('\00FCssen Sie die \00FCbersetzte Anwendung vordefinieren und ver\00F6ffentlichen.</p>'),
'',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
