,p_prompt=>'Ansicht der Unterschiede'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json sys.json_object_t;',
'    l_left_file  clob;',
'    l_right_file clob;',
'begin',
'    begin',
'        select clob001',
'          into l_left_file ',
'          from wwv_flow_diff_export_left_dev',
'         where seq_id          = :P5302_EXPORT_LEFT_ID;',
'    exception',
'        when no_data_found then',
'            l_left_file := empty_clob();',
'    end;',
'    begin',
'        select clob001',
'          into l_right_file ',
'          from wwv_flow_diff_export_right_dev',
'         where seq_id          = :P5302_EXPORT_RIGHT_ID;',
'    exception',
'        when no_data_found then',
'            l_right_file := empty_clob();',
'    end;',
'',
'    l_json := sys.json_object_t();',
'    l_json.put( ''original'', l_left_file );',
'    l_json.put( ''modified'', l_right_file );',
'',
'    return l_json.to_clob;',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
