,p_step_template=>wwv_flow_imp.id(120871216744825711.4003)
,p_page_template_options=>'#DEFAULT#'
,p_dialog_height=>'560'
,p_protection_level=>'C'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3185079872144510.4003)
,p_plug_name=>'Info zu Arbeitskopien'
,p_region_css_classes=>'padding-left-md padding-right-md'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Tipps</h3>',
'<ul>',
unistr('    <li>Entwickler k\00F6nnen unterschiedliche Arbeitskopien verwenden. So vermeiden Sie \00DCberschreibungen oder Fehler beim Zusammenf\00FChren:'),
'        <ul>',
unistr('            <li>Sperren Sie eine Seite in Ihrer Hauptanwendung, bevor Sie sie in einer Arbeitskopie \00E4ndern</li>'),
unistr('            <li>Reservieren Sie Seitenbereiche f\00FCr neue Seiten, die von Entwicklern erstellt werden</li>'),
unistr('            <li>Einigen Sie sich auf gemeinsame Komponentennamen, die von Entwicklern hinzugef\00FCgt werden</li>'),
'        </ul>',
'    </li>',
unistr('    <li>Exportieren Sie Arbeitskopien nach Bedarf mit <em>Urspr\00FCngliche IDs</em>, um die Verkn\00FCpfung zur Hauptanwendung beizubehalten</li>'),
unistr('    <li><em>Heben Sie die Verkn\00FCpfung einer Arbeitskopie mit der Hauptanwendung auf</em>, indem Sie die Aufgabe <em>Anwendung kopieren</em> verwenden</li>'),
unistr('    <li>L\00F6schen Sie Arbeitskopien, <em>bevor</em> Sie eine Anwendung l\00F6schen</li>'),
'</ul>',
unistr('<h3>Nicht unterst\00FCtzte Komponententypen</h3>'),
unistr('<p>F\00FCr diese Komponententypen wird die <em>automatische</em> Zusammenf\00FChrung noch nicht unterst\00FCtzt:'),
unistr('   \00DCbersetzungen, Themes, Theme-Templates, unterst\00FCtzende Objekte, Anwendungseigenschaften, Registerkarten (Legacy) und'),
unistr('   Komponenten auf Workspace-Ebene (z.B. App-Gruppen, Zugangsdaten oder Remoteserver). Sie k\00F6nnen die Arbeitskopie zusammenf\00FChren'),
unistr('   und dann die Erg\00E4nzungen oder \00C4nderungen dieser Komponententypen manuell anwenden.'),
'</p>',
unistr('<h3>Einschr\00E4nkungen</h3>'),
unistr('<p>Die folgenden Einschr\00E4nkungen gelten f\00FCr Arbeitskopien:</p>'),
'<ul>',
unistr('    <li>Sie k\00F6nnen keine Arbeitskopien einer Arbeitskopie erstellen</li>'),
unistr('    <li>Gel\00F6schte Seiten oder gemeinsame Komponenten von Arbeitskopien m\00FCssen <em>manuell</em> in der Hauptanwendung gel\00F6scht werden</li>'),
unistr('    <li>Komponenten, die als <em>Fehlend</em> aufgelistet werden, wurden m\00F6glicherweise in der Arbeitskopie entfernt oder sind nur in der Hauptanwendung vorhanden</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
