,p_process_type=>'NATIVE_FORM_DML'
,p_process_name=>'Save Map Background Changes'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update wwv_flow_map_backgrounds',
'   set name              = :P6120_NAME,',
'       type              = :P6120_TYPE,',
'       url               = case',
'                             when :P6120_TYPE = ''RASTER'' then',
'                                 :P6120_XYZ_TILE_SERVER_URL',
'                             when :P6120_TYPE = ''OGCWMS'' then',
'                                 :P6120_WMS_URL',
'                             when :P6120_TYPE = ''VECTOR'' then',
'                                 :P6120_MAP_STYLESHEET',
'                             else',
'                                 null',
'                           end,',
'       attribution       = :P6120_ATTRIBUTION,',
'       api_key           = :P6120_API_KEY,',
'       http_headers      = :P6120_HTTP_HEADERS,',
'       map_comment       = :P6120_MAP_COMMENT,',
'       reference_id      = :P6120_REFERENCE_ID,',
'       zoom_min          = :P6120_ZOOM_MIN,',
'       zoom_max          = :P6120_ZOOM_MAX',
' where id                = :P6120_ID',
'   and flow_id           = :P6120_FLOW_ID',
'   and security_group_id = :P6120_SECURITY_GROUP_ID;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1890669015145483.4003)
,p_process_success_message=>unistr('\00C4nderungen an Kartenhintergrund gespeichert.')
,p_internal_uid=>1859284179065945.4003
);
