wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4800456594119504.4003)
,p_plug_name=>'Automatisierungen'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>70
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('<strong>Automatisierungen</strong> l\00F6sen eine Abfolge von Prozessen aus. Sie werden zum \00DCberwachen von Daten und anschlie\00DFenden Ausf\00FChren der entsprechenden Aktion verwendet (Beispiele umfassen das automatische Genehmigen bestimmter Anforderungen und')
||' das Senden von E-Mail-Alerts).',
'</p>',
'<p>',
unistr('<strong>Automatisierungsaktionen</strong> werden pro Zeile, die von der Automatisierungsquelle zur\00FCckgegeben wird, einmal ausgel\00F6st. Eine Aktion kann die Werte jeder Spalte f\00FCr jede Zeile mithilfe von Bind-Variablensyntax referenzieren.</p>'),
'<p>',
unistr('Nach dem <em>Import</em> einer Anwendung werden Automatisierungen <em>deaktiviert</em>, um zu verhindern, dass mehrere Automatisierungen gleichzeitig ausgef\00FChrt werden. Die Automatisierung muss entweder auf dieser Seite oder mit dem Package <strong>A')
||'PEX_AUTOMATION</strong> explizit aktiviert werden.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
