'                    :P7021_FUNCTION_BODY_LANGUAGE := :P7021_POST_PROC_FUNC_BODY_LANG;',
'                end if;',
'            else',
'                 :P7021_SOURCE_POST_PROCESSING := null;',
'                 :P7021_FUNCTION_BODY_LANGUAGE := null;',
'            end if;',
'            :P7021_REMOTE_SERVER_ID           := null;',
'            :P7021_DOCUMENT_SOURCE_ID         := null;',
'            :P7021_INCLUDE_ROWID_COLUMN       := ''N'';',
'            :P7021_SOURCE_POST_PROCESSING     := nullif ( :P7021_SOURCE_POST_PROCESSING, ''NONE'' );',
'            :P7021_TABLE_USELOCALSYNCTABLE    := case',
'                                                 when wwv_flow_web_src_sync.sync_exists_for_array_column(',
'                                                          p_web_source_module_id => :P7021_WEB_SRC_MODULE_ID,',
'                                                          p_array_column_id      => :P7021_WEB_SRC_ARRAY_COL_ID ) = ''Y''',
'                                                 then coalesce(:P7021_USE_LOCAL_SYNC_TABLE,''N'')',
'                                                 end;',
'',
'        elsif :P7021_LOCATION = wwv_flow_exec_api.c_location_duality_view then',
'',
'            :P7021_WEB_SRC_ARRAY_COL_ID := :P7021_DVSRC_ARRAYCOL_ID;',
'            :P7021_DOCUMENT_SOURCE_ID   := :P7021_DUALITY_VIEW_ID;',
'',
'            if :P7021_DVPOST = ''WHERE_ORDER_BY_CLAUSE'' then',
