,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Beispiel 1: E-Mail senden. Hierbei wird davon ausgegangen, dass ein E-Mail-Template namens <strong>ORDER</strong> vorhanden ist, das Platzhalter aus dem ',
unistr('    Parameter <strong>p_placeholders</strong> enth\00E4lt.'),
'</p>',
'<pre>',
'begin',
'    apex_mail.send (',
'        p_template_static_id => ''ORDER'',',
'        p_placeholders       => ''{ "ORDER_NUMBER": '' || :ORDER_NUMBER ||',
'                                  ''"ORDER_DATE":"''   || to_char( :ORDER_DATE, ''YYYY-MM-DD'' ) || ''", ''',
'                                  ''"ORDER_TOTAL":''   || :ORDER_TOTAL || ',
'                                ''}'',',
'        p_to                 => ''some_user@somewhere.com'' );',
'end;',
'</pre>',
'<p>',
unistr('    Beispiel 2: Zeile in eine andere Tabelle einf\00FCgen. Wenn der Wert ":SAL" NULL ist, wird eine Warnmeldung in das Automatisierungslog geschrieben.'),
'</p>',
'<pre>',
'begin',
'    insert into other_table( empno, ename, sal )',
'                     values( :EMPNO, :ENAME, :SAL );',
'    if :SAL is null then',
'        apex_automation.log_warn( ''EMPNO '' || :EMPNO ||'' has a NULL Salary'');',
'    end if;',
'end;',
'</pre>'))
