wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409356763910720.4003)
,p_name=>'P7022_ACTION_TYPE'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1410170163910728.4003)
,p_item_source_plug_id=>wwv_flow_imp.id(1410170163910728.4003)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Typ'
,p_source=>'ACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''PROCESS.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'           and ( ( select wwv_flow_f4000_util.is_cloud',
'                     from sys.dual ) = ''Y''',
'                  or name != ''GEOCODING'' )',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id                   = to_number(:FB_FLOW_ID)',
'           and security_group_id         = to_number(:WORKSPACE_ID)',
'           and plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('W\00E4hlen Sie den Typ der Aktion aus.')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409543908910722.4003)
,p_name=>'P7022_REMOTE_PLSQL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(90116067165448609.4003)
,p_prompt=>unistr('PL/SQL-Code (wird im REST-f\00E4higen SQL-Service ausgef\00FChrt)')
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie den auszuf\00FChrenden PL/SQL-Code an. Spaltenwerte aus der Automatisierungsabfrage sind als Bind-Variablen nach Spaltennamen verf\00FCgbar, z.B. <strong>:EMPNO</strong>, <strong>:ENAME</strong> usw. Dar\00FCber hinaus stellt APEX die folgenden, al')
||'lgemeinen Bind-Variablen bereit:',
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: Wenn eine Prim\00E4rschl\00FCsselspalte definiert wurde, enth\00E4lt diese Bind-Variable den Prim\00E4rschl\00FCsselwert.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: Bei auf einer Abfrage basierenden Automatisierungen enth\00E4lt diese Bind-Variable die aktuelle Zeilennummer.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: Bei auf einer Abfrage basierenden Automatisierungen enth\00E4lt diese Bind-Variable die Anzahl der Zeilen, bei denen w\00E4hrend der Aktionen Fehler aufgetreten sind.</li>'),
unistr('    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: Enth\00E4lt den Zeitstempel der <em>vorherigen</em> Automatisierungsausf\00FChrung im Format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
'</ul>',
'<p style="padding-top: 10px">',
unistr('    Beachten Sie, dass das <strong>APEX_AUTOMATION</strong>-Package f\00FCr den REST-f\00E4higen SQL-Service m\00F6glicherweise nicht verf\00FCgbar ist. Um dem Ausf\00FChrungslog Meldungen hinzuzuf\00FCgen (<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_E')
||unistr('RROR</strong>), erstellen Sie eine <em>weitere</em> Aktion, die in der <em>lokalen Datenbank</em> ausgef\00FChrt werden soll.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_05', 'P7022_REMOTE_SERVER_ID',
  'attribute_07', 'N')).to_clob
);
