wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6707661430580950.4003)
,p_plug_name=>'Info: JSON-Quellen'
,p_title=>'Info'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>60
,p_plug_display_point=>'REGION_POSITION_03'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    <strong>JSON-Quellen</strong> in &PRODUCT_NAME. bestehen aus Informationen zum Eigent\00FCmer und Namen '),
'    einer Datenbanktabelle. Dabei kann es sich um eine <em>JSON-Collection-Tabelle</em> oder eine einfache Tabelle handeln, deren Spalten',
unistr('    JSON-Daten enthalten. <em>JSON-Collection-Tabellen</em> sind in Oracle Database 23ai oder h\00F6her verf\00FCgbar. Dar\00FCber hinaus'),
'    wird ein <strong>Datenprofil</strong> verwaltet, das',
unistr('    JSON-Attribute f\00FCr die Nutzung durch &PRODUCT_NAME.-Komponenten <em>Spalten</em> zuordnet.'),
'</p>',
'<p> ',
unistr('    Sie k\00F6nnen eine JSON-Quelle mit der lokalen Datenbank sowie mit einem REST-f\00E4higen SQL-'),
'    Service definieren. Nach der Auswahl der zu verwendenden Tabelle und Spalte bestimmt &PRODUCT_NAME. das Datenprofil',
unistr('    entweder anhand der tats\00E4chlichen Daten oder anhand einer hochgeladenen <em>JSON-Schemadatei</em>.'),
'</p>',
'<p>',
unistr('    Nach der Erstellung ist die JSON-Quelle f\00FCr Seitenkomponenten wie <em>Berichte</em>, <em>Diagramme</em>, '),
unistr('    <em>Formulare</em> usw. sowie f\00FCr gemeinsame Komponenten wie <em>Wertelisten</em>, <em>Automatisierungen</em>'),
unistr('    usw. verf\00FCgbar. Das PL/SQL-Package APEX_EXEC erm\00F6glicht den programmgesteuerten Zugriff.'),
'</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P7100_SOURCE_TYPE'
,p_plug_display_when_cond2=>'JSON_TABLE'
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6708063614581792.4003)
,p_plug_name=>unistr('Info: Dualit\00E4ts-Views')
