,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    <strong>Dualit\00E4ts-Views</strong> in &PRODUCT_NAME. bestehen aus Informationen zum Eigent\00FCmer und Namen '),
unistr('    des Dualit\00E4ts-View-Objekts in der Oracle-Datenbank sowie einem <strong>Datenprofil</strong>. Das Datenprofil ordnet'),
unistr('    JSON-Attribute <em>Spalten</em> mit Datentypen zu, die von &PRODUCT_NAME.-Komponenten konsumiert werden k\00F6nnen.'),
'</p>',
'<p> ',
unistr('    Sie k\00F6nnen eine Dualit\00E4ts-View mit der lokalen Datenbank sowie mit einem REST-f\00E4higen SQL-Service'),
unistr('    definieren. Nach Auswahl der Dualit\00E4ts-View ruft &PRODUCT_NAME. ein JSON-Schema von'),
'    der Datenbank ab und erstellt das Datenprofil entsprechend.',
'</p>',
'<p>',
unistr('    Nach der Erstellung ist die Dualit\00E4ts-View f\00FCr Seitenkomponenten wie <em>Berichte</em>, <em>Diagramme</em>, '),
unistr('    <em>Formulare</em> usw. sowie f\00FCr gemeinsame Komponenten wie <em>Wertelisten</em>, <em>Automatisierungen</em>'),
unistr('    usw. verf\00FCgbar. Das PL/SQL-Package APEX_EXEC erm\00F6glicht den programmgesteuerten Zugriff.'),
'</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Weitere Informationen...</a></p>'))
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
