'                                                      when ''OTHER'' then :P7115_COPY_FROM_APPLICATION_ID',
'                                                  end,',
'                        p_to_application_id    => :FB_FLOW_ID,',
'                        p_document_source_id   => case :P7115_COPY_SOURCE',
'                                                      when ''THIS''  then :P7115_SRC_ID_THIS_APP',
'                                                      when ''OTHER'' then :P7115_SRC_ID_OTHER_APP',
'                                                  end,',
'                        p_to_name              => case when :P7115_SUBSCRIBE != ''Y'' then :P7115_JSON_SOURCE_NAME end,',
