wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4461407640614608.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Discover into JSON Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'    l_json_columns         wwv_flow_t_varchar2;',
'    l_json_schemas         wwv_flow_t_clob := wwv_flow_t_clob();',
'',
'    procedure load_column_and_json_schema(',
'        p_col_idx in pls_integer )',
'    is',
'        c_json_column   constant varchar2(128)   := wwv_flow_session_state.v( ''P7122_JSON_COLUMN_'' || p_col_idx );',
'        c_json_schema   constant varchar2(32767) := wwv_flow_session_state.v( ''P7122_JSON_SCHEMA_COLUMN_'' || p_col_idx );',
'',
'        l_file_content  blob;',
'    begin',
'        if c_json_column is not null then',
'            wwv_flow_string.push( l_json_columns, c_json_column );',
'',
'            if c_json_schema is not null then',
'',
'                select blob_content',
'                  into l_file_content',
'                  from wwv_flow_temp_files',
'                 where name = c_json_schema;',
'',
'                wwv_flow_string.push( l_json_schemas, wwv_flow_utilities.blob_to_clob(',
'                                                          p_blob       => l_file_content,',
'                                                          p_cache      => true,',
'                                                          p_dur        => sys.dbms_lob.call ) );',
'            else',
'',
'                wwv_flow_string.push( l_json_schemas, to_clob( null ) );',
'',
'            end if;',
'        end if;',
'    end load_column_and_json_schema;',
'begin',
'    wwv_flow_collection.create_or_truncate_collection( ''DATA_PROFILE'' );',
'',
'    load_column_and_json_schema( 1 );',
'    load_column_and_json_schema( 2 );',
'    load_column_and_json_schema( 3 );',
'',
'    wwv_flow_doc_src_dev.discover(',
'        p_source_type       => :P7120_SRC_TYPE,',
'        p_location          => :P7120_LOCATION,',
'        p_remote_server_id  => :P7120_REMOTE_SERVER_ID,',
'        p_object_owner      => :P7120_SRC_OWNER,',
'        p_object_name       => :P7120_SRC_NAME,',
'        p_json_columns      => l_json_columns,',
'        p_json_schemas      => l_json_schemas );',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Aufgrund des folgenden Fehlers konnte kein <em>Datenprofil</em> f\00FCr die neue &P7100_SOURCE_TYPE_TITLE_SIN. berechnet werden: #SQLERRM#.'),
'</p>',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4460458173614600.4003)
,p_internal_uid=>4461407640614608.4003
);
end;
