,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p />',
unistr('Gibt an, ob der Schutz f\00FCr den Sessionzustand aktiviert oder deaktiviert ist. Wenn Sie den Schutz aktiviert haben, verwendet dieses Feature die Seitenattribute f\00FCr <b>Schutz f\00FCr den Seitenzugriff</b> und die Elementattribute f\00FCr <b>Schutz f\00FCr den Ses')
||unistr('sionzustand</b> in Verbindung mit Pr\00FCfsummen in "f?p="-URLs. Dieses Feature verhindert, dass unberechtigte Benutzer die URLs und den Sessionzustand \00E4ndern bzw. aufrufen k\00F6nnen. '),
'<p />',
unistr('Wenn Sie dieses Feature deaktivieren, werden die Seiten- und Elementattribute zum Schutz f\00FCr den Sessionzustand ignoriert und keine Pr\00FCfsummen in generierte "f?p="-URLs einbezogen.')))
,p_encrypt_session_state_yn=>'N'
