,p_name=>'P9008_APPLICATION_SESSION_STATE_SECURITY'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(110814830114933628.4003)
,p_item_default=>'N'
,p_prompt=>unistr('Schutz f\00FCr den Sessionzustand:')
,p_source=>'select PAGE_PROTECTION_ENABLED_Y_N from wwv_flows where id = :fb_flow_id'
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cSize=>30
,p_cMaxlength=>2000
,p_cHeight=>1
,p_cAttributes=>'nowrap="nowrap"'
,p_tag_css_classes=>'fielddatabold'
,p_label_alignment=>'RIGHT'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4003)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Gibt an, ob der Schutz f\00FCr den Sessionzustand aktiviert oder deaktiviert ist. Wenn Sie den Schutz aktiviert haben, verwendet dieses Feature die Seitenattribute f\00FCr <b>Schutz f\00FCr den Seitenzugriff</b> und die Elementattribute f\00FCr <b>Schutz f\00FCr den Ses')
||unistr('sionzustand</b> in Verbindung mit Pr\00FCfsummen in "f?p="-URLs. Dieses Feature verhindert, dass unberechtigte Benutzer die URLs und den Sessionzustand \00E4ndern bzw. aufrufen k\00F6nnen. '),
'<p />',
unistr('Wenn Sie dieses Feature deaktivieren, werden die Seiten- und Elementattribute zum Schutz f\00FCr den Sessionzustand ignoriert und keine Pr\00FCfsummen in generierte "f?p="-URLs einbezogen.')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(110698229152438343.4003)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set session state security Standard'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select 1 from wwv_flows where id = :FB_FLOW_ID ',
'  and nvl(page_protection_enabled_y_n,''N'') = ''Y'' ) loop',
'    update wwv_flows set page_protection_enabled_y_n = ''N'' ',
'          where id = :FB_FLOW_ID ',
'          and security_group_id = wwv_flow_security.g_security_group_id;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Fehler beim Deaktivieren des Schutzes f\00FCr den Zustand der Anwendungssession.')
,p_process_when_button_id=>wwv_flow_imp.id(109524628805275296.4003)
,p_process_success_message=>unistr('Schutz f\00FCr den Sessionzustand der Anwendung wurde deaktiviert.')
,p_internal_uid=>110698229152438343.4003
);
end;
