,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.ID,',
'       t.FLOW_ID,',
'       t.NAME,',
'       t.STATIC_ID,',
'       t.SUBJECT,',
'       t.TASK_TYPE,',
'       t.PRIORITY,',
'       t.TASK_DEF_COMMENT,',
'       t.LAST_UPDATED_BY,',
'       t.LAST_UPDATED_ON,',
'       (select count(a.ID) ',
'          from WWV_FLOW_TASK_DEF_ACTIONS a ',
'         where a.task_def_id=t.id) ACTIONS_COUNT,',
'       (select count(p.id) ',
'          from WWV_FLOW_TASK_DEF_PARAMS p ',
'         where p.task_def_id=t.id) PARAMS_COUNT,',
'       (select count(part.id) ',
'          from WWV_FLOW_TASK_DEF_PARTICIPANTS part ',
'         where part.task_def_id=t.id) PARTICIPANTS_COUNT',
'from WWV_FLOW_TASK_DEFS t where t.flow_id = :FB_FLOW_ID and t.security_group_id = :WORKSPACE_ID'))
