wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3201962690436619.4003)
,p_plug_name=>'Aufgabendefinitionen'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    <strong>Aufgabendefinitionen</strong> definieren die Eigenschaften einer Human Task.',
'    Sie werden dazu verwendet, Aufgabeninstanzen zu erstellen und dann die erforderliche',
unistr('    Aktion auszuf\00FChren (z.B. Genehmigen oder Ablehnen der Aufgabeninstanzen). Aufgaben k\00F6nnen'),
unistr('    au\00DFerdem beansprucht, freigegeben, delegiert und abgebrochen werden.'),
'</p>',
'<p>',
'    <strong>Aufgabendefinitionsteilnehmer</strong> definieren die Teilnehmer einer',
unistr('    Human Task, die Aktionen f\00FCr die Aufgabe ausf\00FChren k\00F6nnen. Teilnehmer haben den Typ'),
unistr('    <strong>Potenzieller Eigent\00FCmer</strong> oder <strong>Gesch\00E4ftsadministrator'),
'    </strong>.',
'</p>',
'<p>',
'    <strong>Aufgabendefinitionsparameter</strong> definieren die Parameter einer',
unistr('    Human Task. Sie sind in der Regel Attribute eines Datensatzsystems, f\00FCr'),
'    das die Aufgabe definiert wurde. Sie stellen die Payload der Aufgabe dar.',
'</p>',
'<p>',
unistr('    <strong>Aufgabendefinitionsaktionen</strong> werden einmal f\00FCr ein Ereignis ausgel\00F6st, das'),
