,p_lov=>'.'||wwv_flow_imp.id(2058881135907033)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4003)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Das Ereignis, f\00FCr das die Aktion ausgef\00FChrt wird. Aktionen k\00F6nnen f\00FCr folgende Ereignisse in der Aufgabe ausgef\00FChrt werden:'),
'<dl>',
'    <dt>Beanspruchen</dt>',
unistr('    <dd>Wenn die Aufgabe von einem potenziellen Eigent\00FCmer beansprucht wird. Bei Beanspruchung wechselt der Status einer Aufgabe von "Nicht zugeordnet" zu "Zugeordnet".</dd>'),
unistr('    <dt>Abschlie\00DFen</dt>'),
unistr('    <dd>Wenn die Aufgabe abgeschlossen wird. Dar\00FCber hinaus k\00F6nnen Sie bei einer Genehmigungsaufgabe festlegen, ob die Aktion nur beim Ergebnis "Genehmigt" oder "Abgelehnt" stattfindet.</dd>'),
'    <dt>Delegieren</dt>',
unistr('    <dd>Wenn die Aufgabe an einen anderen potenziellen Eigent\00FCmer der Aufgabe delegiert wird.</dd>'),
'    <dt>Kommentar aktualisieren</dt>',
unistr('    <dd>Wenn der Aufgabe ein Kommentar hinzugef\00FCgt wird.</dd>'),
unistr('    <dt>Priorit\00E4t aktualisieren</dt>'),
unistr('    <dd>Wenn die Priorit\00E4t der Aufgabe aktualisiert wird.</dd>'),
'    <dt>Parameter aktualisieren</dt>',
'    <dd>Wenn die Parameter der Aufgabe aktualisiert werden.</dd>',
'    <dt>Freigeben</dt>',
'    <dd>Wenn die Aufgabe freigegeben wird. Der Status der Aufgabe wechselt von "Zugeordnet" zu "Nicht zugeordnet".</dd>',
'    <dt>Abbrechen</dt>',
'    <dd>Wenn die Aufgabe abgebrochen wird, also kein Interesse an der Aufgabe mehr gezeigt wird.</dd>',
'    <dt>Erstellen</dt>',
'    <dd>Wenn die Aufgabe erstellt wird.</dd>',
'    <dt>Informationen anfordern</dt>',
'    <dd>Wenn Informationen vom Initiator der Aufgabe angefordert werden.</dd>',
'    <dt>Informationen weiterleiten</dt>',
'    <dd>Wenn Informationen vom Initiator an den Anforderer weitergeleitet werden.</dd>',
'    <dt>Vor Ablauf</dt>',
unistr('    <dd>Bevor das F\00E4lligkeitsdatum der Aufgabe erreicht wird und kurz vor Ablauf der Aufgabe. Ein ISO/SQL-Intervall muss angegeben werden.</dd>'),
'    <dt>Ablaufen</dt>',
unistr('    <dd>Wenn das F\00E4lligkeitsdatum der Aufgabe erreicht wird und die Aufgabe abl\00E4uft.</dd>'),
' </dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
