wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1974380900697179.4003)
,p_name=>'P9506_LOCAL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(92085503084145721.4003)
,p_prompt=>'Code'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4003)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Geben Sie den auszuf\00FChrenden PL/SQL-Code an. Spaltenwerte aus der Aktionsabfrage der Aufgabendefinition sind als Bind-Variablen nach Spaltennamen verf\00FCgbar, z.B. <strong>:EMPNO</strong>, <strong>:ENAME</strong> usw. Dar\00FCber hinaus stellt APEX die')
||' folgenden generischen Bind-Variablen bereit:',
'</p>',
'<ul>',
unistr('    <li><strong>APEX$TASK_PK</strong>: Wenn eine Prim\00E4rschl\00FCsselspalte definiert wurde, enth\00E4lt diese Bind-Variable den Prim\00E4rschl\00FCsselwert.</li>'),
unistr('    <li><strong>APEX$TASK_ID</strong>: Diese Bind-Variable enth\00E4lt die ID der Aufgabe, f\00FCr die diese Aktion definiert ist.</li>'),
unistr('    <li><strong>APEX$TASK_SUBJECT</strong>: Diese Bind-Variable enth\00E4lt das Thema der Aufgabe, f\00FCr die diese Aktion definiert ist.</li>'),
unistr('    <li><strong>APEX$TASK_STATE</strong>: Diese Bind-Variable enth\00E4lt den aktuellen Status der Aufgabe, f\00FCr die diese Aktion definiert ist.</li>'),
unistr('    <li><strong>APEX$TASK_OUTCOME</strong>: Diese Bind-Variable enth\00E4lt das Ergebnis der Aufgabe, f\00FCr die diese Aktion definiert ist. Diese Variable wird nur f\00FCr Aufgaben im Status <strong>Abgeschlossen</strong> aufgef\00FCllt.</li>'),
unistr('    <li><strong>APEX$TASK_CREATED_ON</strong>: Enth\00E4lt den Zeitstempel der Aufgabenerstellung im Format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_INITIATOR</strong>: Enth\00E4lt den Benutzer, der die Aufgabe initiiert hat. Hier wird standardm\00E4\00DFig der angemeldete Benutzer verwendet, wenn der Wert nicht explizit im Seitenprozess <strong>Human Task - Erstellen</strong> angeg')
||'eben wird.</li>        ',
unistr('    <li><strong>APEX$TASK_DUE_ON</strong>: Enth\00E4lt den Zeitstempel der F\00E4lligkeit dieser Aufgabe im Format <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_OWNER</strong>: Enth\00E4lt den Benutzer, dem die Aufgabe derzeit zugewiesen ist.</li>'),
unistr('    <li> Die Parameter f\00FCr die Aufgabendefinition sind ebenfalls als Bind-Variablen verf\00FCgbar.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
