wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(228259524730656176.4003)
,p_plug_name=>unistr('Services f\00FCr generative KI')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4003)
,p_plug_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Informationen zu Services f\00FCr generative KI werden als Objekt des Typs <strong>Generative KI</strong> gespeichert. Services f\00FCr generative KI bieten eine Abstraktion g\00E4ngiger '),
unistr(' kommerzieller Produkte f\00FCr generative KI, wie Open AI, Cohere usw. Die \00F6ffentliche API <code>APEX_AI</code> referenziert die hier konfigurierten Services f\00FCr generative KI.</p>'),
unistr('<p>Services f\00FCr generative KI werden auf Workspace-Ebene gespeichert und sind daher in allen Anwendungen sichtbar. Beim Exportieren einer Anwendung werden die verwendeten Services f\00FCr generative KI der Exportdatei hinzugef\00FCgt. Beim Importieren der An')
||unistr('wendung in einen anderen Workspace pr\00FCft &PRODUCT_NAME., ob der Ziel-Workspace bereits Services f\00FCr generative KI mit derselben <strong>statischen ID</strong> enth\00E4lt. Wenn bereits ein Service f\00FCr generative KI vorhanden ist, verwendet die Anwendung ')
||unistr('diesen. Andernfalls werden die Services f\00FCr generative KI aus der Importdatei im Ziel-Workspace erstellt.</p>')))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(715109030894818867.4003)
,p_plug_name=>'Weitere Informationen'
,p_region_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="padding: 0 12px 12px 12px;"'
,p_plug_template=>wwv_flow_imp.id(208928010704475743.4003)
